/// the per-object locked delete sections of objects in different leaves overlap in time.
///
/// The claim is about the dispatcher production uses, so the test drives
/// [`run_leaf_groups`] at [`LEAF_CONCURRENCY_LIMIT`] with one object per leaf group — the shape
/// `batch_evict_ranges` is called in from both the legacy pass and the work-list executor — and
/// observes the holds from inside `DiskCacheManager::delete_ranges_under_slot_lock` itself.
///
/// Three things would make it vacuous, and each is dealt with:
///
/// - **Fewer objects than the limit.** It uses exactly `LEAF_CONCURRENCY_LIMIT` objects and
///   asserts the peak equals that, so a dispatcher that holds any fewer in flight fails.
/// - **Zero-latency file operations.** Unlinking a 2 KiB file on a local filesystem takes
///   microseconds, so 32 serial holds can finish inside one scheduler tick. Each hold is
///   therefore held open for `DWELL` from inside the locked section.
/// - **Two objects sharing a metadata slot**, which would serialise that pair however the work
///   is dispatched. The keys are chosen for distinct slots through
///   `metadata_lock_manager::slot_for_cache_key`, the function the acquisition itself uses.
#[cfg(test)]
mod locked_delete_concurrency_tests {
    use super::{run_leaf_groups, EvictionLeaf, LEAF_CONCURRENCY_LIMIT};
    use crate::cache_types::{CompressionInfo, NewCacheMetadata, ObjectMetadata, RangeSpec};
    use crate::compression::CompressionAlgorithm;
    use crate::disk_cache::locked_delete_observer;
    use std::time::{Duration, SystemTime};

    const RANGE_BYTES: u64 = 2048;
    const PREFIX: &str = "case12-overlap/";
    /// Long enough that 32 serial holds (4.8 s) and 32 concurrent ones (150 ms) cannot be
    /// confused, short enough that the test is quick when the code is right.
    const DWELL: Duration = Duration::from_millis(150);

    fn disk(cache_dir: &std::path::Path) -> crate::disk_cache::DiskCacheManager {
        crate::disk_cache::DiskCacheManager::new(
            cache_dir.to_path_buf(),
            true,
            4096,
            false,
            1_048_576,
        )
    }

    /// `LEAF_CONCURRENCY_LIMIT` cache keys that take distinct metadata slots, so no pair of them
    /// is serialised by the lock rather than by the dispatcher.
    fn distinct_slot_keys(cache_dir: &std::path::Path) -> Vec<String> {
        let mut keys = Vec::new();
        let mut slots = std::collections::HashSet::new();
        for i in 0..100_000 {
            if keys.len() == LEAF_CONCURRENCY_LIMIT {
                break;
            }
            let key = format!("{PREFIX}bucket/object-{i}.bin");
            let slot = crate::metadata_lock_manager::slot_for_cache_key(&key);
            if slots.insert(slot) {
                keys.push(key);
            }
        }
        assert_eq!(
            keys.len(),
            LEAF_CONCURRENCY_LIMIT,
            "fixture: could not find {LEAF_CONCURRENCY_LIMIT} keys with distinct slots"
        );
        let _ = cache_dir;
        keys
    }

    /// One single-range object: its `.bin` on disk and a `.meta` listing it.
    fn publish(cache_dir: &std::path::Path, key: &str) {
        let dc = disk(cache_dir);
        let (start, end) = (0, RANGE_BYTES - 1);
        let bin = dc.get_new_range_file_path(key, start, end);
        std::fs::create_dir_all(bin.parent().unwrap()).unwrap();
        std::fs::write(&bin, vec![0x5a; RANGE_BYTES as usize]).unwrap();
        let created_at = SystemTime::now() - Duration::from_secs(600);
        let metadata = NewCacheMetadata {
            cache_key: key.to_string(),
            object_metadata: ObjectMetadata {
                etag: "\"case12\"".to_string(),
                last_modified: "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
                content_length: RANGE_BYTES,
                ..Default::default()
            },
            ranges: vec![RangeSpec {
                start,
                end,
                file_path: bin
                    .strip_prefix(cache_dir.join("ranges"))
                    .unwrap()
                    .to_string_lossy()
                    .to_string(),
                compression_algorithm: CompressionAlgorithm::None,
                compressed_size: RANGE_BYTES,
                uncompressed_size: RANGE_BYTES,
                created_at,
                last_accessed: created_at,
                access_count: 1,
                staged: Some(false),
                unservable: false,
                file_identity: None,
            }],
            created_at,
            expires_at: created_at + Duration::from_secs(3600),
            compression_info: CompressionInfo::default(),
            ..Default::default()
        };
        let meta = dc.get_new_metadata_file_path(key);
        std::fs::create_dir_all(meta.parent().unwrap()).unwrap();
        std::fs::write(&meta, serde_json::to_string_pretty(&metadata).unwrap()).unwrap();
    }

    #[tokio::test]
    async fn locked_sections_of_many_objects_overlap_in_time() {
        let temp = tempfile::TempDir::new().unwrap();
        for sub in ["metadata", "ranges", "locks"] {
            std::fs::create_dir_all(temp.path().join(sub)).unwrap();
        }
        let keys = distinct_slot_keys(temp.path());
        for key in &keys {
            publish(temp.path(), key);
        }

        let groups: Vec<(EvictionLeaf, Vec<String>)> = keys
            .iter()
            .map(|k| (EvictionLeaf::of_cache_key(k), vec![k.clone()]))
            .collect();
        assert_eq!(
            groups.len(),
            LEAF_CONCURRENCY_LIMIT,
            "fixture: one object per leaf group, as many groups as the limit"
        );

        locked_delete_observer::arm(PREFIX, DWELL);
        let dc = disk(temp.path());
        let outcomes = tokio::time::timeout(
            Duration::from_secs(60),
            run_leaf_groups(groups, LEAF_CONCURRENCY_LIMIT, |_leaf, key: String| {
                let dc = &dc;
                async move { dc.batch_delete_ranges(&key, &[(0, RANGE_BYTES - 1)]).await }
            }),
        )
        .await
        .expect("the deletions must finish inside the bound");
        let (observed, peak) = locked_delete_observer::observed_and_peak_overlap();
        locked_delete_observer::disarm();

        for outcome in &outcomes {
            let deletion = outcome.as_ref().expect("each delete must succeed");
            assert_eq!(
                deletion.unlinked_extents.len(),
                1,
                "fixture: each object's one range must have been unlinked"
            );
        }
        assert_eq!(
            observed, LEAF_CONCURRENCY_LIMIT,
            "fixture: every object's locked section must have been observed"
        );
        assert_eq!(
            peak, LEAF_CONCURRENCY_LIMIT,
            "the locked delete sections of {LEAF_CONCURRENCY_LIMIT} objects in distinct leaves \
             and distinct metadata slots must be open at the same instant; peak was {peak}. A \
             peak of 1 means the section runs on the dispatching task, where one synchronous \
             step blocks every sibling leaf group"
        );
    }
}

/// Eviction and the entry reclaim select candidates from a `.meta` read taken without
/// the key's slot lock, then delete at version-independent paths. A peer that re-PUTs the key at
/// the same extent in that gap must keep its new `.bin` and `.meta`, and nothing may be debited
/// for it. The re-check lives in `DiskCacheManager::batch_delete_ranges_expecting`.
#[cfg(test)]
mod eviction_delete_identity_tests {
    use super::*;
    use crate::cache_types::{CompressionInfo, NewCacheMetadata, ObjectMetadata, RangeSpec};
    use crate::compression::CompressionAlgorithm;

    const RANGE_BYTES: u64 = 2048;
    const KEY: &str = "test-bucket/edi-object.bin";

    async fn setup(cache_dir: &std::path::Path) -> CacheManager {
        for sub in ["metadata/_journals", "size_tracking", "locks", "ranges"] {
            std::fs::create_dir_all(cache_dir.join(sub)).unwrap();
        }
        let manager = CacheManager::new_with_shared_storage(
            cache_dir.to_path_buf(),
            false,
            0,
            10 * 1024 * 1024 * 1024,
            CacheEvictionAlgorithm::TinyLFU,
            1024,
            true,
            std::time::Duration::from_secs(315360000),
            std::time::Duration::from_secs(3600),
            std::time::Duration::from_secs(3600),
            false,
            crate::config::SharedStorageConfig::default(),
            10.0,
            true,
            std::time::Duration::from_secs(86400),
            crate::config::MetadataCacheConfig::default(),
            95,
            80,
            true,
            std::time::Duration::from_secs(60),
            1_048_576,
            false,
            std::time::Duration::from_secs(10),
            64,
            std::time::Duration::from_secs(5),
        );
        let _ = manager.create_configured_disk_cache_manager();
        manager
            .initialize()
            .await
            .expect("initialize() must succeed");
        manager
    }

    fn disk(cache_dir: &std::path::Path) -> crate::disk_cache::DiskCacheManager {
        crate::disk_cache::DiskCacheManager::new(
            cache_dir.to_path_buf(),
            true,
            4096,
            false,
            1_048_576,
        )
    }

    /// Publish one version of `KEY`: a one-range `.meta` plus its `.bin` filled with `fill`, at
    /// the extent `batch_delete_ranges` unlinks. Returns the document as written.
    fn publish(
        cache_dir: &std::path::Path,
        etag: &str,
        created_at: SystemTime,
        staged: bool,
        fill: u8,
    ) -> NewCacheMetadata {
        let dc = disk(cache_dir);
        let (start, end) = (0, RANGE_BYTES - 1);
        let bin = dc.get_new_range_file_path(KEY, start, end);
        std::fs::create_dir_all(bin.parent().unwrap()).unwrap();
        std::fs::write(&bin, vec![fill; RANGE_BYTES as usize]).unwrap();
        let old = created_at - Duration::from_secs(600);
        let object_metadata = ObjectMetadata {
            etag: etag.to_string(),
            last_modified: "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
            content_length: RANGE_BYTES,
            is_write_cached: staged,
            ..Default::default()
        };
        let metadata = NewCacheMetadata {
            cache_key: KEY.to_string(),
            object_metadata,
            ranges: vec![RangeSpec {
                start,
                end,
                file_path: bin
                    .strip_prefix(cache_dir.join("ranges"))
                    .unwrap()
                    .to_string_lossy()
                    .to_string(),
                compression_algorithm: CompressionAlgorithm::None,
                compressed_size: RANGE_BYTES,
                uncompressed_size: RANGE_BYTES,
                created_at,
                last_accessed: old,
                access_count: 1,
                staged: Some(staged),
                unservable: false,
                file_identity: None,
            }],
            created_at,
            expires_at: created_at + Duration::from_secs(3600),
            compression_info: CompressionInfo::default(),
            ..Default::default()
        };
        let meta = dc.get_new_metadata_file_path(KEY);
        std::fs::create_dir_all(meta.parent().unwrap()).unwrap();
        std::fs::write(&meta, serde_json::to_string_pretty(&metadata).unwrap()).unwrap();
        metadata
    }

    /// Candidates the way `reclaim_whole_object` and the full collector build them: from a read
    /// of the document, carrying its identity.
    fn candidates_from(
        cache_dir: &std::path::Path,
        m: &NewCacheMetadata,
    ) -> Vec<RangeEvictionCandidate> {
        let identity = Arc::new(crate::disk_cache::ExpectedObjectIdentity::of(m));
        m.ranges
            .iter()
            .map(|r| RangeEvictionCandidate {
                cache_key: KEY.to_string(),
                range_start: r.start,
                range_end: r.end,
                last_accessed: r.last_accessed,
                size: r.compressed_size,
                compressed_size: r.compressed_size,
                access_count: r.access_count,
                bin_file_path: cache_dir.join("ranges").join(&r.file_path),
                is_write_cached: m.object_metadata.is_write_cached,
                staged: r.staged,
                expires_at: Some(m.expires_at),
                object_range_count: Some(m.ranges.len() as u64),
                identity: Some(identity.clone()),
            })
            .collect()
    }

    fn assert_peer_survived(cache_dir: &std::path::Path, peer: &NewCacheMetadata, fill: u8) {
        let dc = disk(cache_dir);
        let meta = dc.get_new_metadata_file_path(KEY);
        let bin = dc.get_new_range_file_path(KEY, 0, RANGE_BYTES - 1);
        let on_disk: NewCacheMetadata = serde_json::from_str(
            &std::fs::read_to_string(&meta).expect("the peer's .meta must survive the delete"),
        )
        .unwrap();
        assert_eq!(
            crate::disk_cache::ExpectedObjectIdentity::of(&on_disk),
            crate::disk_cache::ExpectedObjectIdentity::of(peer),
            "the .meta on disk must still be the peer's version"
        );
        assert_eq!(on_disk.ranges.len(), 1, "the peer's range must stay listed");
        let body = std::fs::read(&bin).expect("the peer's .bin must survive the delete");
        assert!(
            body.iter().all(|b| *b == fill),
            "the .bin must still hold the peer's bytes"
        );
    }

    /// A read-tier candidate is selected, then a peer publishes a STAGED write-cached version at
    /// the same extent with the same ETag (a same-content re-PUT) before the delete. Nothing may
    /// be deleted and nothing reported for debit.
    #[tokio::test]
    async fn staged_same_extent_republish_after_selection_is_not_deleted() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path()).await;
        let t1 = SystemTime::now() - Duration::from_secs(300);
        let selected = publish(temp.path(), "\"same\"", t1, false, 0x11);
        let candidates = candidates_from(temp.path(), &selected);

        let peer = publish(
            temp.path(),
            "\"same\"",
            t1 + Duration::from_secs(60),
            true,
            0x22,
        );

        let out = manager.batch_evict_ranges(KEY, &candidates).await.unwrap();

        assert!(
            out.identity_skipped,
            "the delete must see the .meta changed since selection and skip the key"
        );
        assert!(out.unlinked.is_empty(), "nothing may be reported for debit");
        assert_eq!(out.bytes_freed, 0, "no bytes may be reported freed");
        assert!(!out.meta_unlinked);
        assert_peer_survived(temp.path(), &peer, 0x22);
    }

    /// Same, for a non-staged re-PUT with a new ETag.
    #[tokio::test]
    async fn unstaged_new_etag_republish_after_selection_is_not_deleted() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path()).await;
        let t1 = SystemTime::now() - Duration::from_secs(300);
        let selected = publish(temp.path(), "\"v1\"", t1, false, 0x11);
        let candidates = candidates_from(temp.path(), &selected);

        let peer = publish(
            temp.path(),
            "\"v2\"",
            t1 + Duration::from_secs(60),
            false,
            0x33,
        );

        let out = manager.batch_evict_ranges(KEY, &candidates).await.unwrap();

        assert!(out.identity_skipped, "a new ETag must skip the key");
        assert!(out.unlinked.is_empty(), "nothing may be reported for debit");
        assert_eq!(out.bytes_freed, 0);
        assert_peer_survived(temp.path(), &peer, 0x33);
    }

    /// Positive control: a matching identity still deletes, and the debit figures come from the
    /// locked read rather than from the candidate (whose `compressed_size` is made stale here).
    #[tokio::test]
    async fn matching_identity_still_deletes_and_reports_locked_figures() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path()).await;
        let t1 = SystemTime::now() - Duration::from_secs(300);
        let selected = publish(temp.path(), "\"v1\"", t1, false, 0x11);
        let mut candidates = candidates_from(temp.path(), &selected);
        candidates[0].compressed_size = 1;
        candidates[0].size = 1;

        let out = manager.batch_evict_ranges(KEY, &candidates).await.unwrap();

        assert!(
            !out.identity_skipped,
            "an unchanged .meta must not be skipped"
        );
        assert!(out.meta_unlinked, "the whole object must be removed");
        assert_eq!(out.bytes_freed, RANGE_BYTES);
        assert_eq!(out.unlinked.len(), 1);
        assert_eq!(
            out.unlinked[0].compressed_size, RANGE_BYTES,
            "the debit figure must be the locked read's compressed_size, not the candidate's"
        );
        assert!(!out.unlinked[0].staged);
        let dc = disk(temp.path());
        assert!(!dc.get_new_metadata_file_path(KEY).exists());
        assert!(!dc.get_new_range_file_path(KEY, 0, RANGE_BYTES - 1).exists());
    }

    /// Candidates without an identity (fixtures, any caller that did not read a document) keep
    /// the unchecked behaviour.
    #[tokio::test]
    async fn candidates_without_identity_delete_unchecked() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path()).await;
        let t1 = SystemTime::now() - Duration::from_secs(300);
        let selected = publish(temp.path(), "\"v1\"", t1, false, 0x11);
        let mut candidates = candidates_from(temp.path(), &selected);
        candidates[0].identity = None;
        let _peer = publish(
            temp.path(),
            "\"v2\"",
            t1 + Duration::from_secs(60),
            false,
            0x33,
        );

        let out = manager.batch_evict_ranges(KEY, &candidates).await.unwrap();

        assert!(!out.identity_skipped);
        assert_eq!(out.unlinked.len(), 1);
    }

    // ── a writer's `.bin` rename versus an eviction holding the slot lock ──────────────
    //
    // Each test publishes v1, selects eviction candidates from it, then runs a writer for v2 at
    // the same extent. The writer pauses right after its `.bin` rename
    // (`range_rename_pause::after_rename`); the eviction runs during the pause, and the writer
    // resumes 300 ms later. With the rename inside the writer's slot-lock hold, the eviction
    // waits for the hold and then sees v2, so it skips. With the rename before the hold, the
    // eviction reads v1, passes its identity check and unlinks v2's `.bin`, and the writer then
    // publishes a `.meta` naming a missing file.

    fn v2_object_metadata(staged: bool) -> ObjectMetadata {
        ObjectMetadata {
            etag: "\"v2\"".to_string(),
            last_modified: "Thu, 22 Oct 2015 07:28:00 GMT".to_string(),
            content_length: RANGE_BYTES,
            is_write_cached: staged,
            ..Default::default()
        }
    }

    /// Drive `writer` and an eviction of `candidates` through the pause. Returns the eviction's
    /// outcome.
    async fn race_eviction_against<F>(
        manager: &CacheManager,
        candidates: &[RangeEvictionCandidate],
        writer: F,
    ) -> BatchEviction
    where
        F: std::future::Future<Output = Result<()>>,
    {
        // The pause registry is keyed by cache key and every test here uses `KEY`, so the race
        // tests take turns: a concurrent test's writer would otherwise consume this arming.
        static SERIAL: tokio::sync::Mutex<()> = tokio::sync::Mutex::const_new(());
        let _serial = SERIAL.lock().await;
        let pause = crate::disk_cache::range_rename_pause::arm(KEY);
        let reached = pause.reached.clone();
        let resume = pause.resume.clone();
        let evict = async move {
            tokio::time::timeout(Duration::from_secs(10), reached.notified())
                .await
                .expect("the writer never reached its post-rename pause point");
            let (out, ()) = tokio::join!(manager.batch_evict_ranges(KEY, candidates), async {
                tokio::time::sleep(Duration::from_millis(300)).await;
                resume.notify_one();
            });
            out
        };
        let (written, evicted) = tokio::join!(writer, evict);
        written.expect("the writer must succeed");
        evicted.expect("the eviction must not error")
    }

    fn assert_v2_intact(cache_dir: &std::path::Path, out: &BatchEviction) {
        let dc = disk(cache_dir);
        let meta: NewCacheMetadata = serde_json::from_str(
            &std::fs::read_to_string(dc.get_new_metadata_file_path(KEY))
                .expect("the writer's .meta must exist"),
        )
        .unwrap();
        assert_eq!(meta.object_metadata.etag, "\"v2\"", "the .meta must be v2");
        let bin = cache_dir.join("ranges").join(&meta.ranges[0].file_path);
        assert!(
            bin.exists(),
            "the v2 .meta names {:?}, which an eviction of v1 unlinked",
            bin
        );
        assert!(
            out.identity_skipped && out.unlinked.is_empty(),
            "the eviction must see v2 under the lock and skip the key"
        );
    }

    /// Buffered write-through PUT (`store_put_as_write_cached_range_with_ttl`).
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn buffered_put_rename_is_inside_the_slot_lock_hold() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path()).await;
        let t1 = SystemTime::now() - Duration::from_secs(300);
        let selected = publish(temp.path(), "\"v1\"", t1, false, 0x11);
        let candidates = candidates_from(temp.path(), &selected);
        let body = vec![0x44u8; RANGE_BYTES as usize];
        let out = race_eviction_against(
            &manager,
            &candidates,
            manager.store_put_as_write_cached_range_with_ttl(
                KEY,
                &body,
                "\"v2\"".to_string(),
                "Thu, 22 Oct 2015 07:28:00 GMT".to_string(),
                None,
                HashMap::new(),
                Duration::from_secs(3600),
            ),
        )
        .await;
        assert_v2_intact(temp.path(), &out);
    }

    /// Streamed signed PUT: the sink's `finalize_unpublished` plus
    /// `store_streamed_write_cache_metadata`, as `run_streaming_cache_write` drives them.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn streamed_put_rename_is_inside_the_slot_lock_hold() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path()).await;
        let t1 = SystemTime::now() - Duration::from_secs(300);
        let selected = publish(temp.path(), "\"v1\"", t1, false, 0x11);
        let candidates = candidates_from(temp.path(), &selected);
        let mut sink = manager
            .open_write_cache_sink(KEY, RANGE_BYTES)
            .await
            .unwrap()
            .expect("capacity must admit the sink");
        sink.write(&vec![0x55u8; RANGE_BYTES as usize]).unwrap();
        let (range_spec, pending) = sink.finalize_unpublished().unwrap();
        let out = race_eviction_against(&manager, &candidates, async {
            manager
                .store_streamed_write_cache_metadata(
                    KEY,
                    range_spec,
                    v2_object_metadata(true),
                    Duration::from_secs(3600),
                    pending,
                    None,
                )
                .await
                .map(|_| ())
        })
        .await;
        drop(sink);
        assert_v2_intact(temp.path(), &out);
    }

    /// Full-object GET fill (`store_full_object_as_range_new`).
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn full_object_fill_rename_is_inside_the_slot_lock_hold() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path()).await;
        let t1 = SystemTime::now() - Duration::from_secs(300);
        let selected = publish(temp.path(), "\"v1\"", t1, false, 0x11);
        let candidates = candidates_from(temp.path(), &selected);
        let body = vec![0x66u8; RANGE_BYTES as usize];
        let out = race_eviction_against(
            &manager,
            &candidates,
            manager.store_full_object_as_range_new(KEY, &body, v2_object_metadata(false)),
        )
        .await;
        assert_v2_intact(temp.path(), &out);
    }

    /// One streamed PUT commit on `key`, as `run_streaming_cache_write` drives it.
    async fn streamed_commit(manager: &CacheManager, key: &str) -> Result<()> {
        let mut sink = manager
            .open_write_cache_sink(key, RANGE_BYTES)
            .await
            .unwrap()
            .expect("capacity must admit the sink");
        sink.write(&vec![0x77u8; RANGE_BYTES as usize]).unwrap();
        let (range_spec, pending) = sink.finalize_unpublished().unwrap();
        let out = manager
            .store_streamed_write_cache_metadata(
                key,
                range_spec,
                v2_object_metadata(true),
                Duration::from_secs(3600),
                pending,
                None,
            )
            .await
            .map(|_| ());
        drop(sink);
        out
    }

    /// concurrent streamed PUT commits whose shared-storage `.meta` write is slow do not
    /// take the runtime's workers. Four commits stall 1.5 s each inside the synchronous write
    /// on a two-worker runtime; an unrelated task, standing in for `/health`, must still run
    /// within 500 ms. Std channels and sleeps throughout, because a runtime whose workers are
    /// all blocked also stops its own timer.
    #[test]
    fn slow_commit_tails_leave_the_runtime_workers_free() {
        let rt = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        let temp = tempfile::TempDir::new().unwrap();
        let manager = Arc::new(rt.block_on(setup(temp.path())));
        super::commit_tail_seam::arm(temp.path(), Duration::from_millis(1500));

        let (done_tx, done_rx) = std::sync::mpsc::channel();
        for i in 0..4 {
            let manager = Arc::clone(&manager);
            let done_tx = done_tx.clone();
            rt.spawn(async move {
                let key = format!("test-bucket/case4-starve-{}.bin", i);
                let _ = done_tx.send(streamed_commit(&manager, &key).await);
            });
        }
        // Wait (on this std thread) until at least two commits, one per worker, are inside
        // their stalled `.meta` write; their setup before it takes a variable time.
        let start = std::time::Instant::now();
        while super::commit_tail_seam::REACHED.load(std::sync::atomic::Ordering::SeqCst) < 2 {
            assert!(
                start.elapsed() < Duration::from_secs(10),
                "fixture: no two commits reached the stalled write within 10 s"
            );
            std::thread::sleep(Duration::from_millis(5));
        }

        let (peer_tx, peer_rx) = std::sync::mpsc::channel();
        rt.spawn(async move {
            let _ = peer_tx.send(());
        });
        let peer = peer_rx.recv_timeout(Duration::from_millis(500));

        let mut results = Vec::new();
        for _ in 0..4 {
            results.push(done_rx.recv_timeout(Duration::from_secs(15)));
        }
        super::commit_tail_seam::clear(temp.path());
        assert!(
            peer.is_ok(),
            "STARVED: an unrelated task did not run within 500 ms while 4 slow commit tails ran on a 2-worker runtime: {:?}",
            peer
        );
        for r in results {
            let r = r.expect("a commit did not finish within 15 s");
            assert!(r.is_ok(), "commit failed: {:?}", r);
        }
        rt.shutdown_timeout(Duration::from_secs(5));
    }

    /// the commit tail's publish order. While the `.meta` write is in progress the new
    /// `.bin` is already renamed into place, no `.meta` names it yet, and the slot lock is
    /// held; once the commit returns the `.meta` names the `.bin` and the slot is free. So a
    /// reader never sees a `.meta` naming a `.bin` that is not yet renamed.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn the_streamed_commit_publishes_bin_then_meta_then_releases() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = Arc::new(setup(temp.path()).await);
        let mut sink = manager
            .open_write_cache_sink(KEY, RANGE_BYTES)
            .await
            .unwrap()
            .expect("capacity must admit the sink");
        sink.write(&vec![0x78u8; RANGE_BYTES as usize]).unwrap();
        let (range_spec, pending) = sink.finalize_unpublished().unwrap();
        let bin_path = temp.path().join("ranges").join(&range_spec.file_path);
        let meta_path = manager.get_new_metadata_file_path(KEY);
        assert!(
            !bin_path.exists(),
            "fixture: the .bin must not be published yet"
        );

        super::commit_tail_seam::arm(temp.path(), Duration::from_millis(600));
        let committing = {
            let manager = Arc::clone(&manager);
            tokio::spawn(async move {
                manager
                    .store_streamed_write_cache_metadata(
                        KEY,
                        range_spec,
                        v2_object_metadata(true),
                        Duration::from_secs(3600),
                        pending,
                        None,
                    )
                    .await
            })
        };
        tokio::time::sleep(Duration::from_millis(250)).await;
        let bin_during = bin_path.exists();
        let meta_during = meta_path.exists();
        let slot_during = crate::metadata_lock_manager::try_acquire_slot_lock(temp.path(), KEY);
        let slot_held_during = matches!(slot_during, Err(ProxyError::LockContention(_)));
        drop(slot_during);
        let out = committing.await.unwrap();
        super::commit_tail_seam::clear(temp.path());
        drop(sink);

        assert!(out.is_ok(), "commit failed: {:?}", out);
        assert!(
            bin_during,
            "the .bin was not renamed before the .meta write"
        );
        assert!(!meta_during, "a .meta existed before its write began");
        assert!(
            slot_held_during,
            "the slot lock was not held across the .meta write"
        );
        let meta: NewCacheMetadata =
            serde_json::from_str(&std::fs::read_to_string(&meta_path).unwrap()).unwrap();
        assert_eq!(
            temp.path().join("ranges").join(&meta.ranges[0].file_path),
            bin_path,
            "the .meta must name the renamed .bin"
        );
        assert!(
            crate::metadata_lock_manager::try_acquire_slot_lock(temp.path(), KEY).is_ok(),
            "the slot lock must be released once the commit returns"
        );
    }
}

/// byte eviction's post-lock re-read is projected by the pending delta files.
#[cfg(test)]
mod projected_size_reread_tests {
    use super::*;
    use crate::cache_types::{NewCacheMetadata, ObjectMetadata, RangeSpec};
    use tempfile::TempDir;

    const OBJECTS: u64 = 10;
    const OBJECT_BYTES: u64 = 100_000;
    const MAX: u64 = OBJECTS * OBJECT_BYTES;

    fn manager(cache_dir: &std::path::Path) -> CacheManager {
        for sub in ["metadata/_journals", "size_tracking", "locks", "ranges"] {
            std::fs::create_dir_all(cache_dir.join(sub)).unwrap();
        }
        let m = CacheManager::new_with_shared_storage(
            cache_dir.to_path_buf(),
            false,
            0,
            MAX,
            CacheEvictionAlgorithm::TinyLFU,
            1024,
            true,
            Duration::from_secs(315_360_000),
            Duration::from_secs(3600),
            Duration::from_secs(3600),
            false,
            crate::config::SharedStorageConfig::default(),
            10.0,
            false,
            Duration::from_secs(86_400),
            crate::config::MetadataCacheConfig::default(),
            95,
            80,
            true,
            Duration::from_secs(60),
            1_048_576,
            false,
            Duration::from_secs(10),
            64,
            Duration::from_secs(5),
        );
        let _ = m.create_configured_disk_cache_manager();
        m
    }

    fn key(i: u64) -> String {
        format!("test-bucket/case14-object-{i:02}")
    }

    fn plant(manager: &CacheManager, cache_dir: &std::path::Path, i: u64, at: SystemTime) {
        let cache_key = key(i);
        let ranges_base = cache_dir.join("ranges");
        let bin = crate::disk_cache::get_sharded_path(
            &ranges_base,
            &cache_key,
            &format!("_0-{}.bin", OBJECT_BYTES - 1),
        )
        .unwrap();
        std::fs::create_dir_all(bin.parent().unwrap()).unwrap();
        std::fs::write(&bin, vec![0u8; OBJECT_BYTES as usize]).unwrap();
        let rel = bin
            .strip_prefix(&ranges_base)
            .unwrap()
            .to_string_lossy()
            .to_string();
        let mut range = RangeSpec::new(
            0,
            OBJECT_BYTES - 1,
            rel,
            CompressionAlgorithm::None,
            OBJECT_BYTES,
            OBJECT_BYTES,
        );
        range.created_at = at;
        range.last_accessed = at;
        range.access_count = 1;
        range.staged = Some(false);
        let metadata = NewCacheMetadata {
            cache_key: cache_key.clone(),
            object_metadata: ObjectMetadata {
                content_length: OBJECT_BYTES,
                ..Default::default()
            },
            ranges: vec![range],
            created_at: at,
            expires_at: SystemTime::now() + Duration::from_secs(3600),
            ..Default::default()
        };
        let path = manager.get_new_metadata_file_path(&cache_key);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(&path, serde_json::to_string(&metadata).unwrap()).unwrap();
    }

    fn resident(manager: &CacheManager) -> Vec<u64> {
        (0..OBJECTS)
            .filter(|i| manager.get_new_metadata_file_path(&key(*i)).exists())
            .collect()
    }

    /// Two byte passes back to back under one manager, with no consolidation cycle between
    /// them. Pass 1 frees down to the 80% target and flushes its debit to a delta file before
    /// releasing the eviction lock; `size_state.json` still holds the pre-eviction figure.
    /// Pass 2 must see that debit and free nothing. Re-reading `size_state` alone, it computed
    /// the same `bytes_to_free` again and deleted the next-coldest objects, sentinel included.
    #[tokio::test]
    async fn a_second_pass_before_any_cycle_frees_nothing() {
        let temp = TempDir::new().unwrap();
        let dir = temp.path();
        let m = manager(dir);
        let consolidator = m
            .journal_consolidator
            .read()
            .await
            .clone()
            .expect("fixture: the consolidator must be wired");
        let now = SystemTime::now();
        for i in 0..OBJECTS {
            // Object 0 is the coldest.
            plant(&m, dir, i, now - Duration::from_secs(36_000 - i * 600));
        }
        consolidator
            .persist_size_state(&crate::journal_consolidator::SizeState {
                total_size: MAX,
                ..Default::default()
            })
            .await
            .unwrap();

        let freed_1 = m
            .enforce_disk_cache_limits_skip_consolidation()
            .await
            .unwrap();
        let after_1 = resident(&m);
        assert!(
            freed_1 >= MAX / 5,
            "fixture: pass 1 must free at least the 20% to the target, freed {freed_1}"
        );
        assert_eq!(
            consolidator.get_current_size().await,
            Some(MAX),
            "fixture: no cycle ran, so size_state still holds the pre-eviction figure"
        );
        let sentinel = *after_1
            .first()
            .expect("fixture: pass 1 must leave objects resident");

        let freed_2 = m
            .enforce_disk_cache_limits_skip_consolidation()
            .await
            .unwrap();
        let after_2 = resident(&m);
        assert!(
            after_2.contains(&sentinel),
            "pass 2 evicted the sentinel (object {sentinel}, the coldest survivor of pass 1): \
             it re-freed pass 1's amount from a re-read that omits pass 1's flushed debit. \
             pass 1 freed {freed_1}, pass 2 freed {freed_2}, resident after pass 1 \
             {after_1:?}, after pass 2 {after_2:?}"
        );
        assert_eq!(
            freed_2, 0,
            "pass 2 must free nothing: pass 1 freed {freed_1}"
        );
        assert_eq!(after_1, after_2);
    }
}

/// an invalidation (`invalidate_cache_hierarchy`, reached by every DELETE and
/// overwriting PUT) that removes a valid `.meta` debits `cached_objects` exactly once.
///
/// The object is credited through the production route: a hybrid `store_range` journals the
/// `Add`, and `run_consolidation_cycle` folds it into a new `.meta` and counts it
/// (`is_new_object`). After the invalidation a further cycle runs, so a debit owed to
/// consolidation would land before the assertion. The re-cache leg then shows the count
/// returns to one, not two, so the fix does not double-debit and consolidation does not
/// re-credit twice.
///
/// # RED SIDE
///
/// With the debit in `invalidate_cache_hierarchy` disabled, `cached_objects` stays 1 after
/// the DELETE and reaches 2 after the re-cache.
/// `cached_objects` means one per `.meta` file on the shared volume, the population the
/// full validation's census installs and the `st_size` fold's `entry_count` sum counts. So
/// after any mix of incremental creates and removals the live figure must equal both.
///
/// The fixture seeds ranged and HEAD-only documents, takes a full validation as the census
/// baseline, then runs every incremental credit and debit site this crate has for a `.meta`
/// appearing or being unlinked (multipart completion is pinned separately in
/// `signed_put_handler`, whose fixture it needs). Last, it reads the live figure, runs a
/// second full validation and a full fold, and asserts all three agree.
///
/// # RED SIDE
///
/// On the earlier tree the live figure is one below the census: the HEAD-only invalidation
/// and `remove_invalidated_range` leave it high (+2), and the zero-length PUT, the
/// full-object store and the zero-length full-object store are never credited (-3).
#[cfg(test)]
mod cached_objects_one_per_meta_tests {
    use super::zero_length_arm_orphan_tests::{
        incompressible_body, object_metadata, setup, BODY_LEN,
    };

    /// The published count after one consolidation cycle, which is when request-path credits
    /// and debits reach `size_state.json`.
    async fn cached_objects(manager: &super::CacheManager) -> u64 {
        let consolidator = manager
            .get_journal_consolidator()
            .await
            .expect("fixture: the consolidator must be wired");
        consolidator
            .run_consolidation_cycle()
            .await
            .expect("fixture: consolidation must not error");
        consolidator
            .load_size_state()
            .await
            .expect("fixture: size_state must load")
            .cached_objects
    }

    async fn consolidate(manager: &super::CacheManager) {
        manager
            .get_journal_consolidator()
            .await
            .unwrap()
            .run_consolidation_cycle()
            .await
            .expect("consolidation must not error");
    }

    async fn fill(manager: &super::CacheManager, key: &str, seed: u8, etag: &str) {
        let body = incompressible_body(seed);
        let mut disk_cache = manager.create_configured_disk_cache_manager();
        disk_cache
            .store_range(
                key,
                0,
                BODY_LEN as u64 - 1,
                &body,
                object_metadata(BODY_LEN as u64, etag),
                std::time::Duration::from_secs(315_360_000),
                true,
            )
            .await
            .expect("fixture: the fill must publish");
        consolidate(manager).await;
    }

    async fn head(manager: &super::CacheManager, key: &str) {
        let etag = format!("\"{key}-head\"");
        let headers = std::collections::HashMap::from([
            (String::from("content-type"), String::from("text/plain")),
            (String::from("etag"), etag.clone()),
        ]);
        manager
            .store_head_cache_entry_unified(
                key,
                headers,
                super::CacheMetadata {
                    etag,
                    last_modified: "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
                    content_length: BODY_LEN as u64,
                    part_number: None,
                    cache_control: None,
                    access_count: 0,
                    last_accessed: std::time::SystemTime::now(),
                },
            )
            .await
            .expect("fixture: the HEAD entry must store");
        consolidate(manager).await;
    }

    async fn put(manager: &super::CacheManager, key: &str, body: &[u8], etag: &str) {
        manager
            .store_put_as_write_cached_range_with_ttl(
                key,
                body,
                etag.to_string(),
                "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
                Some("application/octet-stream".to_string()),
                std::collections::HashMap::new(),
                std::time::Duration::from_secs(86_400),
            )
            .await
            .expect("fixture: the PUT must publish");
        consolidate(manager).await;
    }

    /// `.meta` files under `metadata/`, skipping `_`-prefixed state directories and temps.
    fn meta_files_on_disk(cache_dir: &std::path::Path) -> u64 {
        walkdir::WalkDir::new(cache_dir.join("metadata"))
            .into_iter()
            .filter_entry(|e| e.depth() == 0 || !e.file_name().to_string_lossy().starts_with('_'))
            .filter_map(|e| e.ok())
            .filter(|e| {
                e.file_type().is_file() && e.file_name().to_string_lossy().ends_with(".meta")
            })
            .count() as u64
    }

    #[tokio::test]
    async fn cached_objects_matches_the_census_after_incremental_changes() {
        let temp = tempfile::TempDir::new().unwrap();
        let dir = temp.path();
        let manager = setup(dir).await;
        let tracker = manager
            .get_size_tracker()
            .await
            .expect("fixture: the size tracker must be wired");

        // Seed N = 2 ranged and M = 2 HEAD-only documents, then census.
        fill(&manager, "case15-bucket/ranged-0.bin", 1, "\"case15-r0\"").await;
        fill(&manager, "case15-bucket/ranged-1.bin", 2, "\"case15-r1\"").await;
        head(&manager, "case15-bucket/head-0.bin").await;
        head(&manager, "case15-bucket/head-1.bin").await;
        tracker.perform_full_validation().await.unwrap();
        assert_eq!(
            cached_objects(&manager).await,
            4,
            "PRECONDITION: the census counts every .meta, ranged and HEAD-only"
        );

        // 1. Invalidate one HEAD-only and one ranged document.
        for key in ["case15-bucket/head-0.bin", "case15-bucket/ranged-0.bin"] {
            manager.invalidate_cache_hierarchy(key).await.unwrap();
            assert!(!manager.get_new_metadata_file_path(key).exists());
        }
        consolidate(&manager).await;

        // 2. A HEAD create, then a first range folded onto it.
        head(&manager, "case15-bucket/head-2.bin").await;
        let mut doc_etag = String::new();
        if let Ok(s) =
            std::fs::read_to_string(manager.get_new_metadata_file_path("case15-bucket/head-2.bin"))
        {
            let d: crate::cache_types::NewCacheMetadata = serde_json::from_str(&s).unwrap();
            doc_etag = d.object_metadata.etag;
        }
        fill(&manager, "case15-bucket/head-2.bin", 3, &doc_etag).await;

        // 3. A fold creating a document for an absent key.
        fill(&manager, "case15-bucket/ranged-3.bin", 4, "\"case15-r3\"").await;

        // 4. Write-cached PUTs (non-empty and zero-length) and full-object GET stores
        // (non-empty and zero-length).
        let mut body = incompressible_body(5);
        body.truncate(BODY_LEN / 4);
        put(&manager, "case15-bucket/put-0.bin", &body, "\"case15-p0\"").await;
        put(
            &manager,
            "case15-bucket/put-empty.bin",
            &[],
            "\"case15-pe\"",
        )
        .await;
        manager
            .store_full_object_as_range_new(
                "case15-bucket/full-0.bin",
                &incompressible_body(6),
                object_metadata(BODY_LEN as u64, "\"case15-f0\""),
            )
            .await
            .expect("fixture: the full-object store must publish");
        manager
            .store_full_object_as_range_new(
                "case15-bucket/full-empty.bin",
                &[],
                object_metadata(0, "\"case15-fe\""),
            )
            .await
            .expect("fixture: the zero-length full-object store must publish");
        consolidate(&manager).await;

        // 5. A `Remove` fold that empties a document (it stays, rangeless).
        let r1 = "case15-bucket/ranged-1.bin";
        let r1_doc: crate::cache_types::NewCacheMetadata = serde_json::from_str(
            &std::fs::read_to_string(manager.get_new_metadata_file_path(r1)).unwrap(),
        )
        .unwrap();
        let r1_range = r1_doc.ranges[0].clone();
        manager
            .get_journal_consolidator()
            .await
            .unwrap()
            .write_eviction_journal_entries(vec![(
                r1.to_string(),
                r1_range.start,
                r1_range.end,
                r1_range.compressed_size,
                r1_range.file_path.clone(),
            )])
            .await;
        consolidate(&manager).await;

        // 6. `remove_invalidated_range` of a document's last range unlinks the `.meta`.
        let r3 = "case15-bucket/ranged-3.bin";
        manager
            .create_configured_disk_cache_manager()
            .remove_invalidated_range(r3, 0, BODY_LEN as u64 - 1)
            .await
            .expect("remove_invalidated_range must not error");
        assert!(
            !manager.get_new_metadata_file_path(r3).exists(),
            "PRECONDITION: the last range's removal must unlink the .meta"
        );
        consolidate(&manager).await;

        let on_disk = meta_files_on_disk(dir);
        let live = cached_objects(&manager).await;

        tracker.perform_full_validation().await.unwrap();
        let census = cached_objects(&manager).await;

        assert_eq!(
            census, on_disk,
            "PRECONDITION: the census counts the .meta files on disk"
        );
        assert_eq!(
            live, census,
            "DRIFT: the live cached_objects ({live}) differs from the census \
             ({census}) after incremental creates and removals"
        );
    }
}

#[cfg(test)]
mod invalidation_cached_objects_count_tests {
    use super::zero_length_arm_orphan_tests::{
        incompressible_body, object_metadata, setup, BODY_LEN,
    };

    const KEY: &str = "case16-bucket/invalidated-object.bin";

    /// The published count after one consolidation cycle, which is when request-path credits
    /// and debits reach `size_state.json`.
    async fn cached_objects(manager: &super::CacheManager) -> u64 {
        let consolidator = manager
            .get_journal_consolidator()
            .await
            .expect("fixture: the consolidator must be wired");
        consolidator
            .run_consolidation_cycle()
            .await
            .expect("fixture: consolidation must not error");
        consolidator
            .load_size_state()
            .await
            .expect("fixture: size_state must load")
            .cached_objects
    }

    async fn fill_and_consolidate(manager: &super::CacheManager, seed: u8, etag: &str) {
        let body = incompressible_body(seed);
        let mut disk_cache = manager.create_configured_disk_cache_manager();
        disk_cache
            .store_range(
                KEY,
                0,
                BODY_LEN as u64 - 1,
                &body,
                object_metadata(BODY_LEN as u64, etag),
                std::time::Duration::from_secs(315_360_000),
                true,
            )
            .await
            .expect("fixture: the fill must publish");
        manager
            .get_journal_consolidator()
            .await
            .unwrap()
            .run_consolidation_cycle()
            .await
            .expect("consolidation must not error");
    }

    #[tokio::test]
    async fn a_delete_debits_cached_objects_once_and_a_recache_credits_once() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path()).await;
        let before = cached_objects(&manager).await;

        fill_and_consolidate(&manager, 61, "\"case16-v1\"").await;
        assert!(
            manager.get_new_metadata_file_path(KEY).exists(),
            "PRECONDITION: consolidation must have written the .meta"
        );
        assert_eq!(
            cached_objects(&manager).await,
            before + 1,
            "PRECONDITION: consolidation must credit the new object once"
        );

        manager
            .invalidate_cache_hierarchy(KEY)
            .await
            .expect("invalidation must not error");
        assert!(
            !manager.get_new_metadata_file_path(KEY).exists(),
            "PRECONDITION: the invalidation must have removed the .meta"
        );
        manager
            .get_journal_consolidator()
            .await
            .unwrap()
            .run_consolidation_cycle()
            .await
            .expect("consolidation must not error");
        assert_eq!(
            cached_objects(&manager).await,
            before,
            "OVER-COUNT: the DELETE removed the .meta but cached_objects was not debited"
        );

        fill_and_consolidate(&manager, 62, "\"case16-v2\"").await;
        assert_eq!(
            cached_objects(&manager).await,
            before + 1,
            "the re-cached object must be counted once in total"
        );
    }

    /// a write-through PUT publishes its `.meta` with the range already listed and
    /// journals no `Add`, so consolidation's `is_new_object` never credited it, while its
    /// invalidation debits it. The publish now credits it. Another object is counted
    /// first so an under-count is visible above the saturating decrement.
    ///
    /// # RED SIDE
    ///
    /// With `credit_put_cached_object` disabled the count after the PUT and fold is
    /// `base`, not `base + 1`, and the invalidation then takes it to `base - 1`.
    #[tokio::test]
    async fn a_write_cached_put_is_credited_once_and_its_invalidation_restores_the_count() {
        const PUT_KEY: &str = "case17-bucket/put-object.bin";
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path()).await;
        fill_and_consolidate(&manager, 65, "\"case17-other\"").await;
        let base = cached_objects(&manager).await;
        assert!(base >= 1, "PRECONDITION: another object is counted");

        let put = |seed: u8, len: usize, etag: &'static str| {
            let manager = &manager;
            async move {
                let mut body = incompressible_body(seed);
                body.truncate(len);
                manager
                    .store_put_as_write_cached_range_with_ttl(
                        PUT_KEY,
                        &body,
                        etag.to_string(),
                        "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
                        Some("application/octet-stream".to_string()),
                        std::collections::HashMap::new(),
                        std::time::Duration::from_secs(86_400),
                    )
                    .await
                    .expect("fixture: the PUT must publish");
                manager
                    .get_journal_consolidator()
                    .await
                    .unwrap()
                    .run_consolidation_cycle()
                    .await
                    .expect("consolidation must not error");
            }
        };

        put(66, BODY_LEN, "\"case17-v1\"").await;
        let doc: crate::cache_types::NewCacheMetadata = serde_json::from_str(
            &std::fs::read_to_string(manager.get_new_metadata_file_path(PUT_KEY)).unwrap(),
        )
        .unwrap();
        assert!(
            doc.object_metadata.is_write_cached && doc.ranges.len() == 1,
            "PRECONDITION: a write-cached document listing its range"
        );
        assert_eq!(
            cached_objects(&manager).await,
            base + 1,
            "UNCREDITED PUT: the write-cached PUT object was not counted in cached_objects"
        );

        // A length-changing re-PUT replaces a counted document: no second credit.
        put(67, BODY_LEN / 2, "\"case17-v2\"").await;
        assert_eq!(
            cached_objects(&manager).await,
            base + 1,
            "DOUBLE CREDIT: a re-PUT over a counted document credited it again"
        );

        manager
            .invalidate_cache_hierarchy(PUT_KEY)
            .await
            .expect("invalidation must not error");
        manager
            .get_journal_consolidator()
            .await
            .unwrap()
            .run_consolidation_cycle()
            .await
            .expect("consolidation must not error");
        assert_eq!(
            cached_objects(&manager).await,
            base,
            "the PUT object's invalidation must return cached_objects to its starting value"
        );
    }

    /// (replacing the earlier "leaves unchanged" rule): `cached_objects` counts one per
    /// `.meta` file, so a HEAD-only document (no ranges) is credited when it is created and
    /// debited once when it is invalidated. Another object is counted first so the count is
    /// above 0 and a double debit cannot hide behind the saturating decrement.
    #[tokio::test]
    async fn a_head_only_document_is_credited_once_and_its_invalidation_debits_once() {
        const HEAD_KEY: &str = "case18-bucket/head-only-object.bin";
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path()).await;
        fill_and_consolidate(&manager, 64, "\"case18-v1\"").await;
        let base = cached_objects(&manager).await;
        assert!(
            base >= 1,
            "PRECONDITION: the filled object must be counted, so a double debit is visible"
        );

        let headers = std::collections::HashMap::from([
            (String::from("content-type"), String::from("text/plain")),
            (String::from("etag"), String::from("\"case18-head\"")),
        ]);
        manager
            .store_head_cache_entry_unified(
                HEAD_KEY,
                headers,
                super::CacheMetadata {
                    etag: "\"case18-head\"".to_string(),
                    last_modified: "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
                    content_length: 4096,
                    part_number: None,
                    cache_control: None,
                    access_count: 0,
                    last_accessed: std::time::SystemTime::now(),
                },
            )
            .await
            .expect("fixture: the HEAD entry must store");
        manager
            .get_journal_consolidator()
            .await
            .unwrap()
            .run_consolidation_cycle()
            .await
            .expect("consolidation must not error");
        let head_meta_path = manager.get_new_metadata_file_path(HEAD_KEY);
        let head_doc: crate::cache_types::NewCacheMetadata =
            serde_json::from_str(&std::fs::read_to_string(&head_meta_path).unwrap()).unwrap();
        assert!(
            head_doc.ranges.is_empty(),
            "PRECONDITION: the HEAD entry must be a rangeless document"
        );
        assert_eq!(
            cached_objects(&manager).await,
            base + 1,
            "UNCREDITED HEAD: the HEAD-only .meta was not counted in cached_objects"
        );

        manager
            .invalidate_cache_hierarchy(HEAD_KEY)
            .await
            .expect("invalidation must not error");
        assert!(
            !head_meta_path.exists(),
            "PRECONDITION: the invalidation must have removed the HEAD-only .meta"
        );
        manager
            .get_journal_consolidator()
            .await
            .unwrap()
            .run_consolidation_cycle()
            .await
            .expect("consolidation must not error");
        assert_eq!(
            cached_objects(&manager).await,
            base,
            "the HEAD-only document's invalidation must debit it exactly once"
        );
    }

    /// The buffered reader's lookup-to-read gap: an extent marked `unservable`
    /// after `find_cached_ranges` chose it is still loaded by `load_range_data_with_cache`,
    /// the disk read behind `serve_range_from_cache_buffered` and the merge path.
    ///
    /// Both disk loaders (`RangeHandler::load_range_data_from_new_storage` and the RAM
    /// promotion's `load_range_frame_from_new_storage`) resolve the spec through
    /// `resolve_extent_spec_for_read`, which refuses a marked extent.
    #[tokio::test]
    async fn an_extent_marked_unservable_after_the_lookup_is_not_loaded() {
        use crate::range_handler::RangeHandler;
        use std::sync::Arc;
        let temp = tempfile::TempDir::new().unwrap();
        let manager = Arc::new(setup(temp.path()).await);
        fill_and_consolidate(&manager, 63, "\"case16-v1\"").await;

        let disk_cache = Arc::new(tokio::sync::RwLock::new(
            manager.create_configured_disk_cache_manager(),
        ));
        let range_handler = RangeHandler::new(manager.clone(), disk_cache);
        let overlap = range_handler
            .find_cached_ranges(
                KEY,
                &crate::range_handler::RangeSpec {
                    start: 0,
                    end: BODY_LEN as u64 - 1,
                },
                None,
                None,
                crate::cache_types::RangeLookupPurpose::FreshServe,
            )
            .await
            .expect("find_cached_ranges must not error");
        let range = overlap
            .cached_ranges
            .first()
            .cloned()
            .expect("PRECONDITION: the lookup must choose the consolidated extent");

        // What a consolidation's failed unlink does between the lookup and the read.
        let meta_path = manager.get_new_metadata_file_path(KEY);
        let mut meta: crate::cache_types::NewCacheMetadata =
            serde_json::from_str(&std::fs::read_to_string(&meta_path).unwrap()).unwrap();
        for r in meta.ranges.iter_mut() {
            r.unservable = true;
        }
        std::fs::write(&meta_path, serde_json::to_string(&meta).unwrap()).unwrap();

        let loaded = manager
            .load_range_data_with_cache(KEY, &range, &range_handler)
            .await;
        assert!(
            loaded.is_err(),
            "SERVED AN UNSERVABLE EXTENT: the buffered read loaded {} bytes from an extent \
             marked unservable after the lookup",
            loaded.map(|(d, _)| d.len()).unwrap_or(0)
        );
    }
}

/// The PUT-capacity figure is read narrowly and taken at startup.
///
/// `put_usage_figure` must equal `get_cache_size_stats().total_cache_size` in both
/// staged-authority epochs at non-zero `P`, and after `initialize()` plus
/// `start_put_usage_refresher()` the first `put_capacity_usage` must not wait on a read.
///
/// Spec: write-cache-accounting-and-eviction. Requirements: 8.3
#[cfg(test)]
mod put_usage_narrowed_read_tests {
    use super::*;

    const DISK_BYTES: u64 = 20_767_307_686;
    const INCUMBENT_BYTES: u64 = 7_777_777_777;
    const F_BYTES: u64 = 1_234_567_890;
    const P_BYTES: u64 = 98_765_432;

    fn setup(cache_dir: &std::path::Path) -> Arc<CacheManager> {
        for sub in ["metadata/_journals", "size_tracking", "locks", "ranges"] {
            std::fs::create_dir_all(cache_dir.join(sub)).unwrap();
        }
        let manager = Arc::new(CacheManager::new_with_eviction_algorithm(
            cache_dir.to_path_buf(),
            false,
            0,
            CacheEvictionAlgorithm::TinyLFU,
        ));
        let _ = manager.create_configured_disk_cache_manager();
        manager
    }

    async fn seed_total_size(manager: &CacheManager, total_size: u64) {
        let consolidator = manager.get_journal_consolidator().await.unwrap();
        let mut state = consolidator.load_size_state().await.unwrap();
        state.total_size = total_size;
        state.write_cache_size = INCUMBENT_BYTES;
        consolidator.persist_size_state(&state).await.unwrap();
    }

    fn seed_in_progress_part(cache_dir: &std::path::Path) {
        let dir = cache_dir.join("mpus_in_progress").join("mpu-live");
        std::fs::create_dir_all(&dir).unwrap();
        let info = crate::cache_types::CachedPartInfo::new(
            1,
            P_BYTES * 3,
            "\"etag-live\"".to_string(),
            crate::compression::CompressionAlgorithm::Lz4,
        )
        .with_compressed_size(P_BYTES);
        std::fs::write(
            dir.join("part1.json"),
            serde_json::to_string(&info).unwrap(),
        )
        .unwrap();
        assert_eq!(
            crate::signed_put_handler::in_progress_part_bytes(cache_dir),
            Some(P_BYTES),
            "fixture: P must be non-zero and readable, or the equality is vacuous"
        );
    }

    async fn stats_total(manager: &CacheManager) -> u64 {
        manager
            .get_cache_size_stats()
            .await
            .unwrap()
            .sizes
            .expect("get_cache_size_stats must always populate CacheSizes")
            .total_cache_size
    }

    /// Phase L: `P` is on disk and the fold has a figure, but neither path counts `P`.
    #[tokio::test(flavor = "multi_thread")]
    async fn narrowed_figure_equals_stats_total_in_phase_l() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path());
        seed_total_size(&manager, DISK_BYTES).await;
        seed_in_progress_part(temp.path());
        crate::staged_fold::seed_shard_figure_for_tests(
            temp.path(),
            "test-bucket",
            "3f",
            F_BYTES,
            9,
        );
        assert_eq!(
            crate::staged_authority::read_epoch(temp.path()),
            crate::staged_authority::EPOCH_LEGACY,
            "fixture: no epoch document means Phase L"
        );

        let narrowed = manager.put_usage_figure().await.unwrap();
        assert_eq!(narrowed, stats_total(&manager).await);
        assert_eq!(
            narrowed, DISK_BYTES,
            "Phase L: P must not be counted, as in the stats path's incumbent arm"
        );
    }

    /// Fold epoch: both paths report `total_size + P`.
    #[tokio::test(flavor = "multi_thread")]
    async fn narrowed_figure_equals_stats_total_in_fold_epoch() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path());
        seed_total_size(&manager, DISK_BYTES).await;
        seed_in_progress_part(temp.path());
        crate::staged_fold::seed_shard_figure_for_tests(
            temp.path(),
            "test-bucket",
            "3f",
            F_BYTES,
            9,
        );
        assert!(crate::staged_authority::activate(temp.path(), "host:test").unwrap());
        assert!(
            crate::staged_fold::staged_authority_figure(temp.path())
                .await
                .is_some(),
            "fixture: the fold figure must be readable so the stats path takes its fold arm"
        );

        let narrowed = manager.put_usage_figure().await.unwrap();
        assert_eq!(narrowed, stats_total(&manager).await);
        assert_eq!(
            narrowed,
            DISK_BYTES + P_BYTES,
            "fold epoch: the PUT figure is total_size + P"
        );
    }

    const S_BYTES: u64 = 1_048_576;
    const T_BYTES: u64 = 4_096;
    /// `(read_cache_size, write_cache_size, captured WARN output)` from one stats read, with
    /// the fold snapshot invalidated first so the read derives from the fixture as it is now.
    async fn stats_with_warns(manager: &CacheManager, dir: &std::path::Path) -> (u64, u64, String) {
        use tracing::instrument::WithSubscriber;
        #[derive(Clone)]
        struct Buffer(std::sync::Arc<std::sync::Mutex<Vec<u8>>>);
        impl std::io::Write for Buffer {
            fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
                self.0.lock().unwrap().extend_from_slice(buf);
                Ok(buf.len())
            }
            fn flush(&mut self) -> std::io::Result<()> {
                Ok(())
            }
        }
        crate::staged_fold::invalidate_authority_snapshot_for_tests(dir);
        let buf = Buffer(Default::default());
        let writer = buf.clone();
        let subscriber = tracing_subscriber::fmt()
            .with_ansi(false)
            .with_max_level(tracing::Level::WARN)
            .with_writer(move || writer.clone())
            .finish();
        let sizes = manager
            .get_cache_size_stats()
            .with_subscriber(subscriber)
            .await
            .unwrap()
            .sizes
            .expect("get_cache_size_stats must always populate CacheSizes");
        let out = String::from_utf8(buf.0.lock().unwrap().clone()).unwrap();
        (sizes.read_cache_size, sizes.write_cache_size, out)
    }
    /// Fold epoch, F = S staged plus T read-tier bytes in `total_size`, read once while
    /// consistent so the stats path holds a last consistent `read_cache_size` of T.
    async fn fold_epoch_read_once_consistent(dir: &std::path::Path) -> Arc<CacheManager> {
        let manager = setup(dir);
        seed_total_size(&manager, S_BYTES + T_BYTES).await;
        crate::staged_fold::seed_shard_figure_for_tests(dir, "test-bucket", "3f", S_BYTES, 1);
        assert!(crate::staged_authority::activate(dir, "host:test").unwrap());
        let (read, _, warns) = stats_with_warns(&manager, dir).await;
        assert_eq!(
            read, T_BYTES,
            "fixture: the consistent read is total_size - F"
        );
        assert!(!warns.contains("accounting inverted"), "fixture: {warns}");
        manager
    }
    /// A same-key re-PUT at epoch 1: `total_size` stays flat, F keeps the superseded copy and
    /// the new copy's credit sits above the cut, so R = 2S > total_size until the next visit.
    /// That is the design, so no WARN and no `read_cache_size` of 0; eviction still sees 2S.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_re_put_double_count_at_epoch_1_is_not_reported_as_inverted() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = fold_epoch_read_once_consistent(temp.path()).await;
        let credit = crate::staged_fold::PendingCredit {
            seq: 1,
            bucket: "test-bucket".to_string(),
            l1: "3f".to_string(),
            bytes: S_BYTES,
            range: Some(crate::staged_fold::PendingRange {
                cache_key: "test-bucket/k.bin".to_string(),
                start: 0,
                end: S_BYTES - 1,
            }),
        };
        crate::staged_fold::PendingStore::new(temp.path().to_path_buf())
            .append_batch("host:9", &[credit])
            .await
            .unwrap();
        let (read, write, warns) = stats_with_warns(&manager, temp.path()).await;
        assert!(
            write >= 2 * S_BYTES,
            "fixture: R must hold both copies, got write_cache_size {write}"
        );
        assert!(
            !warns.contains("accounting inverted"),
            "a designed re-PUT double count must not WARN: {warns}"
        );
        assert_eq!(
            read, T_BYTES,
            "read_cache_size must hold its last consistent value, not 0"
        );
    }
    /// A staged DELETE at epoch 1: `total_size` takes the debit, F keeps the deleted bytes and
    /// no credit explains them, so R = S > total_size = T until the next visit.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_staged_delete_excess_at_epoch_1_is_not_reported_as_inverted() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = fold_epoch_read_once_consistent(temp.path()).await;
        seed_total_size(&manager, T_BYTES).await;
        let (read, write, warns) = stats_with_warns(&manager, temp.path()).await;
        assert!(write >= S_BYTES, "fixture: F still holds S, got {write}");
        assert!(
            !warns.contains("accounting inverted"),
            "a designed DELETE excess must not WARN: {warns}"
        );
        assert_eq!(
            read, T_BYTES,
            "read_cache_size must hold its last consistent value, not 0"
        );
    }
    /// An excess unbroken for longer than the rotation bound is not the design: it WARNs and
    /// publishes 0, as every inversion did before.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_fold_excess_past_the_rotation_bound_still_warns() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = fold_epoch_read_once_consistent(temp.path()).await;
        seed_total_size(&manager, T_BYTES).await;
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        manager.staged_excess_since_secs.store(
            now - crate::staged_fold::RECLAIM_DOCUMENT_MAX_AGE_SECS - 1,
            std::sync::atomic::Ordering::Relaxed,
        );
        let (read, _, warns) = stats_with_warns(&manager, temp.path()).await;
        assert!(
            warns.contains("accounting inverted"),
            "an excess past the bound must WARN: {warns:?}"
        );
        assert_eq!(read, 0, "and publish read_cache_size 0");
        // The gauge keeps counting past the bound, where the guard has given up holding: a
        // gauge that cleared here would end the alarm exactly when the inversion is confirmed.
        crate::staged_fold::invalidate_authority_snapshot_for_tests(temp.path());
        let sizes = manager
            .get_cache_size_stats()
            .await
            .unwrap()
            .sizes
            .expect("get_cache_size_stats must always populate CacheSizes");
        assert!(
            sizes.read_cache_size_inverted_secs > crate::staged_fold::RECLAIM_DOCUMENT_MAX_AGE_SECS,
            "past the bound the gauge must keep counting, got {}",
            sizes.read_cache_size_inverted_secs
        );
    }
    /// An excess older than `MAX_AUTHORITY_AGE_SECS` but younger than the reclaim-document bound
    /// is still inside the rotation's worst case (a visit starts within the first and installs
    /// within the claim lease after it), so it holds the last consistent figure and does not WARN.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_fold_excess_between_the_authority_age_and_the_reclaim_bound_holds() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = fold_epoch_read_once_consistent(temp.path()).await;
        seed_total_size(&manager, T_BYTES).await;
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        manager.staged_excess_since_secs.store(
            now - crate::staged_fold::MAX_AUTHORITY_AGE_SECS - 450,
            std::sync::atomic::Ordering::Relaxed,
        );
        let (read, _, warns) = stats_with_warns(&manager, temp.path()).await;
        assert!(
            !warns.contains("accounting inverted"),
            "an excess inside the reclaim bound must not WARN: {warns:?}"
        );
        assert_eq!(
            read, T_BYTES,
            "and hold the last consistent read_cache_size"
        );
    }
    /// Inverted, consistent, inverted: the consistent read ends the first excess, so the second
    /// starts its age at 0. Without that reset every transient after the first one older than
    /// the bound would inherit its age and WARN at once.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_consistent_read_restarts_the_excess_clock() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = fold_epoch_read_once_consistent(temp.path()).await;
        seed_total_size(&manager, T_BYTES).await;
        let (read, _, warns) = stats_with_warns(&manager, temp.path()).await;
        assert!(
            !warns.contains("accounting inverted"),
            "fixture: the first excess is fresh: {warns}"
        );
        assert_eq!(read, T_BYTES, "fixture: the first excess holds T");
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        manager.staged_excess_since_secs.store(
            now - crate::staged_fold::RECLAIM_DOCUMENT_MAX_AGE_SECS - 1,
            std::sync::atomic::Ordering::Relaxed,
        );
        seed_total_size(&manager, S_BYTES + T_BYTES).await;
        let (read, _, warns) = stats_with_warns(&manager, temp.path()).await;
        assert_eq!(
            read, T_BYTES,
            "fixture: the consistent read is total_size - F"
        );
        assert!(!warns.contains("accounting inverted"), "fixture: {warns}");
        seed_total_size(&manager, T_BYTES).await;
        let (read, _, warns) = stats_with_warns(&manager, temp.path()).await;
        assert!(
            !warns.contains("accounting inverted"),
            "an excess after a consistent read must not inherit the earlier excess's age: {warns:?}"
        );
        assert_eq!(
            read, T_BYTES,
            "read_cache_size must hold its last consistent value, not 0"
        );
    }
    /// The guard's held arm is observable: `read_cache_size_inverted_secs` carries the excess's
    /// age while `read_cache_size` is held, and returns to 0 on the next consistent read. Red
    /// with the gauge stubbed to 0.
    #[tokio::test(flavor = "multi_thread")]
    async fn a_held_read_cache_size_publishes_its_inverted_age() {
        async fn sizes_now(manager: &CacheManager, dir: &std::path::Path) -> CacheSizes {
            crate::staged_fold::invalidate_authority_snapshot_for_tests(dir);
            manager
                .get_cache_size_stats()
                .await
                .unwrap()
                .sizes
                .expect("get_cache_size_stats must always populate CacheSizes")
        }
        let temp = tempfile::TempDir::new().unwrap();
        let manager = fold_epoch_read_once_consistent(temp.path()).await;
        let consistent = sizes_now(&manager, temp.path()).await;
        assert_eq!(
            consistent.read_cache_size_inverted_secs, 0,
            "fixture: a consistent read is not held"
        );
        seed_total_size(&manager, T_BYTES).await;
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs();
        manager
            .staged_excess_since_secs
            .store(now - 600, std::sync::atomic::Ordering::Relaxed);
        let held = sizes_now(&manager, temp.path()).await;
        assert_eq!(held.read_cache_size, T_BYTES, "fixture: the guard holds T");
        assert!(
            held.read_cache_size_inverted_secs >= 600,
            "a held read_cache_size must publish the excess's age, got {}",
            held.read_cache_size_inverted_secs
        );
        seed_total_size(&manager, S_BYTES + T_BYTES).await;
        let cleared = sizes_now(&manager, temp.path()).await;
        assert_eq!(
            cleared.read_cache_size, T_BYTES,
            "fixture: consistent again"
        );
        assert_eq!(
            cleared.read_cache_size_inverted_secs, 0,
            "a consistent read must return the gauge to 0"
        );
    }
    /// After `initialize()` and the startup start, the first PUT reads a snapshot and does not
    /// wait. The refresher's read is made slow (1.5 s) through the test seam, so a build that
    /// starts the refresher on the first PUT instead makes this PUT wait for it.
    #[tokio::test(flavor = "multi_thread")]
    async fn first_put_after_initialize_does_not_wait() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = setup(temp.path());
        manager.initialize().await.unwrap();
        seed_total_size(&manager, DISK_BYTES).await;
        manager
            .put_usage_read_delay_ms
            .store(1_500, std::sync::atomic::Ordering::Relaxed);

        manager.start_put_usage_refresher().await;

        let started = std::time::Instant::now();
        let figure = tokio::time::timeout(
            std::time::Duration::from_millis(500),
            manager.put_capacity_usage(),
        )
        .await
        .expect(
            "the first put_capacity_usage after initialize() waited on the refresher's read: \
             no startup snapshot was taken",
        )
        .expect("a startup snapshot is a figure, not None");
        assert!(started.elapsed() < std::time::Duration::from_millis(500));
        assert_eq!(
            figure, DISK_BYTES,
            "the startup snapshot must be the size-state total (Phase L, no P)"
        );
    }
}

/// red sides 1-4: a GET-miss or HEAD-miss fill whose S3 request began before an
/// acknowledged overwrite must not publish its old version after that overwrite, by either route
/// (the fill's own publish, or the consolidator's fold of its journal `Add`), and a fill that
/// witnessed a key with no marker and no `.meta` must not alias a write that came and went.
///
/// "The fill's S3 request began" is represented by capturing its witness; the fill then holds
/// v1's bytes or headers and publishes through the production primitives.
#[cfg(test)]
mod fill_reorder_tests {
    use super::zero_length_arm_orphan_tests::{
        incompressible_body, object_metadata, setup, BODY_LEN,
    };
    use super::*;

    const LONG_TTL: std::time::Duration = std::time::Duration::from_secs(315_360_000);

    /// The buffered GET-miss range fill (`prepare_range_store` + `finish`), witnessed.
    async fn fill_v1(manager: &CacheManager, key: &str, v1: &[u8], witness: FillWitness) {
        let mut disk_cache = manager.create_configured_disk_cache_manager();
        let prepared = disk_cache
            .prepare_range_store(
                key,
                0,
                BODY_LEN as u64 - 1,
                v1,
                object_metadata(BODY_LEN as u64, "\"v1\""),
                LONG_TTL,
                true,
            )
            .await
            .expect("fixture: the fill's .tmp write must succeed");
        if let Some(fill) = prepared {
            let _ = fill.with_fill_witness(Some(witness)).finish().await;
        }
    }

    async fn consolidate(manager: &CacheManager) {
        tokio::time::timeout(
            std::time::Duration::from_secs(60),
            manager
                .get_journal_consolidator()
                .await
                .expect("fixture: the consolidator must be wired")
                .run_consolidation_cycle(),
        )
        .await
        .expect("consolidation must finish")
        .expect("consolidation must not error");
    }

    /// The bytes a GET would be served from the disk tier: the `.meta`'s ranges, loaded.
    async fn served(manager: &CacheManager, key: &str) -> Option<Vec<u8>> {
        let text = std::fs::read_to_string(manager.get_new_metadata_file_path(key)).ok()?;
        let meta: crate::cache_types::NewCacheMetadata =
            serde_json::from_str(&text).expect("the published .meta must parse");
        let disk_cache = manager.create_configured_disk_cache_manager();
        let mut bytes = Vec::new();
        for range in &meta.ranges {
            bytes.extend(
                disk_cache
                    .load_range_data(range)
                    .await
                    .expect("a listed range must load"),
            );
        }
        Some(bytes)
    }

    /// Red side 1 (the earlier red side 3): the fill publishes after the overwrite's stamp.
    #[tokio::test]
    async fn a_fill_fetched_before_an_acknowledged_overwrite_does_not_publish_after_it() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case19-fill-reorder";
        let v1 = incompressible_body(1);

        // The fill's S3 request begins.
        let witness = manager.capture_fill_witness(key).await;
        // PUT v2 acknowledged: its response-path invalidation runs while the fill holds v1.
        manager
            .invalidate_cache_unified_for_operation(key, "PUT")
            .await
            .expect("the response-path invalidation must succeed");
        // The fill is released and publishes v1.
        fill_v1(&manager, key, &v1, witness).await;
        consolidate(&manager).await;

        let served = served(&manager, key).await;
        assert!(
            served.as_deref() != Some(&v1[..]),
            "a fill of v1 that fetched before PUT v2 was acknowledged published after v2's \
             invalidation: a GET is served {} bytes, served == v1: true",
            served.as_ref().map_or(0, |b| b.len())
        );
    }

    /// Red side 2: the fill's publish and journal `Add` land before the overwrite's stamp; the
    /// consolidator folds the `Add` after it.
    #[tokio::test]
    async fn a_fill_journalled_before_an_overwrite_is_not_folded_after_it() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case20-consolidator-route";
        let v1 = incompressible_body(2);

        let witness = manager.capture_fill_witness(key).await;
        fill_v1(&manager, key, &v1, witness).await;
        assert!(
            !manager.get_new_metadata_file_path(key).exists(),
            "fixture: the fill is journal-only, so no .meta exists before the fold"
        );
        manager
            .invalidate_cache_unified_for_operation(key, "PUT")
            .await
            .expect("the response-path invalidation must succeed");
        consolidate(&manager).await;

        let served = served(&manager, key).await;
        assert!(
            served.as_deref() != Some(&v1[..]),
            "a fill of v1 journalled before PUT v2 was acknowledged was folded after v2's \
             invalidation: a GET is served {} bytes, served == v1: true",
            served.as_ref().map_or(0, |b| b.len())
        );
    }

    /// Red side 3: a HEAD-miss whose S3 HEAD began before an overwrite stores old headers.
    #[tokio::test]
    async fn a_head_fetched_before_an_acknowledged_overwrite_does_not_store_after_it() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case20-head-reorder";

        let witness = manager.capture_fill_witness(key).await;
        manager
            .invalidate_cache_unified_for_operation(key, "PUT")
            .await
            .expect("the response-path invalidation must succeed");
        let v1_head = CacheMetadata {
            etag: "\"v1\"".to_string(),
            last_modified: "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
            content_length: 7000,
            part_number: None,
            cache_control: None,
            access_count: 0,
            last_accessed: SystemTime::now(),
        };
        let mut headers = HashMap::new();
        headers.insert("etag".to_string(), "\"v1\"".to_string());
        let _ = manager
            .store_head_cache_entry_unified_witnessed(key, headers, v1_head, Some(witness))
            .await;

        let stored = std::fs::read_to_string(manager.get_new_metadata_file_path(key))
            .ok()
            .and_then(|t| serde_json::from_str::<crate::cache_types::NewCacheMetadata>(&t).ok())
            .map(|m| (m.object_metadata.etag, m.object_metadata.content_length));
        assert!(
            stored != Some(("\"v1\"".to_string(), 7000)),
            "a HEAD of v1 that began before PUT v2 was acknowledged stored v1's headers after \
             v2's invalidation: HEAD is served (etag, length) = {:?}",
            stored
        );
    }

    /// Red side 4: the fill witnesses a key with no marker and no `.meta`; PUT v2 stamps, its
    /// store publishes (which removes the marker), v2 is evicted, and the fill publishes. With a
    /// witness that can be "no marker" this state aliases the one the fill saw.
    #[tokio::test]
    async fn a_fill_that_saw_no_marker_does_not_alias_a_write_that_came_and_went() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case20-absent-alias";
        let v1 = incompressible_body(3);
        let meta_path = manager.get_new_metadata_file_path(key);

        assert!(
            read_write_marker(&meta_path).is_none() && !meta_path.exists(),
            "fixture: no marker and no .meta before the fill"
        );
        let witness = manager.capture_fill_witness(key).await;

        // PUT v2: stamp, then its store publishes and clears the marker.
        let token = manager
            .invalidate_for_write(key)
            .await
            .expect("the response-path invalidation must succeed");
        let outcome = manager
            .store_put_as_write_cached_range_guarded(
                key,
                &incompressible_body(4),
                "\"v2\"".to_string(),
                "Thu, 22 Oct 2015 07:28:00 GMT".to_string(),
                None,
                HashMap::new(),
                token,
            )
            .await
            .expect("v2's store must not error");
        assert_eq!(
            outcome,
            PublishOutcome::Published,
            "fixture: v2's store publishes"
        );
        // v2 leaves the cache (eviction does not stamp).
        manager
            .invalidate_cache_hierarchy(key)
            .await
            .expect("fixture: v2's removal must succeed");
        assert!(
            read_write_marker(&meta_path).is_none() && !meta_path.exists(),
            "fixture: no marker and no .meta again, as the fill saw"
        );

        fill_v1(&manager, key, &v1, witness).await;
        consolidate(&manager).await;

        let served = served(&manager, key).await;
        assert!(
            served.as_deref() != Some(&v1[..]),
            "a fill of v1 that witnessed no marker and no .meta published after PUT v2 came and \
             went: a GET is served {} bytes, served == v1: true",
            served.as_ref().map_or(0, |b| b.len())
        );
    }
    /// The buffered GET-miss range fill of `body` at version `etag`, witnessed.
    async fn fill_version(
        manager: &CacheManager,
        key: &str,
        body: &[u8],
        etag: &str,
        witness: FillWitness,
    ) {
        let mut disk_cache = manager.create_configured_disk_cache_manager();
        let prepared = disk_cache
            .prepare_range_store(
                key,
                0,
                BODY_LEN as u64 - 1,
                body,
                object_metadata(BODY_LEN as u64, etag),
                LONG_TTL,
                true,
            )
            .await
            .expect("fixture: the fill's .tmp write must succeed");
        if let Some(fill) = prepared {
            let _ = fill.with_fill_witness(Some(witness)).finish().await;
        }
    }
    /// The direct-publish witness check on its own. v1's fill captured
    /// its witness before PUT v2's stamp; v2's fill began after it, published its `.bin` and
    /// journalled its `Add`, not yet folded, so no `.meta` exists for the etag check to compare
    /// against. The range file's path does not depend on the version, so only the check in
    /// `publish_range_fill_under_slot_lock_at` stops v1's rename over v2's bytes, which v2's
    /// `.meta` would then list.
    #[tokio::test]
    async fn a_superseded_fill_does_not_rename_over_a_newer_unfolded_fill() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case21-direct-guard";
        let v1 = incompressible_body(5);
        let v2 = incompressible_body(6);
        assert_ne!(v1, v2, "fixture: the two versions differ");
        let witness_v1 = manager.capture_fill_witness(key).await;
        manager
            .invalidate_cache_unified_for_operation(key, "PUT")
            .await
            .expect("the response-path invalidation must succeed");
        let witness_v2 = manager.capture_fill_witness(key).await;
        fill_version(&manager, key, &v2, "\"v2\"", witness_v2).await;
        assert!(
            !manager.get_new_metadata_file_path(key).exists(),
            "fixture: v2's fill is journal-only, so no .meta exists before the fold"
        );
        fill_version(&manager, key, &v1, "\"v1\"", witness_v1).await;
        consolidate(&manager).await;
        let served = served(&manager, key).await;
        assert!(
            served.as_deref() == Some(&v2[..]),
            "a fill of v1 that fetched before PUT v2 was acknowledged renamed over v2's unfolded \
             fill: a GET is served {} bytes, served == v1: {}, served == v2: false",
            served.as_ref().map_or(0, |b| b.len()),
            served.as_deref() == Some(&v1[..])
        );
    }
    /// The response headers of a `?partNumber=1` GET of v1 for a one-part object.
    fn part_headers_v1() -> HashMap<String, String> {
        let mut headers = HashMap::new();
        headers.insert("etag".to_string(), "\"v1\"".to_string());
        headers.insert(
            "last-modified".to_string(),
            "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
        );
        headers.insert("x-amz-mp-parts-count".to_string(), "1".to_string());
        headers
    }
    /// A `?partNumber=` GET whose S3 request began before an
    /// acknowledged overwrite must not publish its old part after it.
    #[tokio::test]
    async fn a_part_fetched_before_an_acknowledged_overwrite_does_not_publish_after_it() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case21-part-reorder";
        let v1 = incompressible_body(7);
        let witness = manager.capture_fill_witness(key).await;
        manager
            .invalidate_cache_unified_for_operation(key, "PUT")
            .await
            .expect("the response-path invalidation must succeed");
        let content_range = format!("bytes 0-{}/{}", BODY_LEN - 1, BODY_LEN);
        manager
            .store_part_as_range_witnessed(
                key,
                1,
                &content_range,
                &part_headers_v1(),
                &v1,
                Some(witness),
            )
            .await
            .expect("a part store reports success to its caller");
        consolidate(&manager).await;
        let served = served(&manager, key).await;
        assert!(
            served.as_deref() != Some(&v1[..]),
            "a ?partNumber=1 GET of v1 that fetched before PUT v2 was acknowledged published \
             after v2's invalidation: a GET is served {} bytes, served == v1: true",
            served.as_ref().map_or(0, |b| b.len())
        );
    }
    /// the same part GET, where PUT v2's store has already published v2's `.meta`. The
    /// range itself is dropped by the etag check; the `.meta` rewrite that records the part's
    /// boundaries must also not land in v2's document.
    #[tokio::test]
    async fn a_superseded_part_does_not_record_its_boundaries_in_the_newer_meta() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case21-part-populate";
        let v1 = incompressible_body(8);
        let witness = manager.capture_fill_witness(key).await;
        let token = manager
            .invalidate_for_write(key)
            .await
            .expect("the response-path invalidation must succeed");
        let outcome = manager
            .store_put_as_write_cached_range_guarded(
                key,
                &incompressible_body(9),
                "\"v2\"".to_string(),
                "Thu, 22 Oct 2015 07:28:00 GMT".to_string(),
                None,
                HashMap::new(),
                token,
            )
            .await
            .expect("v2's store must not error");
        assert_eq!(
            outcome,
            PublishOutcome::Published,
            "fixture: v2's store publishes"
        );
        let content_range = format!("bytes 0-{}/{}", BODY_LEN / 2 - 1, BODY_LEN);
        manager
            .store_part_as_range_witnessed(
                key,
                1,
                &content_range,
                &part_headers_v1(),
                &v1[..BODY_LEN / 2],
                Some(witness),
            )
            .await
            .expect("a part store reports success to its caller");
        let meta: crate::cache_types::NewCacheMetadata = serde_json::from_str(
            &std::fs::read_to_string(manager.get_new_metadata_file_path(key))
                .expect("fixture: v2's .meta is published"),
        )
        .expect("v2's .meta parses");
        assert_eq!(
            meta.object_metadata.etag, "\"v2\"",
            "fixture: the .meta is v2's"
        );
        assert!(
            !meta.object_metadata.part_ranges.contains_key(&1),
            "a ?partNumber=1 GET of v1 that fetched before PUT v2 was acknowledged recorded its \
             part boundaries in v2's .meta: part_ranges = {:?}",
            meta.object_metadata.part_ranges
        );
    }
    /// The streamed GET-miss fill (`IncrementalRangeWriter` with
    /// `set_fill_witness`, committed through `prepare_incremental_commit`).
    #[tokio::test]
    async fn a_streamed_fill_fetched_before_an_acknowledged_overwrite_does_not_publish_after_it() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case21-streamed-reorder";
        let v1 = incompressible_body(10);
        let witness = manager.capture_fill_witness(key).await;
        manager
            .invalidate_cache_unified_for_operation(key, "PUT")
            .await
            .expect("the response-path invalidation must succeed");
        let disk_cache = manager.create_configured_disk_cache_manager();
        let mut writer = disk_cache
            .begin_incremental_range_write(key, 0, BODY_LEN as u64 - 1, true)
            .await
            .expect("fixture: the streamed writer must open")
            .expect("fixture: the streamed writer is admitted");
        writer.set_fill_witness(Some(witness));
        crate::disk_cache::DiskCacheManager::write_range_chunk(&mut writer, &v1)
            .expect("fixture: the chunk write must succeed");
        let _ = disk_cache
            .commit_incremental_range(writer, object_metadata(BODY_LEN as u64, "\"v1\""), LONG_TTL)
            .await;
        consolidate(&manager).await;
        let served = served(&manager, key).await;
        assert!(
            served.as_deref() != Some(&v1[..]),
            "a streamed fill of v1 that fetched before PUT v2 was acknowledged published after \
             v2's invalidation: a GET is served {} bytes, served == v1: true",
            served.as_ref().map_or(0, |b| b.len())
        );
    }
    /// The full-object GET store (`store_response_with_headers_witnessed`),
    /// disk tier.
    #[tokio::test]
    async fn a_full_object_fill_fetched_before_an_acknowledged_overwrite_does_not_store_after_it() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case21-full-object-reorder";
        let v1 = incompressible_body(11);
        let witness = manager.capture_fill_witness(key).await;
        manager
            .invalidate_cache_unified_for_operation(key, "PUT")
            .await
            .expect("the response-path invalidation must succeed");
        let mut headers = HashMap::new();
        headers.insert("etag".to_string(), "\"v1\"".to_string());
        headers.insert("content-length".to_string(), BODY_LEN.to_string());
        let v1_meta = CacheMetadata {
            etag: "\"v1\"".to_string(),
            last_modified: "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
            content_length: BODY_LEN as u64,
            part_number: None,
            cache_control: None,
            access_count: 0,
            last_accessed: SystemTime::now(),
        };
        let _ = manager
            .store_response_with_headers_witnessed(key, &v1, headers, v1_meta, Some(witness))
            .await;
        consolidate(&manager).await;
        let served = served(&manager, key).await;
        assert!(
            served.as_deref() != Some(&v1[..]),
            "a full-object fill of v1 that fetched before PUT v2 was acknowledged stored after \
             v2's invalidation: a GET is served {} bytes, served == v1: true",
            served.as_ref().map_or(0, |b| b.len())
        );
    }
}

/// A write-stamp retry runs the same post-hold fill-visibility and RAM clear as a
/// first-try stamp, so a fill that recorded inside its own publish hold, after the retry's
/// unconditional clears, is not served on this proxy once the retry lands.
#[cfg(test)]
mod stamp_retry_clear_tests {
    use super::zero_length_arm_orphan_tests::{incompressible_body, object_metadata, BODY_LEN};
    use super::*;

    /// `zero_length_arm_orphan_tests::setup`, with the RAM tier on.
    async fn setup_with_ram(cache_dir: &std::path::Path) -> Arc<CacheManager> {
        for sub in ["metadata/_journals", "size_tracking", "locks", "ranges"] {
            std::fs::create_dir_all(cache_dir.join(sub)).unwrap();
        }
        let manager = CacheManager::new_with_shared_storage(
            cache_dir.to_path_buf(),
            true,
            64 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
            CacheEvictionAlgorithm::TinyLFU,
            1024,
            true,
            std::time::Duration::from_secs(315_360_000),
            std::time::Duration::from_secs(3600),
            std::time::Duration::from_secs(3600),
            false,
            crate::config::SharedStorageConfig::default(),
            10.0,
            true,
            std::time::Duration::from_secs(86400),
            crate::config::MetadataCacheConfig::default(),
            95,
            80,
            true,
            std::time::Duration::from_secs(60),
            1_048_576,
            false,
            std::time::Duration::from_secs(10),
            64,
            std::time::Duration::from_secs(5),
        );
        let _ = manager.create_configured_disk_cache_manager();
        manager
            .initialize()
            .await
            .expect("fixture: initialize() must wire the hybrid metadata writer");
        Arc::new(manager)
    }

    /// What a streamed full-object fill leaves on this proxy when it publishes: a committed
    /// `.bin`, a fill-visibility entry recorded inside its publish hold, and a RAM copy.
    async fn publish_fill(
        manager: &CacheManager,
        cache_dir: &std::path::Path,
        key: &str,
        body: &[u8],
    ) {
        let bin = cache_dir.join("ranges").join("case22-fill.bin");
        std::fs::write(&bin, body).unwrap();
        let om = object_metadata(BODY_LEN as u64, "\"v1\"");
        let now = SystemTime::now();
        let tracked = crate::cache_types::NewCacheMetadata {
            cache_key: key.to_string(),
            object_metadata: om,
            created_at: now,
            expires_at: now + Duration::from_secs(3600),
            ..Default::default()
        };
        let stamp = crate::fill_visibility_tracker::RangeFileStamp::of(&bin).unwrap();
        let marker = crate::fill_visibility_tracker::MarkerStamp::of(
            &manager.get_new_metadata_file_path(key),
        )
        .expect("fixture: the key's write marker is readable");
        manager
            .fill_visibility_tracker
            .record(tracked, vec![stamp], marker);
        let entry = CacheEntry {
            cache_key: key.to_string(),
            headers: HashMap::new(),
            body: Some(body.to_vec()),
            ranges: Vec::new(),
            metadata: CacheMetadata {
                etag: "\"v1\"".to_string(),
                last_modified: "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
                content_length: body.len() as u64,
                part_number: None,
                cache_control: None,
                access_count: 0,
                last_accessed: now,
            },
            created_at: now,
            expires_at: now + Duration::from_secs(3600),
            metadata_expires_at: now + Duration::from_secs(3600),
            compression_info: CompressionInfo::default(),
            is_put_cached: false,
        };
        manager.store_in_ram_cache(&entry).await.unwrap();
    }

    #[tokio::test]
    async fn a_retried_stamp_clears_a_fill_recorded_inside_its_publish_hold() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup_with_ram(dir.path()).await;
        let key = "test-bucket/case22-retry-clears-fill";
        let v1 = incompressible_body(11);
        // DELETE acknowledged; its response-path stamp gives up on the slot lock.
        crate::metadata_lock_manager::forced_retry_exhaustion::arm(key, 1);
        let retry = write_stamp_retry_gate::arm(key);
        let first = manager.invalidate_acknowledged_write(key, "DELETE").await;
        let retry_reached = tokio::time::timeout(Duration::from_secs(5), retry.reached.notified())
            .await
            .is_ok();
        // Hold the retry after its unconditional clears and before its slot-lock hold.
        let hold = stamp_pre_hold_gate::arm(key);
        retry.resume.notify_one();
        let hold_reached = tokio::time::timeout(Duration::from_secs(5), hold.reached.notified())
            .await
            .is_ok();
        // A fill whose S3 request began before the DELETE publishes now: the marker was never
        // moved, so its witness still holds.
        publish_fill(&manager, dir.path(), key, &v1).await;
        let tracked_before = manager
            .get_metadata_cached(key)
            .await
            .ok()
            .flatten()
            .is_some();
        let ram_before = manager
            .get_from_ram_cache(key)
            .await
            .ok()
            .flatten()
            .is_some();
        hold.resume.notify_one();
        let stamped = tokio::time::timeout(Duration::from_secs(30), retry.stamped.notified())
            .await
            .is_ok();
        let tracked_after = manager
            .get_metadata_cached(key)
            .await
            .ok()
            .flatten()
            .is_some();
        let ram_after = manager
            .get_from_ram_cache(key)
            .await
            .ok()
            .flatten()
            .is_some();
        assert!(
            first.is_err(),
            "fixture: the DELETE's first stamp must fail"
        );
        assert!(
            retry_reached && hold_reached,
            "fixture: the retry must reach its gates (retry: {retry_reached}, pre-hold: \
             {hold_reached})"
        );
        assert!(
            tracked_before && ram_before,
            "fixture: the fill is visible on this proxy before the retry's hold (tracker: \
             {tracked_before}, RAM: {ram_before})"
        );
        assert!(stamped, "the background stamp retry must land");
        assert!(
            !tracked_after && !ram_after,
            "after DELETE was acknowledged with its stamp failed and the retry landed, a GET on \
             this proxy is served the older fill (via the fill-visibility tracker: {}, from RAM: \
             {}): the retried stamp did not clear what the fill recorded inside its publish hold",
            tracked_after,
            ram_after
        );
    }

    /// one retry per key, and none past the cap.
    #[tokio::test]
    async fn failed_stamps_of_one_key_share_one_retry_and_the_cap_refuses() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup_with_ram(dir.path()).await;
        let key = "test-bucket/case22-retry-dedup";
        // Enough forced failures that the retry is still failing while the writes arrive.
        crate::metadata_lock_manager::forced_retry_exhaustion::arm(key, 3);
        let retry = write_stamp_retry_gate::arm(key);
        let outcomes: Vec<WriteStampRetry> = (0..100)
            .map(|_| manager.spawn_write_stamp_retry(key))
            .collect();
        let started = outcomes
            .iter()
            .filter(|o| **o == WriteStampRetry::Started)
            .count();
        let joined = outcomes
            .iter()
            .filter(|o| **o == WriteStampRetry::Joined)
            .count();
        let slot = format!("{}\u{0}{}", manager.cache_dir.display(), key);
        let joined_recorded = lock_write_stamp_retries().keys.get(slot.as_str()).copied();
        retry.resume.notify_one();
        let stamped = tokio::time::timeout(Duration::from_secs(30), retry.stamped.notified())
            .await
            .is_ok();
        let slot_freed = !lock_write_stamp_retries().keys.contains_key(slot.as_str());
        let other = "test-bucket/case22-retry-capped";
        let abandoned_before = WRITE_STAMP_RETRY_ABANDONED.load(AtomicOrdering::Relaxed);
        WRITE_STAMP_RETRY_MAX_TASKS_OVERRIDE.with(|c| c.set(Some(0)));
        WRITE_STAMP_OVERFLOW_MAX_BYTES_OVERRIDE.with(|c| c.set(Some(0)));
        let capped = manager.spawn_write_stamp_retry(other);
        WRITE_STAMP_OVERFLOW_MAX_BYTES_OVERRIDE.with(|c| c.set(None));
        WRITE_STAMP_RETRY_MAX_TASKS_OVERRIDE.with(|c| c.set(None));
        let abandoned_after = WRITE_STAMP_RETRY_ABANDONED.load(AtomicOrdering::Relaxed);
        let other_slot = format!("{}\u{0}{}", manager.cache_dir.display(), other);
        assert_eq!(
            (started, joined, joined_recorded),
            (1, 99, Some(99)),
            "100 failed writes of one key must start one retry and join 99"
        );
        assert!(
            stamped && slot_freed,
            "the shared retry must land and free its slot"
        );
        assert_eq!(
            capped,
            WriteStampRetry::Abandoned,
            "with no free task and no overflow room, a write gets no retry"
        );
        assert!(
            abandoned_after > abandoned_before
                && !lock_write_stamp_retries()
                    .keys
                    .contains_key(other_slot.as_str()),
            "an abandoned write is counted and holds no slot"
        );
    }
}

/// A write whose stamp fails while every retry task is busy waits in the
/// overflow queue, and the next task to land its own stamp takes it, so an older pending store
/// of its key does not stay served.
#[cfg(test)]
mod stamp_overflow_tests {
    use super::zero_length_arm_orphan_tests::{
        incompressible_body, object_metadata, setup, BODY_LEN,
    };
    use super::*;

    const LONG_TTL: Duration = Duration::from_secs(315_360_000);

    /// The buffered GET-miss range fill (`prepare_range_store` + `finish`), witnessed.
    async fn fill_v1(manager: &CacheManager, key: &str, v1: &[u8], witness: FillWitness) {
        let mut disk_cache = manager.create_configured_disk_cache_manager();
        let prepared = disk_cache
            .prepare_range_store(
                key,
                0,
                BODY_LEN as u64 - 1,
                v1,
                object_metadata(BODY_LEN as u64, "\"v1\""),
                LONG_TTL,
                true,
            )
            .await
            .expect("fixture: the fill's .tmp write must succeed");
        if let Some(fill) = prepared {
            let _ = fill.with_fill_witness(Some(witness)).finish().await;
        }
    }

    async fn consolidate(manager: &CacheManager) {
        tokio::time::timeout(
            Duration::from_secs(60),
            manager
                .get_journal_consolidator()
                .await
                .expect("fixture: the consolidator must be wired")
                .run_consolidation_cycle(),
        )
        .await
        .expect("consolidation must finish")
        .expect("consolidation must not error");
    }

    /// The bytes a GET would be served from the disk tier: the `.meta`'s ranges, loaded.
    async fn served(manager: &CacheManager, key: &str) -> Option<Vec<u8>> {
        let text = std::fs::read_to_string(manager.get_new_metadata_file_path(key)).ok()?;
        let meta: crate::cache_types::NewCacheMetadata =
            serde_json::from_str(&text).expect("the published .meta must parse");
        let disk_cache = manager.create_configured_disk_cache_manager();
        let mut bytes = Vec::new();
        for range in &meta.ranges {
            bytes.extend(
                disk_cache
                    .load_range_data(range)
                    .await
                    .expect("a listed range must load"),
            );
        }
        Some(bytes)
    }

    #[tokio::test]
    async fn a_write_past_the_retry_task_cap_is_queued_and_its_stamp_lands() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = Arc::new(setup(dir.path()).await);
        let busy = "test-bucket/case23-busy";
        let key = "test-bucket/case23-overflow";
        let v1 = incompressible_body(31);
        WRITE_STAMP_RETRY_MAX_TASKS_OVERRIDE.with(|c| c.set(Some(1)));
        // The cap's one task: a retry held before its first attempt.
        let busy_gate = write_stamp_retry_gate::arm(busy);
        let busy_outcome = manager.spawn_write_stamp_retry(busy);
        let busy_reached =
            tokio::time::timeout(Duration::from_secs(10), busy_gate.reached.notified())
                .await
                .is_ok();
        // A peer proxy's fill of v1 begins: its witness is the key's current marker. A peer's,
        // because this proxy declines its own fills of a key while it holds a pending stamp for
        // it, so only a peer's older fill can outlive the DELETE.
        let witness = capture_fill_witness_blocking(
            &manager.cache_dir,
            &manager.get_new_metadata_file_path(key),
            key,
            &Arc::new(FillLeaseRegistry::default()),
        );
        // DELETE acknowledged; its response-path stamp gives up on the slot lock.
        crate::metadata_lock_manager::forced_retry_exhaustion::arm(key, 1);
        let key_gate = write_stamp_retry_gate::arm(key);
        let deleted = manager.invalidate_acknowledged_write(key, "DELETE").await;
        WRITE_STAMP_RETRY_MAX_TASKS_OVERRIDE.with(|c| c.set(None));
        let slot = format!("{}\u{0}{}", manager.cache_dir.display(), key);
        let pending = lock_write_stamp_retries().keys.contains_key(slot.as_str());
        // The older fill publishes v1: the marker never moved, so its witness still holds.
        fill_v1(&manager, key, &v1, witness).await;
        consolidate(&manager).await;
        let served_before = served(&manager, key).await;
        // The busy task is released; it lands its own stamp and then takes the queued key.
        busy_gate.resume.notify_one();
        let key_reached =
            tokio::time::timeout(Duration::from_secs(10), key_gate.reached.notified())
                .await
                .is_ok();
        key_gate.resume.notify_one();
        let key_stamped = key_reached
            && tokio::time::timeout(Duration::from_secs(30), key_gate.stamped.notified())
                .await
                .is_ok();
        let served_after = served(&manager, key).await;
        assert_eq!(
            busy_outcome,
            WriteStampRetry::Started,
            "fixture: the busy key takes the only task"
        );
        assert!(busy_reached, "fixture: the busy retry must reach its gate");
        assert!(
            deleted.is_err(),
            "fixture: the DELETE's first stamp must fail"
        );
        assert_eq!(
            served_before.as_deref(),
            Some(&v1[..]),
            "fixture: the older fill must publish before any stamp lands"
        );
        assert!(
            served_after.as_deref() != Some(&v1[..]),
            "after a DELETE was acknowledged with its stamp failed while every retry task was \
             busy, an older fill stays served: a GET is served {} bytes, served == v1: true \
             (key pending a retry: {}, retry reached: {}, landed: {})",
            served_after.as_ref().map_or(0, |b| b.len()),
            pending,
            key_reached,
            key_stamped
        );
        assert!(
            pending && key_stamped,
            "the queued key's stamp must land (pending: {pending}, landed: {key_stamped})"
        );
    }
}

/// (review): liveness of the stamp-retry queue and of the uncached fill's marker
/// release.
#[cfg(test)]
mod stamp_retry_liveness_tests {
    use super::zero_length_arm_orphan_tests::setup;
    use super::*;

    /// A key whose metadata slot differs from `of`'s.
    fn key_on_another_slot(prefix: &str, of: &str) -> String {
        let taken = crate::metadata_lock_manager::slot_for_cache_key(of);
        (0..)
            .map(|i| format!("{prefix}-{i}"))
            .find(|k| crate::metadata_lock_manager::slot_for_cache_key(k) != taken)
            .expect("some key lands on another slot")
    }

    fn slot_of(manager: &CacheManager, key: &str) -> String {
        format!("{}\u{0}{}", manager.cache_dir.display(), key)
    }

    /// Fix 2: a task whose key's slot stays refused moves to the next queued key.
    #[tokio::test]
    async fn a_queued_key_on_a_free_slot_lands_while_the_only_task_is_on_a_held_slot() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = Arc::new(setup(dir.path()).await);
        let stuck = "test-bucket/case24-stuck";
        let free = key_on_another_slot("test-bucket/case24-free", stuck);
        // A peer holds the stuck key's slot for the whole test, as a hung proxy would.
        let held = crate::metadata_lock_manager::try_acquire_slot_lock(&manager.cache_dir, stuck)
            .expect("fixture: the stuck key's slot must be free to take");
        WRITE_STAMP_RETRY_MAX_TASKS_OVERRIDE.with(|c| c.set(Some(1)));
        let stuck_outcome = manager.spawn_write_stamp_retry(stuck);
        let free_gate = write_stamp_retry_gate::arm(&free);
        free_gate.resume.notify_one();
        let free_outcome = manager.spawn_write_stamp_retry(&free);
        WRITE_STAMP_RETRY_MAX_TASKS_OVERRIDE.with(|c| c.set(None));
        // while the stuck key holds the only task.
        let figures_while_stuck = write_stamp_retry_scope_figures(&manager.stamp_retry_scope());
        let active_gauge_while_stuck = write_stamp_retry_active_keys();
        let free_landed =
            tokio::time::timeout(Duration::from_secs(60), free_gate.stamped.notified())
                .await
                .is_ok();
        let (stuck_pending, free_pending) = {
            let st = lock_write_stamp_retries();
            (
                st.keys.contains_key(slot_of(&manager, stuck).as_str()),
                st.keys.contains_key(slot_of(&manager, &free).as_str()),
            )
        };
        let figures_after = write_stamp_retry_scope_figures(&manager.stamp_retry_scope());
        drop(held);
        assert_eq!(
            (stuck_outcome, free_outcome),
            (WriteStampRetry::Started, WriteStampRetry::Queued),
            "fixture: the stuck key takes the only task and the free key is queued"
        );
        assert!(
            figures_while_stuck == (1, 1, 2) && active_gauge_while_stuck >= 1,
            "while the stuck key holds the only task: one active key and one queued, of two \
             pending (tasks, queued, pending) = {figures_while_stuck:?}; process-wide active \
             gauge {active_gauge_while_stuck}"
        );
        assert!(
            figures_after.0 + figures_after.1 == figures_after.2 && figures_after.2 == 1,
            "after the rotation and the free key's landing, active plus queued keys must be \
             the pending set, the stuck key alone: (tasks, queued, pending) = {figures_after:?}"
        );
        assert!(
            free_landed,
            "with the only retry task on a key whose slot stays held, a queued key on a free \
             slot did not have its stamp land within 60 s (stuck key pending: {}, free key \
             pending: {})",
            stuck_pending, free_pending
        );
        assert!(
            stuck_pending && !free_pending,
            "the stuck key stays pending after the task moves off it and the free key does not \
             (stuck: {stuck_pending}, free: {free_pending})"
        );
    }

    /// Fix 3: a task that panics hands its directory's queued keys to a new task. The panicked
    /// key has no log record, so it stays pending on this proxy until the task that lands
    /// the queued key takes it and its own stamp lands: the predicate the read-side guard
    /// consults, so meanwhile its GET and HEAD go to S3. The queued key's gate is held so that
    /// interval can be observed.
    #[tokio::test]
    async fn a_panicking_retry_task_hands_its_queued_key_to_a_new_task() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = Arc::new(setup(dir.path()).await);
        let doomed = "test-bucket/case24-panics";
        let queued = "test-bucket/case24-queued-behind-a-panic";
        write_stamp_retry_panic::arm(doomed);
        WRITE_STAMP_RETRY_MAX_TASKS_OVERRIDE.with(|c| c.set(Some(1)));
        let doomed_outcome = manager.spawn_write_stamp_retry(doomed);
        let queued_gate = write_stamp_retry_gate::arm(queued);
        let queued_outcome = manager.spawn_write_stamp_retry(queued);
        WRITE_STAMP_RETRY_MAX_TASKS_OVERRIDE.with(|c| c.set(None));
        // The doomed key's task panicked and handed the queued key to a new task, held at its
        // gate: nothing can have stamped the doomed key yet.
        let handed = tokio::time::timeout(Duration::from_secs(10), queued_gate.reached.notified())
            .await
            .is_ok();
        let mut held_samples = Vec::new();
        for _ in 0..6 {
            // The guard at the top of the GET and HEAD serve path reads exactly this.
            held_samples.push(manager.pending_stamp_probe(doomed).pending());
            tokio::time::sleep(Duration::from_millis(50)).await;
        }
        queued_gate.resume.notify_one();
        let landed = tokio::time::timeout(Duration::from_secs(10), queued_gate.stamped.notified())
            .await
            .is_ok();
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        let (doomed_pending, queued_pending, tasks) = loop {
            let doomed_pending = manager.pending_stamp_probe(doomed).pending();
            let sample = {
                let st = lock_write_stamp_retries();
                (
                    doomed_pending,
                    st.keys.contains_key(slot_of(&manager, queued).as_str()),
                    st.dirs.get(&manager.cache_dir).map_or(0, |d| d.tasks),
                )
            };
            if sample == (false, false, 0) || std::time::Instant::now() >= deadline {
                break sample;
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        };
        assert_eq!(
            (doomed_outcome, queued_outcome),
            (WriteStampRetry::Started, WriteStampRetry::Queued),
            "fixture: the doomed key takes the only task and the other key is queued"
        );
        assert!(
            handed,
            "after the only retry task panicked, the key queued behind it was not handed to a \
             new task within 10 s"
        );
        assert!(
            held_samples.iter().all(|p| *p),
            "while the queued key's retry is held, the panicked key (its task ended with no log \
             record) must stay pending on this proxy, so its GET and HEAD go to S3: pending \
             samples {held_samples:?}"
        );
        assert!(
            landed,
            "after the only retry task panicked, a key queued behind it did not have its stamp \
             land within 10 s of its gate opening (queued key pending: {}, retry tasks counted: \
             {})",
            queued_pending, tasks
        );
        assert!(
            !doomed_pending && !queued_pending && tasks == 0,
            "the queued key's retry finishes, then the panicked key's stamp lands and it leaves \
             the pending set, and no task stays counted (panicked pending: {doomed_pending}, \
             queued pending: {queued_pending}, tasks: {tasks})"
        );
    }

    /// a key with no log record whose retry task ends early (a panic) is left untracked,
    /// and a replacement task with nothing else queued takes that same key again. A retry that
    /// ends early every time must not respawn in a loop: the key is retried at a bounded rate,
    /// stays pending throughout, and its stamp lands once its retry can complete.
    #[tokio::test]
    async fn a_retry_task_that_keeps_ending_early_respawns_at_a_bounded_rate() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = Arc::new(setup(dir.path()).await);
        let key = "test-bucket/case25-ends-early-every-time";
        write_stamp_retry_panic::arm_every(key);
        let outcome = manager.spawn_write_stamp_retry(key);
        let window = Duration::from_millis(600);
        let started = std::time::Instant::now();
        let mut pending_throughout = true;
        while started.elapsed() < window {
            pending_throughout &= manager.pending_stamp_probe(key).pending();
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
        let picked_up = write_stamp_retry_panic::disarm_every(key);
        let deadline = std::time::Instant::now() + Duration::from_secs(15);
        let (pending_after, tasks) = loop {
            let pending = manager.pending_stamp_probe(key).pending();
            let tasks = lock_write_stamp_retries()
                .dirs
                .get(&manager.cache_dir)
                .map_or(0, |d| d.tasks);
            if (!pending && tasks == 0) || std::time::Instant::now() >= deadline {
                break (pending, tasks);
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        };
        assert_eq!(
            outcome,
            WriteStampRetry::Started,
            "fixture: the key takes a retry task"
        );
        assert!(
            (2..=10).contains(&picked_up),
            "a key whose retry task ends early every time was picked up {picked_up} times in \
             {window:?}: it must keep being retried (at least 2) at a bounded rate (at most 10)"
        );
        assert!(
            pending_throughout,
            "the key must stay pending on this proxy while its retries keep ending early"
        );
        assert!(
            !pending_after && tasks == 0,
            "once its retry can complete the key's stamp lands and no task stays counted \
             (pending: {pending_after}, tasks: {tasks})"
        );
    }

    /// Fix 1 (fix 3's untested half): an uncached fill's marker release retries while
    /// the key's slot lock is busy, so a marker whose lock frees within the window is removed.
    #[tokio::test]
    async fn an_uncached_fill_marker_is_released_after_its_slot_lock_frees() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case24-contended-release";
        let marker = write_marker_path(&manager.get_new_metadata_file_path(key));
        let witness = manager.capture_fill_witness(key).await;
        let created = witness.lease.is_some() && marker.exists();
        // A peer holds the key's slot across the release's first tries (0, 20, 60, 140 ms).
        let held = crate::metadata_lock_manager::try_acquire_slot_lock(&manager.cache_dir, key)
            .expect("fixture: the key's slot must be free to take");
        drop(witness);
        tokio::time::sleep(Duration::from_millis(200)).await;
        let kept_while_held = marker.exists();
        drop(held);
        let deadline = tokio::time::Instant::now() + Duration::from_secs(3);
        while marker.exists() && tokio::time::Instant::now() < deadline {
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
        let left = marker.exists();
        assert!(
            created && kept_while_held,
            "fixture: the capture creates the marker and the held lock keeps it (created: \
             {created}, kept while held: {kept_while_held})"
        );
        assert!(
            !left,
            "an uncached fill's marker whose slot lock was busy for its first release tries and \
             then freed was left on the shared volume 3 s later: {}",
            marker.display()
        );
    }
}
/// fills on one proxy that witnessed the same marker token. The deterministic shape of
/// the multipart race test's "no .meta after the downloads settled": a HEAD miss (or a fill S3
/// refused) creates the key's marker and caches nothing, its release removes the marker, and the
/// repair fills that witnessed the token on the same proxy are refused as superseded though no
/// write was acknowledged.
#[cfg(test)]
mod shared_fill_lease_tests {
    use super::zero_length_arm_orphan_tests::{
        incompressible_body, object_metadata, setup, BODY_LEN,
    };
    use super::*;
    const LONG_TTL: Duration = Duration::from_secs(315_360_000);
    /// The buffered GET-miss range fill (`prepare_range_store` + `finish`), witnessed.
    async fn fill_v1(manager: &CacheManager, key: &str, v1: &[u8], witness: FillWitness) {
        let mut disk_cache = manager.create_configured_disk_cache_manager();
        let prepared = disk_cache
            .prepare_range_store(
                key,
                0,
                BODY_LEN as u64 - 1,
                v1,
                object_metadata(BODY_LEN as u64, "\"v1\""),
                LONG_TTL,
                true,
            )
            .await
            .expect("fixture: the fill's .tmp write must succeed");
        if let Some(fill) = prepared {
            let _ = fill.with_fill_witness(Some(witness)).finish().await;
        }
    }
    async fn consolidate(manager: &CacheManager) {
        tokio::time::timeout(
            Duration::from_secs(60),
            manager
                .get_journal_consolidator()
                .await
                .expect("fixture: the consolidator must be wired")
                .run_consolidation_cycle(),
        )
        .await
        .expect("consolidation must finish")
        .expect("consolidation must not error");
    }
    /// The bytes a GET would be served from the disk tier: the `.meta`'s ranges, loaded.
    async fn served(manager: &CacheManager, key: &str) -> Option<Vec<u8>> {
        let text = std::fs::read_to_string(manager.get_new_metadata_file_path(key)).ok()?;
        let meta: crate::cache_types::NewCacheMetadata =
            serde_json::from_str(&text).expect("the published .meta must parse");
        let disk_cache = manager.create_configured_disk_cache_manager();
        let mut bytes = Vec::new();
        for range in &meta.ranges {
            bytes.extend(
                disk_cache
                    .load_range_data(range)
                    .await
                    .expect("a listed range must load"),
            );
        }
        Some(bytes)
    }
    /// Wait until the marker is gone or `limit` passes. `true` when it is gone.
    async fn marker_gone_within(marker: &Path, limit: Duration) -> bool {
        let deadline = tokio::time::Instant::now() + limit;
        while marker.exists() && tokio::time::Instant::now() < deadline {
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
        !marker.exists()
    }

    /// Red before the fix: the sibling's release removed the marker and the repair fill was refused.
    #[tokio::test]
    async fn a_sibling_fills_uncached_release_does_not_refuse_a_repair_fill() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case26-sibling-release";
        let v1 = incompressible_body(59);
        let marker = write_marker_path(&manager.get_new_metadata_file_path(key));
        // A HEAD miss captures first and creates the key's marker.
        let sibling = manager.capture_fill_witness(key).await;
        let created = sibling.lease.is_some() && marker.exists();
        // A repair fill on the same proxy captures next and witnesses the sibling's token.
        let repair = manager.capture_fill_witness(key).await;
        let same_token = repair.token().is_some() && repair.token() == sibling.token();
        // The HEAD's store is skipped on slot contention: its witness is dropped unconsulted.
        drop(sibling);
        let released = marker_gone_within(&marker, Duration::from_secs(1)).await;
        // No write of the key was acknowledged. The repair fill publishes and is folded.
        fill_v1(&manager, key, &v1, repair).await;
        consolidate(&manager).await;
        let served = served(&manager, key).await;
        assert!(
            created && same_token,
            "fixture: the sibling creates the marker and the repair witnesses its token \
             (created: {created}, same token: {same_token})"
        );
        assert!(
            served.as_deref() == Some(&v1[..]),
            "a repair fill was refused as superseded although no write of the key was \
             acknowledged; a sibling fill on the same proxy cached nothing and its release \
             removed the marker the repair witnessed (marker released: {released}, served: {})",
            match &served {
                Some(b) => format!("{} bytes", b.len()),
                None => "no .meta".to_string(),
            }
        );
    }

    /// The witness is not weakened: a write acknowledged after a shared capture still refuses it.
    #[tokio::test]
    async fn a_write_acknowledged_after_a_shared_capture_still_refuses_the_fill() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case26-superseded";
        let v1 = incompressible_body(60);
        let sibling = manager.capture_fill_witness(key).await;
        let repair = manager.capture_fill_witness(key).await;
        let shared = repair.lease.is_some();
        assert!(
            shared,
            "fixture: the repair capture must share the sibling's lease, or this shows only that \
             a lone witness is refused"
        );
        // A PUT of the key is acknowledged after the repair's S3 request began.
        manager
            .invalidate_for_write(key)
            .await
            .expect("fixture: the write's stamp must land");
        drop(sibling);
        fill_v1(&manager, key, &v1, repair).await;
        consolidate(&manager).await;
        let served = served(&manager, key).await;
        assert!(
            served.is_none(),
            "a fill whose S3 request began before an acknowledged write published its bytes \
             (shared lease: {shared}, served: {:?} bytes)",
            served.map(|b| b.len())
        );
    }

    /// holds for a shared marker: it is kept while any sharer may still publish, and removed
    /// once every one of them cached nothing.
    #[tokio::test]
    async fn a_shared_marker_is_released_once_every_sharer_caches_nothing() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case26-shared-release";
        let marker = write_marker_path(&manager.get_new_metadata_file_path(key));
        let first = manager.capture_fill_witness(key).await;
        let second = manager.capture_fill_witness(key).await;
        drop(first);
        let gone_early = marker_gone_within(&marker, Duration::from_millis(300)).await;
        drop(second);
        let gone = marker_gone_within(&marker, Duration::from_secs(3)).await;
        assert!(
            !gone_early,
            "the marker was released while a second fill that witnessed it could still publish"
        );
        assert!(
            gone,
            "a marker no fill cached under was left on the shared volume: {}",
            marker.display()
        );
    }

    /// the key's only lease has dropped and its release is waiting on the key's
    /// slot lock, held here as a busy volume holds it; a repair fill on the same proxy captures
    /// in that window. Returns the repair's witness and whether the marker was still present
    /// when it captured. The slot is free again on return.
    async fn capture_in_the_release_window(
        manager: &CacheManager,
        key: &str,
    ) -> (FillWitness, bool) {
        let marker = write_marker_path(&manager.get_new_metadata_file_path(key));
        let sibling = manager.capture_fill_witness(key).await;
        assert!(
            sibling.lease.is_some() && marker.exists(),
            "fixture: the sibling's capture must create the marker"
        );
        let slot = crate::metadata_lock_manager::try_acquire_slot_lock(&manager.cache_dir, key)
            .expect("fixture: hold the key's slot lock");
        drop(sibling);
        // The release has been spawned and finds the slot busy.
        tokio::time::sleep(Duration::from_millis(50)).await;
        let repair = manager.capture_fill_witness(key).await;
        let present = marker.exists();
        drop(slot);
        (repair, present)
    }

    /// Red before the fix: the repair captured after the last lease dropped, its release unlinked
    /// the marker once the slot was free, and the repair was refused as superseded.
    #[tokio::test]
    async fn a_capture_between_the_last_drop_and_the_unlink_still_publishes() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case27-release-window";
        let v1 = incompressible_body(61);
        let marker = write_marker_path(&manager.get_new_metadata_file_path(key));
        let (repair, present) = capture_in_the_release_window(&manager, key).await;
        let joined = repair.lease.is_some();
        // Past every try the release makes (about 0.6 s).
        tokio::time::sleep(Duration::from_millis(800)).await;
        let marker_after = marker.exists();
        fill_v1(&manager, key, &v1, repair).await;
        consolidate(&manager).await;
        let served = served(&manager, key).await;
        assert!(
            present,
            "fixture: the release must not have unlinked the marker before the repair captured"
        );
        assert!(
            served.as_deref() == Some(&v1[..]),
            "a repair fill that captured after the last sharer dropped but before its \
             release unlinked the marker was refused as superseded, although no write of the key \
             was acknowledged (joined the lease: {joined}, marker present after the release: \
             {marker_after}, served: {})",
            match &served {
                Some(b) => format!("{} bytes", b.len()),
                None => "no .meta".to_string(),
            }
        );
    }

    /// The witness is not weakened: in the same window, a write acknowledged after the capture
    /// still refuses the fill.
    #[tokio::test]
    async fn a_write_acknowledged_after_a_capture_in_the_release_window_refuses_the_fill() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case27-release-window-superseded";
        let v1 = incompressible_body(62);
        let (repair, present) = capture_in_the_release_window(&manager, key).await;
        let joined = repair.lease.is_some();
        manager
            .invalidate_for_write(key)
            .await
            .expect("fixture: the write's stamp must land");
        fill_v1(&manager, key, &v1, repair).await;
        consolidate(&manager).await;
        let served = served(&manager, key).await;
        assert!(
            present,
            "fixture: the release must not have unlinked the marker before the repair captured"
        );
        assert!(
            served.is_none(),
            "a fill whose S3 request began before an acknowledged write published its bytes \
             (joined the lease: {joined}, served: {:?} bytes)",
            served.map(|b| b.len())
        );
    }

    /// still holds for a lease joined in the release window: once that capture caches
    /// nothing too, the marker is removed.
    #[tokio::test]
    async fn a_marker_joined_in_the_release_window_is_released_once_nothing_cached() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case27-release-window-released";
        let marker = write_marker_path(&manager.get_new_metadata_file_path(key));
        let (repair, _) = capture_in_the_release_window(&manager, key).await;
        drop(repair);
        let gone = marker_gone_within(&marker, Duration::from_secs(3)).await;
        assert!(
            gone,
            "a marker no fill cached under was left on the shared volume: {}",
            marker.display()
        );
    }

    /// Red before the fix: the release's blocking task panicked, the `Err` arm returned without
    /// retiring or forgetting the entry, and the registry listed it with `retired == false` for
    /// the life of the process. No lease is left to drop, so nothing else would release it.
    #[tokio::test]
    async fn a_release_whose_task_did_not_finish_leaves_the_registry_consistent() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case5-release-task-did-not-finish";
        let meta_path = manager.get_new_metadata_file_path(key);
        let marker = write_marker_path(&meta_path);
        let witness = manager.capture_fill_witness(key).await;
        let token = witness.token().map(str::to_string);
        // Kept so the entry's own `retired` flag is readable after it is delisted.
        let entry = manager.fill_leases.lock().get(&meta_path).cloned();
        arm_fill_release_panic(key);
        drop(witness);
        // Past every try the release makes (about 0.6 s), with room for the panic to land.
        let deadline = tokio::time::Instant::now() + Duration::from_secs(3);
        while manager.fill_leases.lock().contains_key(&meta_path)
            && tokio::time::Instant::now() < deadline
        {
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
        let listed = manager.fill_leases.lock().contains_key(&meta_path);
        let retired = entry.as_ref().map(|e| e.state().retired);
        // The witness is not weakened: a later capture of the key must still take one. The
        // marker is still on the volume, so it witnesses the same token.
        let later = manager.capture_fill_witness(key).await;
        let later_token = later.token().map(str::to_string);
        assert!(
            entry.is_some() && token.is_some(),
            "fixture: the capture must create the marker and register an entry for the key \
             (token: {token:?})"
        );
        assert!(
            !listed && retired == Some(true),
            "the entry of a fill whose release task did not finish was left in the \
             registry (listed: {listed}, retired: {retired:?}, marker still present: {})",
            marker.exists()
        );
        assert!(
            later_token == token,
            "a later capture of the key must still witness the marker's token (token: \
             {token:?}, later: {later_token:?})"
        );
    }

    /// Red before the fix: a capture that read a sibling capture's marker between
    /// its `create_new` and its write took no witness, and its fill was refused.
    #[tokio::test]
    async fn a_capture_that_reads_a_siblings_marker_before_its_write_witnesses_the_token() {
        let dir = tempfile::TempDir::new().unwrap();
        let manager = setup(dir.path()).await;
        let key = "test-bucket/case27-empty-marker";
        let v1 = incompressible_body(63);
        let marker = write_marker_path(&manager.get_new_metadata_file_path(key));
        std::fs::create_dir_all(marker.parent().unwrap()).unwrap();
        // A sibling capture's `create_new` has run; its write lands 10 ms later.
        std::fs::File::create(&marker).unwrap();
        let token = WriteToken::fresh().0;
        let doc = serde_json::to_string(&WriteMarker {
            token: token.clone(),
            cache_key: key.to_string(),
        })
        .unwrap();
        let writer = {
            let marker = marker.clone();
            std::thread::spawn(move || {
                std::thread::sleep(Duration::from_millis(10));
                std::fs::write(&marker, doc).unwrap();
            })
        };
        let witness = manager.capture_fill_witness(key).await;
        writer.join().unwrap();
        let witnessed = witness.token().map(str::to_string);
        fill_v1(&manager, key, &v1, witness).await;
        consolidate(&manager).await;
        let served = served(&manager, key).await;
        assert!(
            served.as_deref() == Some(&v1[..]),
            "a capture that read a sibling capture's marker between its create and its \
             write took no witness, and the fill was refused although no write of the key was \
             acknowledged (witnessed: {witnessed:?}, sibling's token: {token}, served: {})",
            match &served {
                Some(b) => format!("{} bytes", b.len()),
                None => "no .meta".to_string(),
            }
        );
    }
}
/// red side 4: write-order marker hygiene. A marker is never a cached object: a GET of a
/// key holding only a marker misses, the census counts no object for it, orphan reclamation
/// leaves a live object's ranges alone when a marker sits beside its `.meta`, and the reaper
/// removes a stale marker while keeping a fresh one.
#[cfg(test)]
mod marker_hygiene_tests {
    use super::zero_length_arm_orphan_tests::{
        incompressible_body, object_metadata, setup, BODY_LEN,
    };
    use super::*;

    #[tokio::test]
    async fn a_write_marker_reads_as_a_miss_and_is_counted_by_no_scan() {
        let temp = tempfile::TempDir::new().unwrap();
        let dir = temp.path();
        let manager = setup(dir).await;
        let tracker = manager
            .get_size_tracker()
            .await
            .expect("fixture: the size tracker must be wired");

        // A key holding only a marker: an acknowledged write whose store has not run.
        let only_marker = "case19-bucket/marker-only.bin";
        let token = manager.invalidate_for_write(only_marker).await.unwrap();
        let only_marker_meta = manager.get_new_metadata_file_path(only_marker);
        assert!(
            write_marker_holds(&only_marker_meta, &token) && !only_marker_meta.exists(),
            "fixture: the key holds the marker and no .meta"
        );

        // A live object with a marker beside its `.meta`: a fill published after the stamp.
        let live = "case19-bucket/live.bin";
        manager.invalidate_for_write(live).await.unwrap();
        let body = incompressible_body(7);
        let mut disk_cache = manager.create_configured_disk_cache_manager();
        disk_cache
            .store_range(
                live,
                0,
                BODY_LEN as u64 - 1,
                &body,
                object_metadata(BODY_LEN as u64, "\"case19-live\""),
                Duration::from_secs(315_360_000),
                true,
            )
            .await
            .expect("fixture: the fill must publish");
        let consolidator = manager.get_journal_consolidator().await.unwrap();
        consolidator.run_consolidation_cycle().await.unwrap();
        let live_meta = manager.get_new_metadata_file_path(live);
        assert!(
            live_meta.exists() && write_marker_path(&live_meta).exists(),
            "fixture: the live object's .meta and a marker sit side by side"
        );

        let miss = manager.get_metadata_from_disk(only_marker).await;
        tracker.perform_full_validation().await.unwrap();
        consolidator.run_consolidation_cycle().await.unwrap();
        let census = consolidator.load_size_state().await.unwrap().cached_objects;
        let pass = crate::orphan_reclaim::run_pass(
            dir,
            "case19-instance",
            crate::orphan_reclaim::PassBudget {
                leaves: 1_000_000,
                time: Duration::from_secs(60),
            },
        )
        .await;
        let live_doc = manager
            .get_metadata_from_disk(live)
            .await
            .unwrap()
            .expect("the live object's .meta must survive");
        let mut served = Vec::new();
        for range in &live_doc.ranges {
            served.extend(disk_cache.load_range_data(range).await.unwrap());
        }

        assert!(
            matches!(miss, Ok(None)),
            "a key holding only a marker must read as a miss, got {:?}",
            miss.map(|m| m.is_some())
        );
        assert_eq!(
            census, 1,
            "the census must count the live object and not the marker-only key"
        );
        assert_eq!(
            pass.reclaimed, 0,
            "orphan reclamation must not unlink a live object's ranges because of a marker"
        );
        assert!(
            served == body,
            "the live object must still serve its own bytes"
        );
    }

    #[test]
    fn the_reaper_removes_a_stale_marker_and_keeps_a_fresh_one() {
        let temp = tempfile::TempDir::new().unwrap();
        let dir = temp.path();
        std::fs::create_dir_all(dir.join("locks")).unwrap();
        let stamp = |key: &str| {
            let meta =
                crate::disk_cache::get_sharded_path(&dir.join("metadata"), key, ".meta").unwrap();
            let lock = crate::metadata_lock_manager::try_acquire_slot_lock(dir, key).unwrap();
            stamp_write_marker_locked(&meta, key, &WriteToken::fresh(), &lock).unwrap();
            drop(lock);
            write_marker_path(&meta)
        };
        let stale = stamp("case19-bucket/stale.bin");
        let fresh = stamp("case19-bucket/fresh.bin");
        let two_hours_ago = SystemTime::now() - Duration::from_secs(7200);
        filetime::set_file_mtime(&stale, filetime::FileTime::from_system_time(two_hours_ago))
            .unwrap();

        let stale_reaped = reap_write_marker_if_stale(dir, &stale, WRITE_MARKER_REAP_AGE);
        let fresh_reaped = reap_write_marker_if_stale(dir, &fresh, WRITE_MARKER_REAP_AGE);

        assert_eq!(
            (stale_reaped, stale.exists(), fresh_reaped, fresh.exists()),
            (true, false, false, true),
            "(stale reaped, stale present, fresh reaped, fresh present)"
        );
    }
}

/// Test-only: one retry scope's (running tasks, queued keys, pending keys). The per-scope form of
/// [`write_stamp_retry_active_keys`] and [`write_stamp_retry_overflow_keys`], which are
/// process-wide and so moved by parallel tests. A task holds one key, so tasks plus queued keys
/// is the pending set while no task is reloading from the log.
#[cfg(test)]
pub(crate) fn write_stamp_retry_scope_figures(scope: &Path) -> (usize, usize, usize) {
    let prefix = format!("{}\u{0}", scope.display());
    let st = lock_write_stamp_retries();
    let pending = st.keys.keys().filter(|k| k.starts_with(&prefix)).count();
    let (tasks, overflow) = st
        .dirs
        .get(scope)
        .map_or((0, 0), |d| (d.tasks, d.queue.len()));
    (tasks, overflow, pending)
}

/// Test-only: forget every in-memory retry of `scope`, as a process restart does. The
/// node-local log is left as it is.
#[cfg(test)]
pub(crate) fn forget_write_stamp_retry_scope(scope: &Path) {
    let prefix = format!("{}\u{0}", scope.display());
    let mut state = lock_write_stamp_retries();
    let st = &mut *state;
    st.keys.retain(|k, _| !k.starts_with(&prefix));
    st.log_tokens.retain(|k, _| !k.starts_with(&prefix));
    if let Some(dir) = st.dirs.remove(scope) {
        st.queued_keys = st.queued_keys.saturating_sub(dir.queue.len());
        let bytes: usize = dir.queue.iter().map(|s| write_stamp_overflow_cost(s)).sum();
        st.queued_bytes = st.queued_bytes.saturating_sub(bytes);
    }
}

/// the node-local pending-stamp log, its replay, spill and same-proxy guard, and a
/// simulated cache-volume failover across two proxies and a restart.
#[cfg(test)]
mod stamp_backlog_tests {
    use super::zero_length_arm_orphan_tests::{
        incompressible_body, object_metadata, setup, BODY_LEN,
    };
    use super::*;

    const LONG_TTL: Duration = Duration::from_secs(315_360_000);
    const LM: &str = "Wed, 21 Oct 2015 07:28:00 GMT";
    /// The design target: an FSx failover refuses every lock for 20-60 s.
    const OUTAGE: Duration = Duration::from_secs(60);

    fn refuse(keys: &[&str]) {
        for k in keys {
            crate::metadata_lock_manager::forced_retry_exhaustion::arm(k, u32::MAX);
        }
    }

    fn restore(keys: &[&str]) {
        for k in keys {
            crate::metadata_lock_manager::forced_retry_exhaustion::arm(k, 0);
        }
    }

    /// The bytes a GET would be served from the disk tier: the `.meta`'s ranges, loaded.
    async fn served(manager: &CacheManager, key: &str) -> Option<Vec<u8>> {
        let text = std::fs::read_to_string(manager.get_new_metadata_file_path(key)).ok()?;
        let meta: crate::cache_types::NewCacheMetadata = serde_json::from_str(&text).ok()?;
        let disk_cache = manager.create_configured_disk_cache_manager();
        let mut bytes = Vec::new();
        for range in &meta.ranges {
            bytes.extend(disk_cache.load_range_data(range).await.ok()?);
        }
        Some(bytes)
    }

    /// An acknowledged PUT's store: stamped and published.
    async fn put_published(manager: &CacheManager, key: &str, body: &[u8]) {
        let token = manager
            .invalidate_for_write(key)
            .await
            .expect("fixture: the stamp must land");
        let outcome = manager
            .store_put_as_write_cached_range_guarded(
                key,
                body,
                "\"v1\"".to_string(),
                LM.to_string(),
                None,
                HashMap::new(),
                token,
            )
            .await
            .expect("fixture: the store must not error");
        assert_eq!(outcome, PublishOutcome::Published, "fixture: v1 publishes");
    }

    /// What an acknowledged PUT's response path does
    /// (`SignedPutHandler::invalidate_prior_version_before_response`): stamp, and on failure
    /// hand the key to the retry. The response returns either way.
    async fn put_acknowledged(manager: &Arc<CacheManager>, key: &str) -> Option<WriteStampRetry> {
        match manager.invalidate_for_write(key).await {
            Ok(_) => None,
            Err(_) => Some(manager.spawn_write_stamp_retry(key)),
        }
    }

    /// The buffered GET-miss range fill (`prepare_range_store` + `finish`), witnessed.
    async fn fill_v1(manager: &CacheManager, key: &str, v1: &[u8], witness: FillWitness) {
        let mut disk_cache = manager.create_configured_disk_cache_manager();
        let prepared = disk_cache
            .prepare_range_store(
                key,
                0,
                BODY_LEN as u64 - 1,
                v1,
                object_metadata(BODY_LEN as u64, "\"v1\""),
                LONG_TTL,
                true,
            )
            .await
            .expect("fixture: the fill's .tmp write must succeed");
        if let Some(fill) = prepared {
            let _ = fill.with_fill_witness(Some(witness)).finish().await;
        }
    }

    async fn consolidate(manager: &CacheManager) {
        tokio::time::timeout(
            Duration::from_secs(60),
            manager
                .get_journal_consolidator()
                .await
                .expect("fixture: the consolidator must be wired")
                .run_consolidation_cycle(),
        )
        .await
        .expect("consolidation must finish")
        .expect("consolidation must not error");
    }

    async fn with_log(cache_dir: &Path, log_dir: &Path) -> Arc<CacheManager> {
        let manager = Arc::new(setup(cache_dir).await);
        manager.open_stamp_backlog(log_dir);
        manager.start_stamp_backlog_retries();
        manager
    }

    /// How long proxy B's RAM tier serves a range hit before re-checking the cache volume in the
    /// failover test (`cache.ram_cache_verification_interval`). Long enough that A's
    /// stamp lands inside it.
    const RAM_VERIFY: Duration = Duration::from_secs(15);

    /// `setup` with the RAM tier on (64 MiB) and its verification interval set.
    async fn setup_ram(cache_dir: &Path, verify: Duration) -> CacheManager {
        for sub in ["metadata/_journals", "size_tracking", "locks", "ranges"] {
            std::fs::create_dir_all(cache_dir.join(sub)).unwrap();
        }
        let mut manager = CacheManager::new_with_shared_storage(
            cache_dir.to_path_buf(),
            true,
            64 * 1024 * 1024,
            10 * 1024 * 1024 * 1024,
            CacheEvictionAlgorithm::TinyLFU,
            1024,
            true,
            std::time::Duration::from_secs(315_360_000),
            std::time::Duration::from_secs(3600),
            std::time::Duration::from_secs(3600),
            false,
            crate::config::SharedStorageConfig::default(),
            10.0,
            true,
            std::time::Duration::from_secs(86400),
            crate::config::MetadataCacheConfig::default(),
            95,
            80,
            true,
            std::time::Duration::from_secs(60),
            1_048_576,
            false,
            std::time::Duration::from_secs(10),
            64,
            std::time::Duration::from_secs(5),
        );
        manager.set_ram_cache_verification_interval(verify);
        let _ = manager.create_configured_disk_cache_manager();
        manager
            .initialize()
            .await
            .expect("fixture: initialize() must wire the hybrid metadata writer");
        manager
    }

    async fn with_log_ram(cache_dir: &Path, log_dir: &Path, verify: Duration) -> Arc<CacheManager> {
        let manager = Arc::new(setup_ram(cache_dir, verify).await);
        manager.open_stamp_backlog(log_dir);
        manager.start_stamp_backlog_retries();
        manager
    }

    /// The bytes a whole-object GET would be served from the RAM tier: the range hit and its
    /// verification against the cache volume, as `http_proxy`'s range path takes them.
    async fn served_from_ram(manager: &Arc<CacheManager>, key: &str) -> Option<Vec<u8>> {
        let hit = manager.get_range_from_ram_cache_hit(key, 0, BODY_LEN as u64 - 1, LONG_TTL)?;
        let cm = Arc::clone(manager);
        let verified = manager
            .ram_verify(key, &hit, |k| async move {
                cm.get_metadata_etag_for_ram_verify(&k).await
            })
            .await;
        verified.then(|| hit.data.to_vec())
    }

    /// A GET's disk hit on every stored range of `key`, which promotes each to the RAM tier.
    async fn promote_to_ram(manager: &Arc<CacheManager>, key: &str) -> bool {
        let Ok(text) = std::fs::read_to_string(manager.get_new_metadata_file_path(key)) else {
            return false;
        };
        let Ok(meta) = serde_json::from_str::<crate::cache_types::NewCacheMetadata>(&text) else {
            return false;
        };
        let disk_cache = Arc::new(tokio::sync::RwLock::new(
            manager.create_configured_disk_cache_manager(),
        ));
        let range_handler =
            crate::range_handler::RangeHandler::new(Arc::clone(manager), disk_cache);
        for spec in &meta.ranges {
            let range = Range {
                start: spec.start,
                end: spec.end,
                data: Vec::new(),
                etag: meta.object_metadata.etag.clone(),
                last_modified: meta.object_metadata.last_modified.clone(),
                compression_algorithm: spec.compression_algorithm.clone(),
            };
            if manager
                .load_range_data_with_cache(key, &range, &range_handler)
                .await
                .is_err()
            {
                return false;
            }
        }
        !meta.ranges.is_empty()
    }

    fn log_text(log_dir: &Path) -> String {
        std::fs::read_to_string(log_dir.join(crate::stamp_backlog::LOG_FILE_NAME))
            .unwrap_or_default()
    }

    async fn landed(gate: &write_stamp_retry_gate::Gate, within: Duration) -> bool {
        tokio::time::timeout(within, gate.stamped.notified())
            .await
            .is_ok()
    }

    fn multi_thread_runtime() -> tokio::runtime::Runtime {
        tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap()
    }

    /// A process exit: every task on its runtime ends, and its file descriptors close.
    fn kill(runtime: tokio::runtime::Runtime, manager: Arc<CacheManager>) {
        let scope = manager.stamp_retry_scope();
        if let Some(backlog) = manager.stamp_backlog.get() {
            backlog.release_for_restart();
        }
        drop(manager);
        std::thread::spawn(move || runtime.shutdown_timeout(Duration::from_secs(10)))
            .join()
            .unwrap();
        forget_write_stamp_retry_scope(&scope);
    }

    /// Red side 1 and the simulated failover. Two proxies, A and B, share one cache
    /// directory; each has its own node-local log. Every lock on the test's keys is refused for
    /// 60 s. During it A overwrites one key and deletes another, B does the same to two more,
    /// and A also overwrites a key whose older write B acknowledged and has not yet stored.
    /// Every write's response path returns; each failed stamp goes to its proxy's retry and
    /// log. A is restarted mid-outage (its runtime and memory dropped, a new manager over the
    /// same log). Then the outage ends.
    ///
    /// After recovery no GET on either proxy serves a replaced or deleted object's bytes,
    /// except the accepted peer-window residual, which the test constructs: B's older store
    /// publishes after the volume returns and before A's stamp for that key lands, and is
    /// served until that stamp lands.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn a_cache_volume_failover_with_a_restart_drops_no_acknowledged_invalidation() {
        let cache = tempfile::TempDir::new().unwrap();
        let log_a = tempfile::TempDir::new().unwrap();
        let log_b = tempfile::TempDir::new().unwrap();
        let c = cache.path().to_path_buf();
        let a_put = "test-bucket/case28-failover/a-put";
        let a_del = "test-bucket/case28-failover/a-del";
        let b_put = "test-bucket/case28-failover/b-put";
        let b_del = "test-bucket/case28-failover/b-del";
        let peer = "test-bucket/case28-failover/peer-window";
        let all = [a_put, a_del, b_put, b_del, peer];
        let v1 = incompressible_body(71);

        // B's RAM tier is on, so the test reads what it serves from RAM too.
        let b = with_log_ram(&c, log_b.path(), RAM_VERIFY).await;
        let rt_a = multi_thread_runtime();
        let a = {
            let (c, l) = (c.clone(), log_a.path().to_path_buf());
            rt_a.spawn(async move { with_log(&c, &l).await })
                .await
                .unwrap()
        };
        for k in [a_put, a_del, b_put, b_del] {
            put_published(&b, k, &v1).await;
        }
        // B acknowledged an older write of `peer`; its store has not run yet.
        let peer_older_token = b.invalidate_for_write(peer).await.unwrap();

        // The outage: every lock on these keys is refused, on both proxies.
        let b_put_gate = write_stamp_retry_gate::arm(b_put);
        b_put_gate.resume.notify_one();
        let b_del_gate = write_stamp_retry_gate::arm(b_del);
        b_del_gate.resume.notify_one();
        refuse(&all);
        let outage_began = std::time::Instant::now();
        let (a_put_ack, a_del_ack, peer_ack) = {
            let a = Arc::clone(&a);
            rt_a.spawn(async move {
                let put = put_acknowledged(&a, a_put).await;
                let del = a.invalidate_acknowledged_write(a_del, "DELETE").await;
                let peer = put_acknowledged(&a, peer).await;
                (put, del.is_err(), peer)
            })
            .await
            .unwrap()
        };
        let b_put_ack = put_acknowledged(&b, b_put).await;
        let b_del_ack = b
            .invalidate_acknowledged_write(b_del, "DELETE")
            .await
            .is_err();
        let a_log_lines = log_text(log_a.path()).lines().count();

        // A restarts mid-outage.
        tokio::time::sleep(OUTAGE / 3).await;
        kill(rt_a, a);
        let a_put_gate = write_stamp_retry_gate::arm(a_put);
        a_put_gate.resume.notify_one();
        let a_del_gate = write_stamp_retry_gate::arm(a_del);
        a_del_gate.resume.notify_one();
        let peer_gate = write_stamp_retry_gate::arm(peer);
        let rt_a2 = multi_thread_runtime();
        let a2 = {
            let c = c.clone();
            rt_a2
                .spawn(async move { Arc::new(setup(&c).await) })
                .await
                .unwrap()
        };
        let replayed = a2.open_stamp_backlog(log_a.path());
        let a2_pending_after_restart: Vec<bool> = [a_put, a_del, peer]
            .iter()
            .map(|k| a2.write_stamp_pending(k))
            .collect();
        {
            let a2 = Arc::clone(&a2);
            rt_a2
                .spawn(async move { a2.start_stamp_backlog_retries() })
                .await
                .unwrap();
        }

        // The outage ends.
        tokio::time::sleep(OUTAGE.saturating_sub(outage_began.elapsed())).await;
        restore(&all);
        let within = Duration::from_secs(30);
        let a_put_landed = landed(&a_put_gate, within).await;
        let a_del_landed = landed(&a_del_gate, within).await;
        let b_put_landed = landed(&b_put_gate, within).await;
        let b_del_landed = landed(&b_del_gate, within).await;

        // The accepted peer-window residual: B holds no pending stamp for `peer`, so its older
        // store publishes once the volume is back, before A's stamp for the key lands.
        let peer_gate_reached = tokio::time::timeout(within, peer_gate.reached.notified())
            .await
            .is_ok();
        let peer_older_store = b
            .store_put_as_write_cached_range_guarded(
                peer,
                &v1,
                "\"v1\"".to_string(),
                LM.to_string(),
                None,
                HashMap::new(),
                peer_older_token,
            )
            .await;
        let peer_served_in_window = served(&b, peer).await;
        // A GET on B inside the window puts the older copy in B's RAM tier.
        let peer_promoted = promote_to_ram(&b, peer).await;
        let peer_promoted_at = std::time::Instant::now();
        let peer_ram_in_window = served_from_ram(&b, peer).await;
        peer_gate.resume.notify_one();
        let peer_landed = landed(&peer_gate, within).await;
        // What B's RAM tier serves once A's stamp has landed: inside the verification interval,
        // and once it has passed since the copy was last checked.
        let peer_ram_after_landing = served_from_ram(&b, peer).await;
        let landed_inside_interval = peer_promoted_at.elapsed() < RAM_VERIFY;
        tokio::time::sleep(
            (RAM_VERIFY + Duration::from_millis(500)).saturating_sub(peer_promoted_at.elapsed()),
        )
        .await;
        let mut ram_served_old = Vec::new();
        for k in all {
            if served_from_ram(&b, k).await.as_deref() == Some(&v1[..]) {
                ram_served_old.push(k);
            }
        }
        let peer_ram_entry_dropped = b
            .get_range_from_ram_cache_hit(peer, 0, BODY_LEN as u64 - 1, LONG_TTL)
            .is_none();

        let mut served_old = Vec::new();
        for k in all {
            for (name, m) in [("A", &a2), ("B", &b)] {
                if served(m, k).await.as_deref() == Some(&v1[..]) {
                    served_old.push(format!("{name}:{k}"));
                }
            }
        }
        let pending_after: Vec<&str> = all
            .iter()
            .copied()
            .filter(|k| a2.write_stamp_pending(k) || b.write_stamp_pending(k))
            .collect();
        let a2_log_after = log_text(log_a.path());
        std::thread::spawn(move || rt_a2.shutdown_timeout(Duration::from_secs(10)))
            .join()
            .unwrap();

        assert!(
            a_put_ack.is_some()
                && a_del_ack
                && peer_ack.is_some()
                && b_put_ack.is_some()
                && b_del_ack,
            "fixture: every write's stamp must fail during the outage and its response path \
             return (A put {a_put_ack:?}, A delete failed {a_del_ack}, A peer-key put \
             {peer_ack:?}, B put {b_put_ack:?}, B delete failed {b_del_ack})"
        );
        assert!(
            ![a_put_ack, peer_ack, b_put_ack].contains(&Some(WriteStampRetry::Abandoned)),
            "no acknowledged write may be abandoned"
        );
        assert_eq!(
            a_log_lines, 3,
            "fixture: A's log holds one fsynced record per failed write before the restart"
        );
        // The served bytes first, so a restart that drops the pending stamps
        // fails on what a GET is served, not only on the replay count.
        assert!(
            served_old.is_empty(),
            "after recovery a GET is served a replaced or deleted object's bytes: {served_old:?} \
             (replayed {replayed} of 3, pending after restart {a2_pending_after_restart:?})"
        );
        assert!(
            replayed == 3 && a2_pending_after_restart.iter().all(|p| *p),
            "a restart mid-outage dropped A's pending stamps: replayed {replayed} of 3, pending \
             after restart (put, delete, peer key) {a2_pending_after_restart:?}"
        );
        assert!(
            a_put_landed && a_del_landed && b_put_landed && b_del_landed,
            "after the outage, the pending stamps must land (A put {a_put_landed}, A delete \
             {a_del_landed}, B put {b_put_landed}, B delete {b_del_landed})"
        );
        assert!(
            peer_gate_reached
                && matches!(peer_older_store, Ok(PublishOutcome::Published))
                && peer_served_in_window.as_deref() == Some(&v1[..]),
            "fixture: the accepted peer-window residual must be constructed: B's older store \
             of the key publishes and is served before A's stamp lands (reached {}, store {:?}, \
             served v1 {})",
            peer_gate_reached,
            peer_older_store,
            peer_served_in_window.as_deref() == Some(&v1[..])
        );
        assert!(peer_landed, "A's stamp for the peer-window key must land");
        assert!(
            peer_promoted && peer_ram_in_window.as_deref() == Some(&v1[..]),
            "fixture: a GET on B inside the window must put the older copy in B's RAM tier \
             (promoted {peer_promoted}, served from RAM {})",
            peer_ram_in_window.as_deref() == Some(&v1[..])
        );
        // The RAM half of the accepted peer-window residual, as CACHING.md states it.
        assert!(
            landed_inside_interval && peer_ram_after_landing.as_deref() == Some(&v1[..]),
            "after A's stamp lands, B's RAM tier serves its copy until \
             ram_cache_verification_interval has passed since the copy was last checked \
             (landed inside the interval {landed_inside_interval}, served from RAM {})",
            peer_ram_after_landing.as_deref() == Some(&v1[..])
        );
        assert!(
            ram_served_old.is_empty() && peer_ram_entry_dropped,
            "past ram_cache_verification_interval B's RAM tier must not serve a replaced or \
             deleted object: {ram_served_old:?} (peer-window RAM entry dropped \
             {peer_ram_entry_dropped})"
        );
        assert!(
            pending_after.is_empty() && a2_log_after.trim().is_empty(),
            "nothing may stay pending once every stamp landed: pending {pending_after:?}, A's \
             log {a2_log_after:?}"
        );
    }

    /// Red side 2: past the in-memory bound a failed stamp spills to the log and still lands.
    #[tokio::test]
    async fn a_write_past_the_memory_bound_spills_to_the_log_and_its_stamp_lands() {
        let cache = tempfile::TempDir::new().unwrap();
        let log = tempfile::TempDir::new().unwrap();
        let manager = with_log(cache.path(), log.path()).await;
        let busy = "test-bucket/case28-spill-busy";
        let key = "test-bucket/case28-spill";
        let v1 = incompressible_body(72);
        put_published(&manager, key, &v1).await;
        // The one task, held; and no room in the overflow queue.
        WRITE_STAMP_RETRY_MAX_TASKS_OVERRIDE.with(|c| c.set(Some(1)));
        WRITE_STAMP_OVERFLOW_MAX_BYTES_OVERRIDE.with(|c| c.set(Some(0)));
        let busy_gate = write_stamp_retry_gate::arm(busy);
        let busy_outcome = manager.spawn_write_stamp_retry(busy);
        let key_gate = write_stamp_retry_gate::arm(key);
        key_gate.resume.notify_one();
        crate::metadata_lock_manager::forced_retry_exhaustion::arm(key, 1);
        let outcome = put_acknowledged(&manager, key).await;
        WRITE_STAMP_OVERFLOW_MAX_BYTES_OVERRIDE.with(|c| c.set(None));
        WRITE_STAMP_RETRY_MAX_TASKS_OVERRIDE.with(|c| c.set(None));
        let pending_while_spilled = manager.write_stamp_pending(key);
        let served_before = served(&manager, key).await;
        busy_gate.resume.notify_one();
        let key_landed = landed(&key_gate, Duration::from_secs(30)).await;
        let served_after = served(&manager, key).await;
        assert_eq!(
            busy_outcome,
            WriteStampRetry::Started,
            "fixture: busy holds the task"
        );
        assert_eq!(
            served_before.as_deref(),
            Some(&v1[..]),
            "fixture: v1 is served before the stamp lands"
        );
        assert_eq!(
            outcome,
            Some(WriteStampRetry::Spilled),
            "past the in-memory bound the write must spill to the log, not be abandoned"
        );
        assert!(
            pending_while_spilled,
            "a spilled key is pending on this proxy"
        );
        assert!(
            key_landed && served_after.as_deref() != Some(&v1[..]),
            "a spilled write's stamp must land and the replaced object stop being served \
             (landed {key_landed}, still served v1 {})",
            served_after.as_deref() == Some(&v1[..])
        );
    }

    /// Red side 3: while this proxy holds a pending stamp for a key, its own older store and its
    /// own fill of the key decline.
    #[tokio::test]
    async fn this_proxys_older_store_and_fill_decline_while_its_stamp_is_pending() {
        let cache = tempfile::TempDir::new().unwrap();
        let log = tempfile::TempDir::new().unwrap();
        let manager = with_log(cache.path(), log.path()).await;
        let key = "test-bucket/case28-guard-store";
        let fill_key = "test-bucket/case28-guard-fill";
        let v1 = incompressible_body(73);
        // PUT v1 acknowledged; its store has not run yet.
        let older = manager.invalidate_for_write(key).await.unwrap();
        // A fill of `fill_key` begins.
        let witness = manager.capture_fill_witness(fill_key).await;
        // PUT v2 of `key` and DELETE of `fill_key` acknowledged; both stamps fail and their
        // retries are held.
        let key_gate = write_stamp_retry_gate::arm(key);
        let fill_gate = write_stamp_retry_gate::arm(fill_key);
        crate::metadata_lock_manager::forced_retry_exhaustion::arm(key, 1);
        crate::metadata_lock_manager::forced_retry_exhaustion::arm(fill_key, 1);
        let put = put_acknowledged(&manager, key).await;
        let del = manager
            .invalidate_acknowledged_write(fill_key, "DELETE")
            .await;
        let declined_before = write_stamp_pending_declined_total();
        let store = manager
            .store_put_as_write_cached_range_guarded(
                key,
                &v1,
                "\"v1\"".to_string(),
                LM.to_string(),
                None,
                HashMap::new(),
                older,
            )
            .await;
        fill_v1(&manager, fill_key, &v1, witness).await;
        consolidate(&manager).await;
        let declined_after = write_stamp_pending_declined_total();
        let store_served = served(&manager, key).await;
        let fill_served = served(&manager, fill_key).await;
        key_gate.resume.notify_one();
        fill_gate.resume.notify_one();
        let cleaned = landed(&key_gate, Duration::from_secs(30)).await
            && landed(&fill_gate, Duration::from_secs(30)).await;
        assert!(
            put == Some(WriteStampRetry::Started) && del.is_err(),
            "fixture: both stamps fail and go to the retry (put {put:?}, delete {del:?})"
        );
        assert!(
            !matches!(store, Ok(PublishOutcome::Published))
                && store_served.as_deref() != Some(&v1[..]),
            "an older store of a key with a pending stamp on this proxy published: {store:?}, \
             served v1 {}",
            store_served.as_deref() == Some(&v1[..])
        );
        assert!(
            fill_served.as_deref() != Some(&v1[..]),
            "a fill that began before this proxy's DELETE published while the DELETE's stamp \
             was pending: a GET is served the deleted object's bytes"
        );
        assert!(
            declined_after >= declined_before + 2,
            "both declines are counted ({declined_before} -> {declined_after})"
        );
        assert!(cleaned, "fixture: the held stamps land once released");
    }

    /// Red side 4: a torn final line is skipped and counted; the records before it replay.
    #[tokio::test]
    async fn a_torn_final_log_line_is_skipped_and_counted_at_startup() {
        let cache = tempfile::TempDir::new().unwrap();
        let log = tempfile::TempDir::new().unwrap();
        let manager = Arc::new(setup(cache.path()).await);
        let key = "test-bucket/case28-torn";
        let good = format!(
            "{{\"op\":\"pending\",\"dir\":{},\"key\":\"{key}\",\"token\":\"0123456789abcdef0123456789abcdef\",\"t\":1}}\n",
            serde_json::to_string(&cache.path().display().to_string()).unwrap()
        );
        std::fs::write(
            log.path().join(crate::stamp_backlog::LOG_FILE_NAME),
            format!("{good}{{\"op\":\"pend"),
        )
        .unwrap();
        let torn_before = crate::stamp_backlog::log_torn_records_total();
        let replayed = manager.open_stamp_backlog(log.path());
        let torn_after = crate::stamp_backlog::log_torn_records_total();
        let pending = manager.write_stamp_pending(key);
        let rewritten = log_text(log.path());
        assert!(
            replayed == 1 && pending,
            "a torn final line must not stop the log opening: replayed {replayed}, key pending \
             {pending}"
        );
        assert!(torn_after > torn_before, "the torn line is counted");
        assert!(
            !rewritten.contains("\"pend\n") && rewritten.lines().count() == 1,
            "the log is rewritten without the torn line: {rewritten:?}"
        );
    }

    /// a task that ends before its key's stamp lands leaves the key in
    /// the node-local log, and a later task reloads and lands it.
    #[tokio::test]
    async fn a_panicked_tasks_own_key_is_reloaded_from_the_log_and_lands() {
        let cache = tempfile::TempDir::new().unwrap();
        let log = tempfile::TempDir::new().unwrap();
        let manager = with_log(cache.path(), log.path()).await;
        let doomed = "test-bucket/case28-panics";
        let later = "test-bucket/case28-after-the-panic";
        write_stamp_retry_panic::arm(doomed);
        let doomed_gate = write_stamp_retry_gate::arm(doomed);
        doomed_gate.resume.notify_one();
        let doomed_outcome = manager.spawn_write_stamp_retry(doomed);
        // Wait for the panic: the key leaves memory but not the log.
        let deadline = std::time::Instant::now() + Duration::from_secs(10);
        while lock_write_stamp_retries().keys.contains_key(
            CacheManager::stamp_retry_slot(&manager.stamp_retry_scope(), doomed).as_ref(),
        ) && std::time::Instant::now() < deadline
        {
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
        let in_log_after_panic = log_text(log.path()).contains(doomed);
        // The second gate pass for `doomed`, when the reload hands it to a task.
        doomed_gate.resume.notify_one();
        let later_gate = write_stamp_retry_gate::arm(later);
        later_gate.resume.notify_one();
        let later_outcome = manager.spawn_write_stamp_retry(later);
        let later_landed = landed(&later_gate, Duration::from_secs(30)).await;
        let doomed_landed = landed(&doomed_gate, Duration::from_secs(30)).await;
        assert_eq!(
            (doomed_outcome, later_outcome),
            (WriteStampRetry::Started, WriteStampRetry::Started),
            "fixture"
        );
        assert!(
            in_log_after_panic,
            "the panicked task's key stays in the log"
        );
        assert!(
            later_landed && doomed_landed && !manager.write_stamp_pending(doomed),
            "the panicked task's key must be reloaded from the log and land (later {}, doomed \
             {})",
            later_landed,
            doomed_landed
        );
    }

    /// (re-pointing the test deleted): the production two-phase
    /// range store, `DiskCacheManager::store_range_shared_witnessed` with
    /// `SlotWait::WithinBudget`, does not hold the `DiskCacheManager` write guard while it waits
    /// for the key's slot lock, and still publishes once the slot frees.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn within_budget_range_store_waits_for_the_slot_without_the_write_guard() {
        use crate::disk_cache::{DiskCacheManager, SlotWait};
        const KEY: &str = "test-bucket/case28/within-budget-range.bin";
        const LEN: u64 = 4096;
        const BOUND: Duration = Duration::from_millis(1500);
        fn bin_count(dir: &Path) -> usize {
            fn walk(dir: &Path, n: &mut usize) {
                if let Ok(entries) = std::fs::read_dir(dir) {
                    for e in entries.flatten() {
                        let p = e.path();
                        if p.is_dir() {
                            walk(&p, n);
                        } else if p.extension().and_then(|x| x.to_str()) == Some("bin") {
                            *n += 1;
                        }
                    }
                }
            }
            let mut n = 0;
            walk(&dir.join("ranges"), &mut n);
            n
        }
        let temp = tempfile::TempDir::new().unwrap();
        let cache_dir = temp.path().to_path_buf();
        for sub in ["metadata/_journals", "size_tracking", "locks", "ranges"] {
            std::fs::create_dir_all(cache_dir.join(sub)).unwrap();
        }
        let manager = Arc::new(CacheManager::new_with_eviction_algorithm(
            cache_dir.clone(),
            false,
            0,
            CacheEvictionAlgorithm::TinyLFU,
        ));
        let dcm = Arc::new(tokio::sync::RwLock::new(
            manager.create_configured_disk_cache_manager(),
        ));
        let slot = crate::metadata_lock_manager::try_acquire_slot_lock(&cache_dir, KEY)
            .expect("fixture: take the key's slot lock");
        let store = {
            let dcm = Arc::clone(&dcm);
            tokio::spawn(async move {
                DiskCacheManager::store_range_shared_witnessed(
                    &dcm,
                    KEY,
                    0,
                    LEN - 1,
                    &vec![0x44; LEN as usize],
                    crate::cache_types::ObjectMetadata {
                        etag: "\"44444444444444444444444444444444\"".to_string(),
                        content_length: LEN,
                        last_modified: LM.to_string(),
                        upload_state: crate::cache_types::UploadState::Complete,
                        cumulative_size: LEN,
                        ..Default::default()
                    },
                    Duration::from_secs(3600),
                    false,
                    None,
                    SlotWait::WithinBudget,
                )
                .await
            })
        };
        tokio::time::sleep(Duration::from_millis(200)).await;
        let waiting = !store.is_finished();
        let started = std::time::Instant::now();
        let read = tokio::time::timeout(BOUND, dcm.read()).await;
        let waited = started.elapsed();
        let read_ok = read.is_ok();
        drop(read);
        drop(slot);
        let finished = tokio::time::timeout(Duration::from_secs(10), store).await;
        assert!(
            waiting,
            "fixture: the store must still be waiting on the held slot lock"
        );
        assert!(
            read_ok && waited < BOUND,
            "STALL: an unrelated disk_cache.read() waited {waited:?} while the WithinBudget \
             range store waited on the slot lock"
        );
        assert!(
            matches!(finished, Ok(Ok(Ok(())))),
            "the store must return once the slot is free: {finished:?}"
        );
        assert_eq!(
            bin_count(&cache_dir),
            1,
            "a fill that waited for the slot is published, not skipped"
        );
    }

    /// a `local_state_dir` inside `cache_dir`, or on a file system that is not a known
    /// node-local type, is refused with a named reason, never written, and the proxy runs in memory only with the metric set.
    #[tokio::test]
    async fn a_state_dir_on_the_cache_volume_is_refused_and_runs_memory_only() {
        let cache = tempfile::TempDir::new().unwrap();
        let other = tempfile::TempDir::new().unwrap();
        let inside = cache.path().join("state");
        let inside_reason = crate::stamp_backlog::local_state_dir_refusal(cache.path(), &inside);
        crate::stamp_backlog::ENFORCE_FS_TYPE_CHECK.with(|c| c.set(true));
        // the directory's own file system type must be a known node-local one.
        crate::stamp_backlog::FS_TYPE_OVERRIDE.with(|c| c.set(Some(Some(0x6969))));
        let same_fs_reason =
            crate::stamp_backlog::local_state_dir_refusal(cache.path(), other.path());
        crate::stamp_backlog::FS_TYPE_OVERRIDE.with(|c| c.set(None));
        crate::stamp_backlog::ENFORCE_FS_TYPE_CHECK.with(|c| c.set(false));
        let elsewhere = crate::stamp_backlog::local_state_dir_refusal(cache.path(), other.path());
        let manager = Arc::new(setup(cache.path()).await);
        manager.open_stamp_backlog(&inside);
        let backlog = manager.stamp_backlog.get().cloned().expect("a log is set");
        let memory_only = backlog.memory_only();
        let gauge = crate::stamp_backlog::log_memory_only();
        let appended = backlog
            .append_pending(
                &cache.path().display().to_string(),
                "test-bucket/case29-refused",
            )
            .is_ok();
        let created = inside.exists();
        assert!(
            inside_reason
                .as_deref()
                .is_some_and(|r| r.contains("inside cache_dir")),
            "a local_state_dir inside cache_dir must be refused with a named reason: \
             {inside_reason:?}"
        );
        assert!(
            same_fs_reason
                .as_deref()
                .is_some_and(|r| r.contains("0x00006969") && r.contains("node-local")),
            "a local_state_dir on an NFS file system must be refused with a named reason: \
             {same_fs_reason:?}"
        );
        assert_eq!(
            elsewhere, None,
            "fixture: the file-system-type check is off in tests"
        );
        assert!(
            memory_only && gauge >= 1,
            "a refused directory must run memory only and say so (memory_only {memory_only}, \
             write_stamp_log_memory_only {gauge})"
        );
        assert!(
            !created && !appended,
            "a refused directory must never be written (created {created}, appended {appended})"
        );
    }

    /// a `local_state_dir` on the same local file system as `cache_dir` (a local-disk
    /// cache on the root volume, which no other host can mount) keeps the durable log.
    #[tokio::test]
    async fn a_state_dir_on_the_same_local_file_system_keeps_the_log() {
        use std::os::unix::fs::MetadataExt;
        let cache = tempfile::TempDir::new().unwrap();
        let state = tempfile::TempDir::new().unwrap();
        let same_device = std::fs::metadata(cache.path()).unwrap().dev()
            == std::fs::metadata(state.path()).unwrap().dev();
        crate::stamp_backlog::ENFORCE_FS_TYPE_CHECK.with(|c| c.set(true));
        let reason = crate::stamp_backlog::local_state_dir_refusal(cache.path(), state.path());
        let manager = Arc::new(setup(cache.path()).await);
        manager.open_stamp_backlog(state.path());
        crate::stamp_backlog::ENFORCE_FS_TYPE_CHECK.with(|c| c.set(false));
        let backlog = manager.stamp_backlog.get().cloned().expect("a log is set");
        let memory_only = backlog.memory_only();
        let appended = backlog
            .append_pending(
                &cache.path().display().to_string(),
                "test-bucket/case30-same-local-device",
            )
            .is_ok();
        let logged =
            std::fs::read_to_string(state.path().join(crate::stamp_backlog::LOG_FILE_NAME))
                .unwrap_or_default()
                .contains("case30-same-local-device");
        assert!(
            same_device,
            "fixture: the cache and state directories must share one local device"
        );
        assert_eq!(
            reason, None,
            "a local_state_dir on cache_dir's own local file system must be accepted"
        );
        assert!(
            !memory_only && appended && logged,
            "a local_state_dir on cache_dir's own local file system must hold a durable log \
             (memory_only {memory_only}, appended {appended}, logged {logged})"
        );
    }

    /// a `local_state_dir` whose own file system is not a known node-local type
    /// (simulated: NFS) or whose type cannot be read is refused, and the proxy then runs in memory only without writing the directory.
    #[tokio::test]
    async fn a_state_dir_on_the_same_nfs_file_system_is_refused() {
        let cache = tempfile::TempDir::new().unwrap();
        let state = tempfile::TempDir::new().unwrap();
        let log = state.path().join("state");
        crate::stamp_backlog::ENFORCE_FS_TYPE_CHECK.with(|c| c.set(true));
        crate::stamp_backlog::FS_TYPE_OVERRIDE.with(|c| c.set(Some(Some(0x6969))));
        let nfs_reason = crate::stamp_backlog::local_state_dir_refusal(cache.path(), &log);
        let manager = Arc::new(setup(cache.path()).await);
        manager.open_stamp_backlog(&log);
        crate::stamp_backlog::FS_TYPE_OVERRIDE.with(|c| c.set(Some(None)));
        let unreadable_reason = crate::stamp_backlog::local_state_dir_refusal(cache.path(), &log);
        crate::stamp_backlog::FS_TYPE_OVERRIDE.with(|c| c.set(Some(Some(0xEF53))));
        let ext4_reason = crate::stamp_backlog::local_state_dir_refusal(cache.path(), &log);
        crate::stamp_backlog::FS_TYPE_OVERRIDE.with(|c| c.set(None));
        crate::stamp_backlog::ENFORCE_FS_TYPE_CHECK.with(|c| c.set(false));
        let backlog = manager.stamp_backlog.get().cloned().expect("a log is set");
        let memory_only = backlog.memory_only();
        let created = log.exists();
        assert!(
            nfs_reason
                .as_deref()
                .is_some_and(|r| r.contains("0x00006969") && r.contains("node-local")),
            "a local_state_dir on an NFS file system must be refused with a named reason: \
             {nfs_reason:?}"
        );
        assert!(
            memory_only && !created,
            "a refused directory must run memory only and never be written (memory_only \
             {memory_only}, created {created})"
        );
        assert!(
            unreadable_reason
                .as_deref()
                .is_some_and(|r| r.contains("could not be read")),
            "a directory whose file-system type cannot be read must be refused: \
             {unreadable_reason:?}"
        );
        assert_eq!(
            ext4_reason, None,
            "a directory on a local type (ext4) must be accepted"
        );
    }

    /// a readable log whose rewrite fails at startup (as a full or read-only root
    /// volume refuses the temp file) is replayed and guarded from memory, and each stamp lands.
    #[tokio::test]
    async fn a_readable_log_whose_rewrite_fails_at_startup_is_replayed_and_guarded() {
        let cache = tempfile::TempDir::new().unwrap();
        let log = tempfile::TempDir::new().unwrap();
        let keys = [
            "test-bucket/case29-rewrite-fails/a",
            "test-bucket/case29-rewrite-fails/b",
            "test-bucket/case29-rewrite-fails/c",
        ];
        let dir_json = serde_json::to_string(&cache.path().display().to_string()).unwrap();
        let text: String = keys
            .iter()
            .enumerate()
            .map(|(i, k)| {
                format!(
                    "{{\"op\":\"pending\",\"dir\":{dir_json},\"key\":\"{k}\",\"token\":\"{:032x}\",\"t\":1}}\n",
                    i + 1
                )
            })
            .collect();
        std::fs::write(log.path().join(crate::stamp_backlog::LOG_FILE_NAME), &text).unwrap();
        std::fs::create_dir(log.path().join("pending-stamps.log.tmp")).unwrap();
        let gates: Vec<write_stamp_retry_gate::Gate> = keys
            .iter()
            .map(|k| write_stamp_retry_gate::arm(k))
            .collect();
        for g in &gates {
            g.resume.notify_one();
        }
        let manager = Arc::new(setup(cache.path()).await);
        let replayed = manager.open_stamp_backlog(log.path());
        let memory_only = manager.stamp_backlog.get().is_some_and(|b| b.memory_only());
        let guarded: Vec<bool> = keys
            .iter()
            .map(|k| manager.pending_stamp_probe(k).pending())
            .collect();
        manager.start_stamp_backlog_retries();
        let mut all_landed = true;
        for g in &gates {
            all_landed &= landed(g, Duration::from_secs(30)).await;
        }
        let pending_after: Vec<bool> = keys
            .iter()
            .map(|k| manager.write_stamp_pending(k))
            .collect();
        assert!(
            replayed == 3 && guarded.iter().all(|p| *p),
            "a readable log whose rewrite failed at startup was not replayed and guarded: \
             replayed {replayed} of 3, guarded {guarded:?}"
        );
        assert!(memory_only, "the log must report memory-only mode");
        assert!(
            all_landed && pending_after.iter().all(|p| !*p),
            "every replayed stamp must land and clear (landed {all_landed}, pending after \
             {pending_after:?})"
        );
    }

    /// two failed writes of one key append in one order and reach the retry in the
    /// other. Once the retry's stamp lands nothing stays pending.
    #[tokio::test]
    async fn interleaved_appends_and_enqueues_of_one_key_leave_nothing_pending() {
        let cache = tempfile::TempDir::new().unwrap();
        let log = tempfile::TempDir::new().unwrap();
        let manager = with_log(cache.path(), log.path()).await;
        let key = "test-bucket/case29-interleave";
        let gate = write_stamp_retry_gate::arm(key);
        let older = manager.log_pending_stamp(key);
        let newer = manager.log_pending_stamp(key);
        let first = manager.enqueue_write_stamp_retry(key, newer.clone());
        let second = manager.enqueue_write_stamp_retry(key, older.clone());
        gate.resume.notify_one();
        let stamped = landed(&gate, Duration::from_secs(30)).await;
        let pending_after = manager.write_stamp_pending(key);
        let log_after = log_text(log.path());
        assert!(
            older
                .as_ref()
                .zip(newer.as_ref())
                .is_some_and(|(o, n)| o.0 < n.0)
                && first == WriteStampRetry::Started
                && second == WriteStampRetry::Joined
                && stamped,
            "fixture: two logged writes, the newer enqueued first, then one landing (older \
             {older:?}, newer {newer:?}, {first:?}, {second:?}, landed {stamped})"
        );
        assert!(
            !pending_after && !log_after.contains(key),
            "an interleaved append and enqueue pinned the key: pending after its stamp landed \
             {pending_after}, log {log_after:?}"
        );
    }

    /// UNRESOLVED, closed: a range fill journaled before this proxy's write was
    /// acknowledged is not folded while the write's stamp is pending here.
    #[tokio::test]
    async fn a_fill_journaled_before_this_proxys_write_does_not_fold_while_its_stamp_is_pending() {
        let cache = tempfile::TempDir::new().unwrap();
        let log = tempfile::TempDir::new().unwrap();
        let manager = with_log(cache.path(), log.path()).await;
        // As `HttpProxy::start` wires it: the consolidator reaches this proxy's pending stamps
        // through its manager.
        manager.set_cache_manager_in_consolidator().await;
        let key = "test-bucket/case29-fold";
        let v1 = incompressible_body(74);
        let witness = manager.capture_fill_witness(key).await;
        fill_v1(&manager, key, &v1, witness).await;
        let gate = write_stamp_retry_gate::arm(key);
        crate::metadata_lock_manager::forced_retry_exhaustion::arm(key, 1);
        let put = put_acknowledged(&manager, key).await;
        consolidate(&manager).await;
        let served_while_pending = served(&manager, key).await;
        gate.resume.notify_one();
        let stamped = landed(&gate, Duration::from_secs(30)).await;
        assert_eq!(
            put,
            Some(WriteStampRetry::Started),
            "fixture: the write's stamp fails and goes to the retry"
        );
        assert!(
            served_while_pending.as_deref() != Some(&v1[..]),
            "a fill journaled before this proxy's write was folded and served while the \
             write's stamp was pending: a GET is served the replaced object's bytes"
        );
        assert!(stamped, "fixture: the held stamp lands once released");
    }

    /// the production store for a non-empty signed PUT,
    /// `store_streamed_write_cache_metadata`, declines an older write while this proxy holds a
    /// pending stamp for the key.
    #[tokio::test]
    async fn this_proxys_older_streamed_store_declines_while_its_stamp_is_pending() {
        let cache = tempfile::TempDir::new().unwrap();
        let log = tempfile::TempDir::new().unwrap();
        let manager = with_log(cache.path(), log.path()).await;
        let key = "test-bucket/case29-streamed";
        let v1 = incompressible_body(75);
        let older = manager.invalidate_for_write(key).await.unwrap();
        let gate = write_stamp_retry_gate::arm(key);
        crate::metadata_lock_manager::forced_retry_exhaustion::arm(key, 1);
        let put = put_acknowledged(&manager, key).await;
        let mut sink = manager
            .open_write_cache_sink(key, BODY_LEN as u64)
            .await
            .unwrap()
            .expect("fixture: capacity must admit the sink");
        sink.write(&v1).unwrap();
        let (range_spec, pending) = sink.finalize_unpublished().unwrap();
        let mut om = object_metadata(BODY_LEN as u64, "\"v1\"");
        om.is_write_cached = true;
        let store = manager
            .store_streamed_write_cache_metadata(
                key,
                range_spec,
                om,
                LONG_TTL,
                pending,
                Some(older),
            )
            .await;
        drop(sink);
        let served_v1 = served(&manager, key).await.as_deref() == Some(&v1[..]);
        gate.resume.notify_one();
        let stamped = landed(&gate, Duration::from_secs(30)).await;
        assert_eq!(
            put,
            Some(WriteStampRetry::Started),
            "fixture: the newer write's stamp fails and goes to the retry"
        );
        assert!(
            !matches!(store, Ok(PublishOutcome::Published)) && !served_v1,
            "an older streamed store of a key with a pending stamp on this proxy published: \
             {store:?}, served v1 {served_v1}"
        );
        assert!(stamped, "fixture: the held stamp lands once released");
    }
}

#[cfg(test)]
mod writer_identity_tests {
    //! each writer records the identity of the file it published, so its ranges are
    //! verified when read. For each: the listing (the `.meta`, else the pending journal `Add`)
    //! carries `Some(identity)` equal to a `stat` of the published file, and a read through
    //! the listing is a hit (a read the identity check refuses is an error).
    use super::*;
    use crate::cache_types::{ObjectMetadata, RangeFileIdentity, RangeSpec, UploadState};
    use std::path::Path;
    use tempfile::TempDir;

    fn setup(dir: &Path) -> Arc<CacheManager> {
        for sub in ["metadata/_journals", "size_tracking", "locks", "ranges"] {
            std::fs::create_dir_all(dir.join(sub)).unwrap();
        }
        Arc::new(CacheManager::new_with_eviction_algorithm(
            dir.to_path_buf(),
            false,
            0,
            CacheEvictionAlgorithm::TinyLFU,
        ))
    }

    fn data(n: usize, seed: u8) -> Vec<u8> {
        (0..n).map(|i| ((i % 251) as u8) ^ seed).collect()
    }

    fn object_metadata(etag: &str, len: u64) -> ObjectMetadata {
        ObjectMetadata {
            etag: etag.to_string(),
            content_length: len,
            last_modified: "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
            upload_state: UploadState::Complete,
            cumulative_size: len,
            ..Default::default()
        }
    }

    async fn listing(manager: &CacheManager, key: &str, start: u64, end: u64) -> RangeSpec {
        if let Ok(Some(meta)) = manager.read_metadata_file(key).await {
            if let Some(r) = meta
                .ranges
                .iter()
                .find(|r| r.start == start && r.end == end)
            {
                return r.clone();
            }
        }
        manager
            .create_configured_disk_cache_manager()
            .find_pending_journal_ranges(key, start, end)
            .await
            .expect("pending lookup")
            .into_iter()
            .find(|r| r.start == start && r.end == end)
            .unwrap_or_else(|| panic!("no listing for {}-{} of {}", start, end, key))
    }

    async fn assert_recorded_and_hits(
        what: &str,
        dir: &Path,
        manager: &CacheManager,
        key: &str,
        start: u64,
        expected: &[u8],
    ) {
        let end = start + expected.len() as u64 - 1;
        let spec = listing(manager, key, start, end).await;
        let on_disk = std::fs::metadata(dir.join("ranges").join(&spec.file_path))
            .ok()
            .and_then(|m| RangeFileIdentity::of(&m));
        assert!(
            spec.file_identity.is_some(),
            "UNVERIFIED WRITER ({}): the listing for {}-{} records no file identity (the file \
             is {:?})",
            what,
            start,
            end,
            on_disk
        );
        assert_eq!(
            spec.file_identity, on_disk,
            "WRONG IDENTITY ({}): the listing records another file than the one published",
            what
        );
        let bytes = manager
            .create_configured_disk_cache_manager()
            .load_range_data(&spec)
            .await
            .unwrap_or_else(|e| panic!("({}) a read through the listing missed: {}", what, e));
        assert_eq!(bytes, expected, "({}) bytes read through the listing", what);
    }

    /// The streamed GET-miss fill (`finalize_incremental_range_unpublished`).
    #[tokio::test]
    async fn streamed_get_miss_fill_records_its_file_identity() {
        let dir = TempDir::new().unwrap();
        let manager = setup(dir.path());
        let key = "test-bucket/case31/writer-stream.bin";
        let d = data(200_000, 0x31);
        let dcm = manager.create_configured_disk_cache_manager();
        let mut writer = dcm
            .begin_incremental_range_write(key, 0, d.len() as u64 - 1, true)
            .await
            .expect("begin")
            .expect("a writer");
        crate::disk_cache::DiskCacheManager::write_range_chunk(&mut writer, &d).expect("write");
        dcm.commit_incremental_range(
            writer,
            object_metadata("\"w-stream\"", d.len() as u64),
            Duration::from_secs(3600),
        )
        .await
        .expect("commit");
        assert_recorded_and_hits("streamed GET-miss fill", dir.path(), &manager, key, 0, &d).await;
    }

    /// a cache copied to a new directory. Populated through the real writers (a
    /// GET range fill, a streamed GET-miss fill, a PUT write-through, a full-object store and a
    /// multipart completion) and consolidated, then copied with `cp`, and every range looked up
    /// and read through a manager opened on the copy (`find_cached_ranges`, `load_range_data`).
    /// A hit is the right bytes with no identity refusal and the range still listed; a miss is
    /// an error before any byte, an identity refusal, and the range healed (unlisted, unlinked).
    /// Per-range evidence (`serve_refusal_log`, keyed by the range's path) rather than the
    /// process-global counter, which parallel tests move.
    mod copied_cache {
        use super::*;
        use crate::cache_types::RangeLookupPurpose;

        #[derive(Clone, Copy, Debug, PartialEq)]
        enum CopyTool {
            /// `cp -a`: modification times kept to the nanosecond.
            Archive,
            /// `cp -r`: every file gets the copy's time.
            Plain,
            /// `cp -a`, then every `.bin`'s modification time truncated to whole seconds.
            WholeSeconds,
            /// `cp -a`, then truncated to whole milliseconds (what a copy onto EFS keeps).
            WholeMillis,
        }

        struct Cached {
            key: String,
            start: u64,
            bytes: Vec<u8>,
            identity: RangeFileIdentity,
        }

        impl Cached {
            fn end(&self) -> u64 {
                self.start + self.bytes.len() as u64 - 1
            }
        }

        async fn populate(dir: &Path, tag: &str) -> Vec<Cached> {
            let manager = setup(dir);
            let mut dcm = manager.create_configured_disk_cache_manager();
            let ttl = Duration::from_secs(3600);
            let mut filled: Vec<(String, u64, Vec<u8>)> = Vec::new();

            let key = format!("test-bucket/case32/{}/get.bin", tag);
            let d = data(150_000, 0x51);
            dcm.store_range(
                &key,
                0,
                d.len() as u64 - 1,
                &d,
                object_metadata("\"c-get\"", d.len() as u64),
                ttl,
                true,
            )
            .await
            .expect("GET range fill");
            filled.push((key, 0, d));

            let key = format!("test-bucket/case32/{}/stream.bin", tag);
            let d = data(150_000, 0x52);
            let mut writer = dcm
                .begin_incremental_range_write(&key, 0, d.len() as u64 - 1, true)
                .await
                .expect("begin")
                .expect("a writer");
            crate::disk_cache::DiskCacheManager::write_range_chunk(&mut writer, &d).expect("write");
            dcm.commit_incremental_range(
                writer,
                object_metadata("\"c-stream\"", d.len() as u64),
                ttl,
            )
            .await
            .expect("streamed fill");
            filled.push((key, 0, d));

            let key = format!("test-bucket/case32/{}/put.bin", tag);
            let d = data(150_000, 0x53);
            manager
                .store_put_as_write_cached_range(
                    &key,
                    &d,
                    "\"c-put\"".to_string(),
                    "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
                    None,
                    HashMap::new(),
                )
                .await
                .expect("PUT write-through");
            filled.push((key, 0, d));

            let key = format!("test-bucket/case32/{}/full.bin", tag);
            let d = data(150_000, 0x54);
            manager
                .store_full_object_as_range_new(
                    &key,
                    &d,
                    object_metadata("\"c-full\"", d.len() as u64),
                )
                .await
                .expect("full-object store");
            filled.push((key, 0, d));

            let path = format!("/test-bucket/case32/{}/mpu.bin", tag);
            let key = CacheManager::generate_cache_key(&path, None);
            let parts = [data(100_000, 0x55), data(100_000, 0x56)];
            manager
                .initiate_multipart_upload(&path)
                .await
                .expect("initiate");
            for (i, part) in parts.iter().enumerate() {
                manager
                    .store_multipart_part(&path, i as u32 + 1, part, format!("etag-part-{}", i + 1))
                    .await
                    .expect("part");
            }
            manager
                .complete_multipart_upload(&path)
                .await
                .expect("complete");
            filled.push((key.clone(), 0, parts[0].clone()));
            filled.push((key, parts[0].len() as u64, parts[1].clone()));

            let consolidator = manager
                .get_journal_consolidator()
                .await
                .expect("journal consolidator must be configured");
            let mut keys: Vec<&String> = filled.iter().map(|(k, _, _)| k).collect();
            keys.dedup();
            for key in keys {
                consolidator
                    .consolidate_object(key)
                    .await
                    .expect("consolidation");
            }
            let mut cached = Vec::new();
            for (key, start, bytes) in filled {
                let end = start + bytes.len() as u64 - 1;
                let spec = listing(&manager, &key, start, end).await;
                let identity = spec.file_identity.unwrap_or_else(|| {
                    panic!("fixture: {} {}-{} records its identity", key, start, end)
                });
                cached.push(Cached {
                    key,
                    start,
                    bytes,
                    identity,
                });
            }
            cached
        }

        fn copy_cache(src: &Path, dst: &Path, tool: CopyTool) {
            let flag = if tool == CopyTool::Plain { "-r" } else { "-a" };
            let status = std::process::Command::new("cp")
                .arg(flag)
                .arg(format!("{}/.", src.display()))
                .arg(dst)
                .status()
                .expect("run cp");
            assert!(status.success(), "cp {} failed", flag);
            if matches!(tool, CopyTool::WholeSeconds | CopyTool::WholeMillis) {
                use std::os::unix::fs::MetadataExt;
                for entry in walkdir::WalkDir::new(dst.join("ranges")) {
                    let entry = entry.unwrap();
                    if entry.path().extension().and_then(|e| e.to_str()) != Some("bin") {
                        continue;
                    }
                    let m = std::fs::metadata(entry.path()).unwrap();
                    let nanos = if tool == CopyTool::WholeSeconds {
                        0
                    } else {
                        m.mtime_nsec() / 1_000_000 * 1_000_000
                    };
                    filetime::set_file_mtime(
                        entry.path(),
                        filetime::FileTime::from_unix_time(m.mtime(), nanos as u32),
                    )
                    .unwrap();
                }
            }
        }

        /// Read `c` through a manager on the copy at `dir`. `Ok(())` for a hit, `Err(())` for a
        /// clean miss; panics on a wrong byte or a miss for any reason but the identity.
        async fn read_copied(
            manager: &CacheManager,
            dir: &Path,
            c: &Cached,
            tool: CopyTool,
        ) -> std::result::Result<(), ()> {
            let dcm = manager.create_configured_disk_cache_manager();
            let lookup = dcm
                .find_cached_ranges(
                    &c.key,
                    c.start,
                    c.end(),
                    None,
                    RangeLookupPurpose::FreshServe,
                )
                .await
                .expect("lookup on the copy");
            let spec = lookup
                .ranges
                .iter()
                .find(|r| r.start == c.start && r.end == c.end())
                .cloned()
                .unwrap_or_else(|| {
                    panic!(
                        "MIGRATION BLOCKED ({:?}): the copy's lookup does not list {}-{} of {}, \
                         a miss before the identity check",
                        tool,
                        c.start,
                        c.end(),
                        c.key
                    )
                });
            let bin = dir.join("ranges").join(&spec.file_path);
            let read = dcm.load_range_data(&spec).await;
            let refused = crate::disk_cache::serve_refusal_log::reasons(&spec.file_path)
                .contains(&"identity");
            let still_listed = manager
                .read_metadata_file(&c.key)
                .await
                .ok()
                .flatten()
                .is_some_and(|m| {
                    m.ranges
                        .iter()
                        .any(|r| r.start == c.start && r.end == c.end())
                });
            match read {
                Ok(bytes) => {
                    assert!(
                        bytes == c.bytes,
                        "WRONG BYTES SERVED FROM A COPY ({:?}): {} {}-{}",
                        tool,
                        c.key,
                        c.start,
                        c.end()
                    );
                    assert!(
                        !refused && still_listed && bin.exists(),
                        "({:?}) a hit must not refuse or heal: {} {}-{} (refused {}, listed {})",
                        tool,
                        c.key,
                        c.start,
                        c.end(),
                        refused,
                        still_listed
                    );
                    Ok(())
                }
                Err(e) => {
                    assert!(
                        refused,
                        "MIGRATION BLOCKED ({:?}): {} {}-{} missed for a reason other than the \
                         identity: {}",
                        tool,
                        c.key,
                        c.start,
                        c.end(),
                        e
                    );
                    assert!(
                        !still_listed && !bin.exists(),
                        "({:?}) a refused range must be healed: {} {}-{} (listed {}, file {})",
                        tool,
                        c.key,
                        c.start,
                        c.end(),
                        still_listed,
                        bin.exists()
                    );
                    Err(())
                }
            }
        }

        /// Whether the copy's file for `c` matches the identity the source recorded.
        fn copy_matches(dir: &Path, c: &Cached, file_path: &str) -> bool {
            std::fs::metadata(dir.join("ranges").join(file_path))
                .ok()
                .and_then(|m| RangeFileIdentity::of(&m))
                .is_some_and(|found| c.identity.matches(&found))
        }

        async fn case(tool: CopyTool, tag: &str) -> (Vec<bool>, Vec<bool>) {
            let src = TempDir::new().unwrap();
            let cached = populate(src.path(), tag).await;
            if tool == CopyTool::Plain {
                // Copy time well past every fill's clock tick, so `cp -r`'s stamps differ.
                std::thread::sleep(Duration::from_millis(50));
            }
            let dst = TempDir::new().unwrap();
            copy_cache(src.path(), dst.path(), tool);
            let manager = setup(dst.path());
            let mut expected = Vec::new();
            for c in &cached {
                let spec = listing(&manager, &c.key, c.start, c.end()).await;
                expected.push(copy_matches(dst.path(), c, &spec.file_path));
            }
            let mut hits = Vec::new();
            for c in &cached {
                hits.push(read_copied(&manager, dst.path(), c, tool).await.is_ok());
            }
            if tool == CopyTool::Plain {
                // The refill: the GET range written again on the copy is a hit.
                let c = &cached[0];
                manager
                    .create_configured_disk_cache_manager()
                    .store_range(
                        &c.key,
                        c.start,
                        c.end(),
                        &c.bytes,
                        object_metadata("\"c-get\"", c.bytes.len() as u64),
                        Duration::from_secs(3600),
                        true,
                    )
                    .await
                    .expect("refill on the copy");
                manager
                    .get_journal_consolidator()
                    .await
                    .expect("consolidator")
                    .consolidate_object(&c.key)
                    .await
                    .expect("consolidation");
                let spec = listing(&manager, &c.key, c.start, c.end()).await;
                let bytes = manager
                    .create_configured_disk_cache_manager()
                    .load_range_data(&spec)
                    .await
                    .expect("the refilled range is a hit");
                assert!(bytes == c.bytes, "the refill's bytes");
            }
            (expected, hits)
        }

        #[tokio::test]
        async fn a_cache_copied_with_cp_a_hits_every_range() {
            let (expected, hits) = case(CopyTool::Archive, "cp-a").await;
            assert!(expected.iter().all(|e| *e), "cp -a did not keep identities");
            assert!(
                hits.iter().all(|h| *h),
                "A COPIED CACHE MISSED: cp -a, hits {:?}",
                hits
            );
        }

        #[tokio::test]
        async fn a_cache_copied_with_cp_r_misses_heals_and_refills() {
            let (expected, hits) = case(CopyTool::Plain, "cp-r").await;
            assert!(
                expected.iter().all(|e| !*e),
                "precondition: cp -r gave every file a new modification time ({:?})",
                expected
            );
            assert!(
                hits.iter().all(|h| !*h),
                "cp -r: every range must miss and heal, hits {:?}",
                hits
            );
        }

        #[tokio::test]
        async fn a_cache_copied_with_whole_second_mtimes_misses_and_heals() {
            let (expected, hits) = case(CopyTool::WholeSeconds, "cp-sec").await;
            assert!(
                expected.iter().any(|e| !*e),
                "precondition: truncation moved at least one time out of the window ({:?})",
                expected
            );
            assert_eq!(
                hits, expected,
                "whole seconds: a range hits exactly when its truncated time is within the window"
            );
        }

        #[tokio::test]
        async fn a_cache_copied_with_whole_millisecond_mtimes_hits_every_range() {
            let (expected, hits) = case(CopyTool::WholeMillis, "cp-ms").await;
            assert!(
                expected.iter().all(|e| *e),
                "millisecond truncation left every identity within the window"
            );
            assert!(
                hits.iter().all(|h| *h),
                "A COPIED CACHE MISSED: whole milliseconds, hits {:?}",
                hits
            );
        }
    }

    /// A streamed fill this instance committed and the consolidator has not folded
    /// is listed by the fill-visibility tracker's document (`get_metadata_from_disk` with no
    /// `.meta`). That document's range is the spec `finalize_incremental_range_unpublished`
    /// built, identity included, so a read through it refuses another file at the path.
    #[tokio::test]
    async fn the_fill_visibility_listing_carries_the_fill_identity() {
        let dir = TempDir::new().unwrap();
        let manager = setup(dir.path());
        let key = "test-bucket/case33/tracker-identity.bin";
        let d = data(200_000, 0x41);
        let dcm = manager.create_configured_disk_cache_manager();
        let mut writer = dcm
            .begin_incremental_range_write(key, 0, d.len() as u64 - 1, true)
            .await
            .expect("begin")
            .expect("a writer");
        crate::disk_cache::DiskCacheManager::write_range_chunk(&mut writer, &d).expect("write");
        dcm.commit_incremental_range(
            writer,
            object_metadata("\"w-tracker\"", d.len() as u64),
            Duration::from_secs(3600),
        )
        .await
        .expect("commit");
        assert!(
            manager
                .read_metadata_file(key)
                .await
                .expect("read")
                .is_none(),
            "precondition: no .meta (the fill is not consolidated)"
        );
        assert!(
            manager.fill_visibility_tracker().lookup(key).is_some(),
            "precondition: the fill-visibility tracker holds the fill"
        );
        let tracked = manager
            .get_metadata_from_disk(key)
            .await
            .expect("read")
            .expect("precondition: the listing comes from the tracker's document");
        let spec = tracked.ranges[0].clone();
        let bin = dir.path().join("ranges").join(&spec.file_path);
        let on_disk = std::fs::metadata(&bin)
            .ok()
            .and_then(|m| RangeFileIdentity::of(&m));
        assert!(
            spec.file_identity.is_some(),
            "UNVERIFIED TRACKER LISTING: the fill-visibility document lists {}-{} with no file \
             identity (the file is {:?})",
            spec.start,
            spec.end,
            on_disk
        );
        assert_eq!(
            spec.file_identity, on_disk,
            "the tracker's listing records another file than the one published"
        );
        // Another file at the path, the same bytes and length, published a second later: only
        // its modification time differs (set explicitly, so not resting on the clock tick).
        let original = std::fs::read(&bin).unwrap();
        let tmp = bin.with_extension("scn7other");
        std::fs::write(&tmp, &original).unwrap();
        let later = spec.file_identity.unwrap().mtime_ns + 1_000_000_000;
        filetime::set_file_mtime(
            &tmp,
            filetime::FileTime::from_unix_time(
                later.div_euclid(1_000_000_000),
                later.rem_euclid(1_000_000_000) as u32,
            ),
        )
        .unwrap();
        std::fs::rename(&tmp, &bin).unwrap();
        let read = manager
            .create_configured_disk_cache_manager()
            .load_range_data(&spec)
            .await;
        assert!(
            read.is_err(),
            "UNVERIFIED TRACKER LISTING SERVED: a read through the tracker's listing returned \
             {:?} bytes from another file",
            read.as_ref().map(|b| b.len())
        );
        let reasons = crate::disk_cache::serve_refusal_log::reasons(&spec.file_path);
        assert!(
            reasons.contains(&"identity"),
            "the read was refused, but not by the identity check (reasons {:?})",
            reasons
        );
    }

    /// The PUT write-through sink (`WriteCacheRangeSink`).
    #[tokio::test]
    async fn put_write_through_records_its_file_identity() {
        let dir = TempDir::new().unwrap();
        let manager = setup(dir.path());
        let key = "test-bucket/case31/writer-put.bin";
        let d = data(200_000, 0x32);
        manager
            .store_put_as_write_cached_range(
                key,
                &d,
                "\"w-put\"".to_string(),
                "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
                None,
                HashMap::new(),
            )
            .await
            .expect("PUT write-through");
        assert_recorded_and_hits("PUT write-through", dir.path(), &manager, key, 0, &d).await;
    }

    /// `store_full_object_as_range_witnessed`.
    #[tokio::test]
    async fn full_object_store_records_its_file_identity() {
        let dir = TempDir::new().unwrap();
        let manager = setup(dir.path());
        let key = "test-bucket/case31/writer-full.bin";
        let d = data(200_000, 0x33);
        manager
            .store_full_object_as_range_new(key, &d, object_metadata("\"w-full\"", d.len() as u64))
            .await
            .expect("full-object store");
        assert_recorded_and_hits("full-object store", dir.path(), &manager, key, 0, &d).await;
    }

    /// `CacheManager::complete_multipart_upload`: each part's range.
    #[tokio::test]
    async fn complete_multipart_upload_records_each_parts_file_identity() {
        let dir = TempDir::new().unwrap();
        let manager = setup(dir.path());
        let path = "/test-bucket/case31/writer-mpu.bin";
        let key = CacheManager::generate_cache_key(path, None);
        let parts = [data(100_000, 0x34), data(100_000, 0x35)];
        manager
            .initiate_multipart_upload(path)
            .await
            .expect("initiate");
        for (i, part) in parts.iter().enumerate() {
            manager
                .store_multipart_part(path, i as u32 + 1, part, format!("etag-part-{}", i + 1))
                .await
                .expect("part");
        }
        manager
            .complete_multipart_upload(path)
            .await
            .expect("complete");
        assert_recorded_and_hits(
            "complete_multipart_upload part 1",
            dir.path(),
            &manager,
            &key,
            0,
            &parts[0],
        )
        .await;
        assert_recorded_and_hits(
            "complete_multipart_upload part 2",
            dir.path(),
            &manager,
            &key,
            parts[0].len() as u64,
            &parts[1],
        )
        .await;
    }
}

/// **The `max_cache_size` soft stop on read fills.**
///
/// Decision (Ed, 2026-10-14): "read caching should follow the same soft-stop logic as
/// write-thru". `disk_safety_refusal`'s component 1 declines a write-through upload once the
/// whole cache plus the incoming object would exceed `max_cache_size`; before this unit a
/// GET-miss fill was gated only by free space (`capacity_guard`), so heavy miss ingest could
/// take the cache far past its configured size — measured peaks at 729% of it.
///
/// # What these assertions read, and why not the return value
///
/// Every decline on a fill path returns `Ok(..)`, deliberately, because a decline must not look
/// like a failure to a caller that would log or propagate it. So the return value cannot
/// discriminate and the **filesystem** has to: no `.bin` published and no range listed in the
/// key's `.meta`.
///
/// # Why the seam is not vacuous
///
/// [`register_read_fill_bound_for_test`] inserts into `READ_FILL_BOUNDS`, the one registry
/// [`read_fill_refusal`] reads, through the same `register_read_fill_bound` the production
/// refresher calls. There is no test-only read path. The control arms below publish the
/// identical fixture with the figure moved, so an assertion cannot pass by the fill being
/// broken for some unrelated reason.
///
/// # What is NOT asserted here
///
/// `cache.read_fills_declined_max_cache_size_total` is a process-global counter and libtest
/// runs these as parallel threads in one process, so an exact delta on it cannot be asserted
/// safely (`testing.md`: "never assert an exact delta on a process-global counter"). The
/// counter's wire shape is covered by `tests/metrics_wire_shape_test.rs` and
/// `tests/test_otlp.rs`; its increment site is the single `fetch_add` in `read_fill_refusal`,
/// on the same branch that returns the reason these tests observe.
#[cfg(test)]
mod read_fill_max_cache_size_soft_stop_tests {
    use super::*;
    use std::collections::HashMap;

    /// Every awaited call is bounded, so a wedged fill fails with a message instead of hanging
    /// the suite.
    const BOUND: Duration = Duration::from_secs(30);
    const LIMIT: u64 = 1_000_000;
    const FILL_LEN: u64 = 4096;

    fn object_metadata(len: u64) -> crate::cache_types::ObjectMetadata {
        crate::cache_types::ObjectMetadata {
            etag: "\"case34-soft-stop\"".to_string(),
            last_modified: "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
            content_length: len,
            content_type: Some("application/octet-stream".to_string()),
            response_headers: HashMap::new(),
            upload_state: crate::cache_types::UploadState::Complete,
            cumulative_size: len,
            ..Default::default()
        }
    }

    /// A direct-mode `DiskCacheManager` on `cache_dir`: P1 (`store_range`) and P3a
    /// (`begin_incremental_range_write_for_read_fill`) publish their own `.bin` and `.meta`
    /// here, which is what the assertions read. Its `cache_dir` is the registry key.
    async fn direct_manager(cache_dir: &Path) -> crate::disk_cache::DiskCacheManager {
        let manager = crate::disk_cache::DiskCacheManager::new(
            cache_dir.to_path_buf(),
            true,
            1024,
            false,
            1_048_576,
        );
        tokio::time::timeout(BOUND, manager.initialize())
            .await
            .expect("initialize must not hang")
            .unwrap();
        manager
    }

    /// A `CacheManager` for the P4 full-object fill, with the free-space floor at `0` so the
    /// danger-band guard is disabled and `max_cache_size` is the only gate that can decline.
    /// That isolation is the point: a decline here has exactly one possible cause.
    async fn cache_manager(cache_dir: &Path) -> CacheManager {
        for sub in ["metadata/_journals", "size_tracking", "locks", "ranges"] {
            std::fs::create_dir_all(cache_dir.join(sub)).unwrap();
        }
        let mut manager = CacheManager::new_with_shared_storage(
            cache_dir.to_path_buf(),
            false,
            0,
            10 * 1024 * 1024 * 1024,
            CacheEvictionAlgorithm::TinyLFU,
            1024,
            true,
            std::time::Duration::from_secs(315360000),
            std::time::Duration::from_secs(3600),
            std::time::Duration::from_secs(3600),
            false,
            crate::config::SharedStorageConfig::default(),
            10.0,
            true,
            std::time::Duration::from_secs(86400),
            crate::config::MetadataCacheConfig::default(),
            95,
            80,
            true,
            std::time::Duration::from_secs(60),
            1_048_576,
            false,
            std::time::Duration::from_secs(10),
            64,
            std::time::Duration::from_secs(5),
        );
        manager.set_disk_safety_free_space_floor(0);
        let _ = manager.create_configured_disk_cache_manager();
        tokio::time::timeout(BOUND, manager.initialize())
            .await
            .expect("initialize must not hang")
            .unwrap();
        manager
    }

    /// (a) A range GET-miss fill with the cache already at `max_cache_size` writes no `.bin`
    /// and lists no range, and reports no error to the fill path that called it.
    ///
    /// A failure implicates the decline block at the head of
    /// `DiskCacheManager::prepare_range_store` (P1), which is where every read fill but the
    /// streamed tee lands.
    #[tokio::test]
    async fn a_range_fill_at_the_limit_publishes_nothing() {
        let temp = tempfile::TempDir::new().unwrap();
        let mut disk_cache = direct_manager(temp.path()).await;
        let _usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(LIMIT));
        let key = "case34-bucket/declined-range";

        let result = tokio::time::timeout(
            BOUND,
            disk_cache.store_range(
                key,
                0,
                FILL_LEN - 1,
                &vec![7u8; FILL_LEN as usize],
                object_metadata(FILL_LEN),
                Duration::from_secs(3600),
                true,
            ),
        )
        .await
        .expect("the fill must not hang");

        assert!(
            result.is_ok(),
            "a max_cache_size decline must not surface as an error to the fill path: {:?}",
            result.err()
        );
        assert!(
            !disk_cache
                .get_new_range_file_path(key, 0, FILL_LEN - 1)
                .exists(),
            "no .bin may be published for a range fill declined on max_cache_size"
        );
        assert!(
            !disk_cache.get_new_metadata_file_path(key).exists(),
            "no listing may be published for a range fill declined on max_cache_size"
        );
    }

    /// (b) The same for the full-object fill (P4), the production whole-object GET
    /// publication, which writes its own `.bin` and `.meta` and so is not covered by P1.
    #[tokio::test]
    async fn b_full_object_fill_at_the_limit_publishes_nothing() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = cache_manager(temp.path()).await;
        let _usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(LIMIT));
        let key = "case34-bucket/declined-full-object";

        let result = tokio::time::timeout(
            BOUND,
            manager.store_full_object_as_range_new(
                key,
                &vec![9u8; FILL_LEN as usize],
                object_metadata(FILL_LEN),
            ),
        )
        .await
        .expect("the fill must not hang");

        assert!(
            result.is_ok(),
            "a max_cache_size decline must not surface as an error: {:?}",
            result.err()
        );
        // Both halves, the check returns before any write,
        // so a `.bin` with no `.meta` would be an orphan the `.meta` assertion cannot see.
        assert_eq!(
            (
                manager.get_new_metadata_file_path(key).exists(),
                manager
                    .get_new_range_file_path(key, 0, FILL_LEN - 1)
                    .exists()
            ),
            (false, false),
            "(a .meta exists, a .bin exists): a full-object fill declined on max_cache_size must \
             publish neither"
        );
    }

    /// A `CacheManager` as [`cache_manager`] builds it, with `max_cache_size` set by the
    /// caller, so the registration test can use a limit any fill crosses.
    async fn cache_manager_with_max(cache_dir: &Path, max_cache_size: u64) -> Arc<CacheManager> {
        for sub in ["metadata/_journals", "size_tracking", "locks", "ranges"] {
            std::fs::create_dir_all(cache_dir.join(sub)).unwrap();
        }
        let mut manager = CacheManager::new_with_shared_storage(
            cache_dir.to_path_buf(),
            false,
            0,
            max_cache_size,
            CacheEvictionAlgorithm::TinyLFU,
            1024,
            true,
            std::time::Duration::from_secs(315360000),
            std::time::Duration::from_secs(3600),
            std::time::Duration::from_secs(3600),
            false,
            crate::config::SharedStorageConfig::default(),
            10.0,
            true,
            std::time::Duration::from_secs(86400),
            crate::config::MetadataCacheConfig::default(),
            95,
            80,
            true,
            std::time::Duration::from_secs(60),
            1_048_576,
            false,
            std::time::Duration::from_secs(10),
            64,
            std::time::Duration::from_secs(5),
        );
        manager.set_disk_safety_free_space_floor(0);
        let _ = manager.create_configured_disk_cache_manager();
        tokio::time::timeout(BOUND, manager.initialize())
            .await
            .expect("initialize must not hang")
            .unwrap();
        Arc::new(manager)
    }

    /// (f) **The production startup path registers the bound.**
    ///
    /// Every other test in this module registers its own bound, so all of them would pass with
    /// the production registration deleted or its key misspelled, and the soft stop would be
    /// inert on the fleet. This test registers nothing: it drives
    /// `start_put_usage_refresher`, the function `HttpProxy::start` calls unconditionally, and
    /// then asks `read_fill_refusal` about the manager's own `cache_dir`.
    ///
    /// `max_cache_size` is one byte, so the only way a fill is admitted afterwards is the bound
    /// not being there. The `before` arm is the positive control: a fresh temp directory has no
    /// entry in the process-wide registry, so a decline before the refresher ran would mean the
    /// test was reading someone else's key.
    #[tokio::test]
    async fn f_the_production_startup_path_registers_the_bound() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = cache_manager_with_max(temp.path(), 1).await;
        let before = read_fill_refusal(temp.path(), FILL_LEN);
        tokio::time::timeout(BOUND, manager.start_put_usage_refresher())
            .await
            .expect("start_put_usage_refresher must not hang");
        let after = read_fill_refusal(temp.path(), FILL_LEN);
        assert_eq!(
            (before.is_some(), after.is_some()),
            (false, true),
            "(declined before the production refresher started, declined after): the read-fill \
             bound must be published by the startup path itself, under the key \
             `read_fill_refusal` looks up, or the soft stop is inert however many tests \
             register one of their own"
        );
    }

    /// (c) The control: below the limit, both boundaries cache exactly as before.
    ///
    /// Without this the two declining arms above would pass against fills broken for some
    /// entirely unrelated reason, which is the recorded failure mode this suite keeps hitting.
    #[tokio::test]
    async fn c_below_the_limit_both_boundaries_still_cache() {
        let range_temp = tempfile::TempDir::new().unwrap();
        let mut disk_cache = direct_manager(range_temp.path()).await;
        let _range_usage = register_read_fill_bound_for_test(range_temp.path(), LIMIT, Some(0));
        let range_key = "case34-bucket/admitted-range";
        tokio::time::timeout(
            BOUND,
            disk_cache.store_range(
                range_key,
                0,
                FILL_LEN - 1,
                &vec![7u8; FILL_LEN as usize],
                object_metadata(FILL_LEN),
                Duration::from_secs(3600),
                true,
            ),
        )
        .await
        .expect("the fill must not hang")
        .expect("a fill below max_cache_size must succeed");
        assert!(
            disk_cache
                .get_new_range_file_path(range_key, 0, FILL_LEN - 1)
                .exists(),
            "a range fill below max_cache_size must publish its .bin"
        );

        let object_temp = tempfile::TempDir::new().unwrap();
        let manager = cache_manager(object_temp.path()).await;
        let _object_usage = register_read_fill_bound_for_test(object_temp.path(), LIMIT, Some(0));
        let object_key = "case34-bucket/admitted-full-object";
        tokio::time::timeout(
            BOUND,
            manager.store_full_object_as_range_new(
                object_key,
                &vec![9u8; FILL_LEN as usize],
                object_metadata(FILL_LEN),
            ),
        )
        .await
        .expect("the fill must not hang")
        .expect("a full-object fill below max_cache_size must succeed");
        assert!(
            manager.get_new_metadata_file_path(object_key).exists(),
            "a full-object fill below max_cache_size must publish its .meta"
        );
    }

    /// (d) An unknown usage figure caches. Fail open, R7.5's posture: silently ceasing to
    /// cache on a figure nobody could read is the worse failure, and the harder one to notice.
    ///
    /// The fixture is the one from (a) — already at the limit would decline — with the figure
    /// absent instead of present, so the two differ in exactly the input under test.
    #[tokio::test]
    async fn d_an_unknown_usage_figure_caches() {
        let temp = tempfile::TempDir::new().unwrap();
        let mut disk_cache = direct_manager(temp.path()).await;
        let _usage = register_read_fill_bound_for_test(temp.path(), LIMIT, None);
        let key = "case34-bucket/unknown-figure";

        tokio::time::timeout(
            BOUND,
            disk_cache.store_range(
                key,
                0,
                FILL_LEN - 1,
                &vec![7u8; FILL_LEN as usize],
                object_metadata(FILL_LEN),
                Duration::from_secs(3600),
                true,
            ),
        )
        .await
        .expect("the fill must not hang")
        .expect("an unreadable figure must not fail the fill");

        assert!(
            disk_cache
                .get_new_range_file_path(key, 0, FILL_LEN - 1)
                .exists(),
            "an unknown usage figure must fail OPEN: the fill is cached"
        );
    }

    /// (e) A streamed fill admitted below the limit completes and is cached even though the
    /// limit is crossed while it runs. The decision is taken once, at the start of the fill.
    ///
    /// The second `begin_...` call is a positive control inside the same test: it proves the
    /// figure really moved, so "the started fill still committed" cannot pass vacuously on a
    /// figure that never changed.
    #[tokio::test]
    async fn e_a_fill_admitted_below_the_limit_completes_across_the_crossing() {
        let temp = tempfile::TempDir::new().unwrap();
        let disk_cache = direct_manager(temp.path()).await;
        let usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(0));
        let key = "case34-bucket/streamed-across";

        let mut writer = tokio::time::timeout(
            BOUND,
            disk_cache.begin_incremental_range_write_for_read_fill(key, 0, FILL_LEN - 1, true),
        )
        .await
        .expect("the open must not hang")
        .expect("opening a fill below the limit is not an error")
        .expect("a fill below max_cache_size is admitted");

        // The cache crosses max_cache_size while the fill streams.
        usage.send_replace(Some((std::time::Instant::now(), LIMIT)));

        let declined_now = tokio::time::timeout(
            BOUND,
            disk_cache.begin_incremental_range_write_for_read_fill(
                "case34-bucket/after-crossing",
                0,
                FILL_LEN - 1,
                true,
            ),
        )
        .await
        .expect("the open must not hang")
        .expect("a decline is not an error");
        assert!(
            declined_now.is_none(),
            "apparatus: the figure must now decline a NEW fill, or this test's crossing \
             never happened and its real assertion is vacuous"
        );

        crate::disk_cache::DiskCacheManager::write_range_chunk(
            &mut writer,
            &vec![1u8; FILL_LEN as usize],
        )
        .unwrap();
        tokio::time::timeout(
            BOUND,
            disk_cache.commit_incremental_range(
                writer,
                object_metadata(FILL_LEN),
                Duration::from_secs(3600),
            ),
        )
        .await
        .expect("the commit must not hang")
        .expect("a fill admitted below the limit must still commit after the crossing");

        assert!(
            disk_cache
                .get_new_range_file_path(key, 0, FILL_LEN - 1)
                .exists(),
            "a streamed fill admitted below max_cache_size must publish its .bin even if the \
             limit is crossed while it runs"
        );
    }

    /// The reason label and the WARN name the bound and where the total is published, so an
    /// operator reading either can tell this apart from a free-space decline and act on it.
    #[test]
    fn the_decline_reason_and_warn_name_the_bound() {
        assert_eq!(
            READ_FILL_MAX_CACHE_SIZE_SKIP_REASON,
            "read_fill_max_cache_size"
        );
        assert_ne!(
            READ_FILL_MAX_CACHE_SIZE_SKIP_REASON,
            crate::capacity_guard::DANGER_BAND_SKIP_REASON,
            "a size decline and a free-space decline must not share a label"
        );
        for expected in [
            "max_cache_size",
            "cache.read_fills_declined_max_cache_size_total",
        ] {
            assert!(
                READ_FILL_MAX_CACHE_SIZE_WARN.contains(expected),
                "the WARN must name {expected}: {READ_FILL_MAX_CACHE_SIZE_WARN}"
            );
        }
    }

    // -----------------------------------------------------------------------------------------
    // the stop counts what this process admitted and the figure has not folded
    // -----------------------------------------------------------------------------------------
    //
    // The figure above is `size_state.json`'s total, rewritten only when a consolidation cycle
    // finishes its delta step: measured gaps with a median of 7 to 16 s and a maximum of
    // 33 s on FSx for NetApp ONTAP, during which every arrival was admitted at the offered rate
    // and the peak reached 112 to 137% of `max_cache_size`. These four assertions are about the
    // addend that stops a proxy outrunning its own reading, and about the one thing that can go
    // wrong with it in either direction: when the count is cleared.
    //
    // The figure is moved explicitly in each arm, so none of them can pass on a snapshot that
    // happened to refresh inside the admission window.

    /// The figure both arms start from, against [`LIMIT`].
    const FIGURE: u64 = 800_000;
    /// One admission, four of which are made.
    const ADMIT: u64 = 40_000;
    /// The figure once a cycle has folded those four admissions.
    const FOLDED_FIGURE: u64 = FIGURE + 4 * ADMIT;
    /// The probe fill for (a): admitted against the bare figure, declined once the four
    /// admissions are added to it.
    const PROBE_A: u64 = 100_000;
    /// The probe fill for (b): admitted against the folded figure alone, declined if the four
    /// admissions are added to it a second time.
    const PROBE_B: u64 = 30_000;
    /// (b)'s positive control, and (c)'s probe: declined against the folded figure, so a run of
    /// assertions cannot pass by the stop admitting everything.
    const PROBE_LARGE: u64 = 60_000;
    /// (c)'s refreshed figure. It moved, by a peer's folded admission, without folding this
    /// process's own, so "the snapshot never refreshed" cannot explain (c)'s verdict.
    const PEER_FIGURE: u64 = FIGURE + 5_000;

    /// Credit `count` admissions through `SizeAccumulator::add_range`, the chokepoint every
    /// production credit site reaches and the only place the count is incremented.
    fn admit_four(accumulator: &crate::journal_consolidator::SizeAccumulator, tag: &str) {
        for i in 0..4 {
            assert!(
                accumulator.add_range(&format!("case35-bucket/{tag}-{i}"), 0, ADMIT - 1, ADMIT),
                "apparatus: each fixture range must be a fresh credit, not a dedup skip"
            );
        }
    }

    /// (a). **With the figure frozen, a proxy crosses the stop on its own admissions.**
    ///
    /// The figure is never moved in this test, which is the state a proxy is in for up to one
    /// consolidation cycle after it starts filling: `size_state.json` says 800 KB of a 1 MB
    /// limit and will keep saying so for seconds. Four 40 KB fills land, and the fifth must be
    /// declined on them even though nothing the volume holds has changed.
    ///
    /// Red side (verbatim): the count not added — drop `unconsolidated_admitted_bytes` from
    /// `read_fill_refusal`'s total and the probe is admitted, because the frozen figure plus
    /// 100 KB is still under the limit.
    #[tokio::test]
    async fn g_admissions_cross_the_stop_while_the_figure_is_frozen() {
        let temp = tempfile::TempDir::new().unwrap();
        let _usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(FIGURE));
        let accumulator = crate::journal_consolidator::SizeAccumulator::new(
            temp.path(),
            "case35-frozen".to_string(),
        );

        let before = read_fill_refusal(temp.path(), PROBE_A);
        admit_four(&accumulator, "frozen");
        let after = read_fill_refusal(temp.path(), PROBE_A);

        assert_eq!(
            (before.is_some(), after.is_some()),
            (false, true),
            "(declined before this proxy's own admissions, declined after): the figure is \
             frozen at {FIGURE} of {LIMIT} in both arms, so a stop that reads only the \
             figure admits every fill until a consolidation cycle rewrites it, which is the \
             overshoot measured"
        );
    }

    /// (b). **A figure that has folded the admissions does not count them twice.**
    ///
    /// The fixture flushes the accumulator, which writes the delta file carrying the four
    /// admissions, then deletes that file as a consolidation cycle's
    /// `delete_applied_delta_files` does after persisting, then publishes the figure the cycle
    /// persisted. The probe must be admitted: the bytes are in the figure exactly once.
    ///
    /// Red side (verbatim): no release, the stop over-declines — skip
    /// `release_consumed_delta_files` in the refresher and the probe is declined against a
    /// figure that already contains the bytes.
    #[tokio::test]
    async fn h_a_folded_figure_stops_counting_the_admissions_again() {
        let temp = tempfile::TempDir::new().unwrap();
        let usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(FIGURE));
        let accumulator = crate::journal_consolidator::SizeAccumulator::new(
            temp.path(),
            "case35-folded".to_string(),
        );
        admit_four(&accumulator, "folded");
        tokio::time::timeout(BOUND, accumulator.flush())
            .await
            .expect("the flush must not hang")
            .expect("the flush must write its delta file");
        let delta_file = sole_delta_file(temp.path());

        // The cycle: apply, persist, then delete the file it applied.
        std::fs::remove_file(&delta_file).expect("the delta file must be removable");
        usage.send_replace(Some((std::time::Instant::now(), FOLDED_FIGURE)));
        let consumed = tokio::time::timeout(BOUND, consumed_delta_files(temp.path()))
            .await
            .expect("the consumed-file read must not hang");
        release_consumed_delta_files(temp.path(), &consumed);

        assert_eq!(
            (
                consumed.len(),
                unconsolidated_admitted_bytes(temp.path()),
                read_fill_refusal(temp.path(), PROBE_B).is_some(),
                read_fill_refusal(temp.path(), PROBE_LARGE).is_some()
            ),
            (1, 0, false, true),
            "(files released, bytes still added, 30 KB declined, 60 KB declined): a figure \
             of {FOLDED_FIGURE} already contains the four admissions, so adding them \
             again declines a fill the cache has room for. The 60 KB arm is the positive \
             control: the stop still declines what genuinely does not fit, so the 30 KB arm \
             cannot pass by the decision having stopped working"
        );
    }

    /// (c). **A refresh that folded nothing resets nothing.**
    ///
    /// Identical to (b) except that the delta file is still on the volume: the cycle has not
    /// consumed it, so the figure cannot contain the bytes however recently it was read. The
    /// figure is moved to exactly the value (b) uses, so the two tests differ in one input —
    /// whether the file is gone — and a reset rule that cannot see the file reads them the
    /// same.
    ///
    /// Red side (verbatim): release on any refresh — release every pending record regardless
    /// of its file and the probe is admitted against a figure that does not contain the bytes,
    /// which is the overshoot again.
    #[tokio::test]
    async fn i_a_refresh_that_folded_nothing_keeps_the_count() {
        let temp = tempfile::TempDir::new().unwrap();
        let usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(FIGURE));
        let accumulator = crate::journal_consolidator::SizeAccumulator::new(
            temp.path(),
            "case35-unfolded".to_string(),
        );
        admit_four(&accumulator, "unfolded");
        tokio::time::timeout(BOUND, accumulator.flush())
            .await
            .expect("the flush must not hang")
            .expect("the flush must write its delta file");
        let delta_file = sole_delta_file(temp.path());

        // A refresh, with the delta file still pending: no cycle has applied it.
        usage.send_replace(Some((std::time::Instant::now(), PEER_FIGURE)));
        let consumed = tokio::time::timeout(BOUND, consumed_delta_files(temp.path()))
            .await
            .expect("the consumed-file read must not hang");
        release_consumed_delta_files(temp.path(), &consumed);

        assert_eq!(
            (
                delta_file.exists(),
                consumed.len(),
                unconsolidated_admitted_bytes(temp.path()),
                read_fill_refusal(temp.path(), PROBE_LARGE).is_some()
            ),
            (true, 0, 4 * ADMIT, true),
            "(the delta file is still pending, files released, bytes still added, probe \
             declined): the file carrying these bytes has not been consumed, so a refresh of \
             the figure proves nothing about them and dropping them lets the proxy outrun its \
             reading again"
        );
    }

    /// This instance's one pending delta file. Fails rather than returning an Option: every
    /// caller above has just flushed exactly one.
    fn sole_delta_file(cache_dir: &Path) -> PathBuf {
        let mut found: Vec<PathBuf> = std::fs::read_dir(cache_dir.join("size_tracking"))
            .expect("size_tracking must exist after a flush")
            .filter_map(|entry| entry.ok().map(|e| e.path()))
            .filter(|p| {
                p.file_name()
                    .and_then(|n| n.to_str())
                    .is_some_and(|n| n.starts_with("delta_") && n.ends_with(".json"))
            })
            .collect();
        assert_eq!(
            found.len(),
            1,
            "apparatus: a flush with a non-zero delta must leave exactly one delta file, \
             found {found:?}"
        );
        found.pop().unwrap()
    }

    /// wiring. **The credit chokepoint is what increments the count, and a dedup skip
    /// does not.**
    ///
    /// Without this, (a) to (c) would pass with the increment deleted from
    /// `SizeAccumulator::add_range` and some test-only call substituted: the count would be
    /// real and nothing on the fleet would ever raise it. `add_range` is the one branch through
    /// which a byte enters `size_state.json`'s total, reached by all four production credit
    /// sites, and the second call is the dedup arm, where another writer already holds these
    /// bytes in the shared total.
    #[tokio::test]
    async fn j_the_credit_chokepoint_increments_the_count_and_a_dedup_skip_does_not() {
        let temp = tempfile::TempDir::new().unwrap();
        let _usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(0));
        let accumulator = crate::journal_consolidator::SizeAccumulator::new(
            temp.path(),
            "case35-chokepoint".to_string(),
        );
        let key = "case35-bucket/chokepoint";

        let before = unconsolidated_admitted_bytes(temp.path());
        let credited = accumulator.add_range(key, 0, ADMIT - 1, ADMIT);
        let after_credit = unconsolidated_admitted_bytes(temp.path());
        let deduped = accumulator.add_range(key, 0, ADMIT - 1, ADMIT);
        let after_dedup = unconsolidated_admitted_bytes(temp.path());

        assert_eq!(
            (credited, deduped, before, after_credit, after_dedup),
            (true, false, 0, ADMIT, ADMIT),
            "(the first call credited, the second deduped, count before, after the credit, \
             after the dedup): the count must move with the accounted total and only with it"
        );
    }

    /// **Write-through admission takes the same correction.**
    ///
    /// `disk_safety_refusal`'s component 1 compares `size_state.json`'s total against
    /// `max_cache_size`, and that document has the same fold lag, so a run of uploads outran it
    /// the same way. The limit here is 200 KB and the figure is the real one for an empty
    /// volume, so the four admissions alone decide the verdict and no planted figure can be
    /// rewritten under the test by a consolidation cycle.
    ///
    /// The refresher is started through `start_put_usage_refresher`, the production call, which
    /// is also what enables the addend — so this test fails if production ever stops enabling
    /// it for this decision.
    #[tokio::test]
    async fn k_write_through_admission_counts_this_proxys_unfolded_admissions() {
        let temp = tempfile::TempDir::new().unwrap();
        let manager = cache_manager_with_max(temp.path(), 200_000).await;
        tokio::time::timeout(BOUND, manager.start_put_usage_refresher())
            .await
            .expect("start_put_usage_refresher must not hang");
        let consolidator = tokio::time::timeout(BOUND, manager.get_journal_consolidator())
            .await
            .expect("the consolidator read must not hang")
            .expect(
                "a shared-storage CacheManager must have a consolidator, or component 1 \
                     never runs and this test cannot see the addend at all",
            );

        let before = tokio::time::timeout(BOUND, manager.disk_safety_refusal(PROBE_A))
            .await
            .expect("the refusal must not hang");
        admit_four(consolidator.size_accumulator(), "write-through");
        let after = tokio::time::timeout(BOUND, manager.disk_safety_refusal(PROBE_A))
            .await
            .expect("the refusal must not hang");

        assert_eq!(
            (before.is_some(), after.is_some()),
            (false, true),
            "(declined before this proxy's own admissions, declined after): 160 KB admitted \
             plus a 100 KB upload is past a 200 KB max_cache_size, and the shared figure will \
             not say so until a consolidation cycle folds the delta"
        );
    }

    // -----------------------------------------------------------------------------------------
    // each delta file's bytes are released on that file's own fate, and the figure and
    // the addend are read as one pair
    // -----------------------------------------------------------------------------------------

    /// Credit `count` admissions of `bytes` each through `SizeAccumulator::add_range`, the
    /// chokepoint every production credit site reaches.
    fn admit_n(
        accumulator: &crate::journal_consolidator::SizeAccumulator,
        tag: &str,
        count: u64,
        bytes: u64,
    ) {
        for i in 0..count {
            assert!(
                accumulator.add_range(&format!("case37-bucket/{tag}-{i}"), 0, bytes - 1, bytes),
                "apparatus: each fixture range must be a fresh credit, not a dedup skip"
            );
        }
    }

    /// Flush the accumulator, bounded.
    async fn flush_once(accumulator: &crate::journal_consolidator::SizeAccumulator) {
        tokio::time::timeout(BOUND, accumulator.flush())
            .await
            .expect("the flush must not hang")
            .expect("the flush must succeed");
    }

    /// This instance's pending delta files, in no particular order. Empty when the directory
    /// does not exist: a flush with nothing to write never creates it.
    fn delta_files(cache_dir: &Path) -> Vec<PathBuf> {
        let Ok(entries) = std::fs::read_dir(cache_dir.join("size_tracking")) else {
            return Vec::new();
        };
        entries
            .filter_map(|entry| entry.ok().map(|e| e.path()))
            .filter(|p| {
                p.file_name()
                    .and_then(|n| n.to_str())
                    .is_some_and(|n| n.starts_with("delta_") && n.ends_with(".json"))
            })
            .collect()
    }

    /// (a). **A cycle that consumed a newer delta file releases that file only.**
    ///
    /// `collect_deltas` breaks out of its listing on a `read_dir` error and the cycle then
    /// deletes only what it collected, in listing order, so the set of this instance's files a
    /// cycle consumed is an arbitrary subset. Here the newer file is gone and the older one is
    /// still pending: no figure holds the older file's bytes, so they must stay counted.
    ///
    /// The pending file is the **older** one deliberately. With the pending file newest, the
    /// per-file rule and a newest-first prefix rule both release nothing and the assertion
    /// passes against either, which is the vacuity trap here.
    ///
    /// Red side (verbatim): the prefix rule — scan the records newest-first, release at the
    /// first absent file and treat every older record as released with it, so the pending older
    /// file's bytes leave the count while the figure does not hold them either, and the probe
    /// is admitted.
    #[tokio::test]
    async fn l_a_partial_collection_releases_only_the_file_it_consumed() {
        let temp = tempfile::TempDir::new().unwrap();
        let usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(FIGURE));
        let accumulator = crate::journal_consolidator::SizeAccumulator::new(
            temp.path(),
            "case37-partial".to_string(),
        );

        admit_n(&accumulator, "partial-old", 2, ADMIT);
        flush_once(&accumulator).await;
        let older = sole_delta_file(temp.path());
        admit_n(&accumulator, "partial-new", 2, ADMIT);
        flush_once(&accumulator).await;
        let newer = delta_files(temp.path())
            .into_iter()
            .find(|path| path != &older)
            .expect("apparatus: the second flush must write a second delta file");

        // The cycle collected the newer file only, applied it, persisted the figure, and
        // deleted what it applied.
        std::fs::remove_file(&newer).expect("the newer delta file must be removable");
        usage.send_replace(Some((std::time::Instant::now(), FIGURE + 2 * ADMIT)));
        let consumed = tokio::time::timeout(BOUND, consumed_delta_files(temp.path()))
            .await
            .expect("the consumed-file read must not hang");
        release_consumed_delta_files(temp.path(), &consumed);

        assert_eq!(
            (
                consumed.clone(),
                older.exists(),
                unconsolidated_admitted_bytes(temp.path()),
                read_fill_refusal(temp.path(), PROBE_LARGE).is_some()
            ),
            (vec![newer], true, 2 * ADMIT, true),
            "(files released, the older file is still pending, bytes still added, 60 KB \
             declined): the figure of {} holds the newer file's two admissions and not the \
             older file's, so releasing the older file's 80 KB with it puts those bytes in no \
             figure and no count, which is the overshoot the addend exists to remove",
            FIGURE + 2 * ADMIT
        );
    }

    /// (b). **A delta file renamed aside as corrupt releases nothing.**
    ///
    /// `collect_deltas` renames an unparseable `delta_*.json` to `{name}.corrupt` and applies
    /// nothing from it, so the record's path is gone while the figure never absorbed its bytes.
    /// Those bytes must stay counted until a validation census re-grounds the figure from the
    /// volume, which is what `note_accounting_reground` does.
    ///
    /// Red side (verbatim): absence alone releases — drop the `.corrupt` check from
    /// `consumed_delta_files`, so the rename releases bytes the figure never absorbed and the
    /// probe is admitted.
    #[tokio::test]
    async fn m_a_corrupt_aside_rename_releases_nothing() {
        let temp = tempfile::TempDir::new().unwrap();
        let _usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(FIGURE));
        let accumulator = crate::journal_consolidator::SizeAccumulator::new(
            temp.path(),
            "case37-corrupt".to_string(),
        );

        admit_n(&accumulator, "corrupt", 4, ADMIT);
        flush_once(&accumulator).await;
        let flushed = sole_delta_file(temp.path());
        // Exactly what `collect_deltas` does with an unparseable file: the whole name plus
        // `.corrupt`, and nothing applied from it.
        let aside = PathBuf::from(format!("{}.corrupt", flushed.display()));
        std::fs::rename(&flushed, &aside).expect("the rename aside must succeed");

        let consumed = tokio::time::timeout(BOUND, consumed_delta_files(temp.path()))
            .await
            .expect("the consumed-file read must not hang");
        release_consumed_delta_files(temp.path(), &consumed);

        assert_eq!(
            (
                flushed.exists(),
                aside.exists(),
                consumed.len(),
                unconsolidated_admitted_bytes(temp.path()),
                read_fill_refusal(temp.path(), PROBE_A).is_some()
            ),
            (false, true, 0, 4 * ADMIT, true),
            "(the delta file is gone, the aside file is there, files released, bytes still \
             added, 100 KB declined): nothing was applied from a file renamed aside, so the \
             figure of {FIGURE} will never hold these 160 KB and dropping them from the \
             count puts them in neither"
        );
    }

    /// (c). **The figure and the addend are read as one pair.**
    ///
    /// The refresher publishes the figure and only then releases the records that figure
    /// absorbed. A decision that read the figure first and the addend second could land between
    /// the two and pair the pre-refresh figure with the post-release addend, which under-states
    /// the total by the released bytes.
    ///
    /// The seam fires the whole refresh — publish the folded figure, release the consumed
    /// record — between the two reads. A 100 KB probe is declined against either consistent
    /// pair, 800 KB with 160 KB counted or 960 KB with nothing counted, and admitted only by
    /// the mixed pair, so this cannot pass by the figure or the release having gone missing.
    ///
    /// Red side (verbatim): the two-lock read — read the figure first, run the seam, then read
    /// the addend, which is the earlier order, and the probe is admitted on 800 KB plus a released
    /// addend of 0.
    #[tokio::test]
    async fn n_the_figure_and_the_addend_are_read_as_one_pair() {
        let temp = tempfile::TempDir::new().unwrap();
        let usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(FIGURE));
        let accumulator = crate::journal_consolidator::SizeAccumulator::new(
            temp.path(),
            "case37-pair".to_string(),
        );

        admit_n(&accumulator, "pair", 4, ADMIT);
        flush_once(&accumulator).await;
        let flushed = sole_delta_file(temp.path());

        let fired = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let hook_fired = Arc::clone(&fired);
        let hook_dir = temp.path().to_path_buf();
        let hook_file = flushed.clone();
        arm_paired_read_seam(
            temp.path(),
            Box::new(move || {
                // One consolidation cycle and one refresh, in production order: the cycle's
                // delete, the figure that contains those bytes, then the release.
                std::fs::remove_file(&hook_file).expect("the delta file must be removable");
                usage.send_replace(Some((std::time::Instant::now(), FOLDED_FIGURE)));
                release_consumed_delta_files(&hook_dir, std::slice::from_ref(&hook_file));
                hook_fired.store(true, std::sync::atomic::Ordering::SeqCst);
            }),
        );

        let declined = read_fill_refusal(temp.path(), PROBE_A).is_some();

        assert_eq!(
            (
                fired.load(std::sync::atomic::Ordering::SeqCst),
                unconsolidated_admitted_bytes(temp.path()),
                declined
            ),
            (true, 0, true),
            "(the refresh landed between the two reads, bytes still added afterwards, 100 KB \
             declined): {FIGURE} with the 160 KB counted and {FOLDED_FIGURE} with \
             nothing counted both decline this probe, so admitting it means the decision \
             paired the old figure with the released count"
        );
    }

    /// (d). **A validation census releases every pending record.**
    ///
    /// `SizeAccumulator::reset` is called when a census installs a size read from the volume
    /// itself, which already contains every byte written, and the same call deletes the delta
    /// files without applying them. Without this release the discarded credits would be added
    /// for the rest of the process's life.
    #[tokio::test]
    async fn o_a_census_reground_releases_every_pending_record() {
        let temp = tempfile::TempDir::new().unwrap();
        let _usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(FIGURE));
        let accumulator = crate::journal_consolidator::SizeAccumulator::new(
            temp.path(),
            "case37-census".to_string(),
        );

        admit_n(&accumulator, "census-flushed", 2, ADMIT);
        flush_once(&accumulator).await;
        // A second pair credited but not yet flushed, so the reset has both shapes to clear.
        admit_n(&accumulator, "census-unflushed", 2, ADMIT);
        let before = unconsolidated_admitted_bytes(temp.path());

        accumulator.reset();

        assert_eq!(
            (
                before,
                unconsolidated_admitted_bytes(temp.path()),
                pending_delta_record_count(temp.path())
            ),
            (4 * ADMIT, 0, 0),
            "(counted before the census, counted after, records left): the installed figure \
             was read from the volume, so it already holds every byte credited here"
        );
    }

    /// (e). **A flush whose credits and debits cancelled releases its own credits.**
    ///
    /// Nothing is written when the swapped deltas are all zero, so no file exists for a cycle
    /// to apply and the figure will never absorb those bytes: the eviction that cancelled them
    /// took them off the volume too.
    #[tokio::test]
    async fn p_a_zero_sum_flush_releases_its_own_credits() {
        let temp = tempfile::TempDir::new().unwrap();
        let _usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(FIGURE));
        let accumulator = crate::journal_consolidator::SizeAccumulator::new(
            temp.path(),
            "case37-zero-sum".to_string(),
        );

        let key = "case37-bucket/zero-sum";
        assert!(
            accumulator.add_range(key, 0, ADMIT - 1, ADMIT),
            "apparatus: the fixture range must be a fresh credit"
        );
        let before = unconsolidated_admitted_bytes(temp.path());
        accumulator.subtract_range(key, 0, ADMIT - 1, ADMIT);
        flush_once(&accumulator).await;

        assert_eq!(
            (
                before,
                delta_files(temp.path()).len(),
                unconsolidated_admitted_bytes(temp.path()),
                pending_delta_record_count(temp.path())
            ),
            (ADMIT, 0, 0, 0),
            "(counted before the flush, delta files written, counted after, records left): a \
             flush with nothing to write leaves no file for a cycle to consume, so a count \
             that waited for one would decline against these bytes for the rest of the \
             process's life"
        );
    }

    /// (f). **The record cap releases the oldest record.**
    ///
    /// One record per unconsumed flush, so reaching the cap means consolidation has not applied
    /// a delta for hours. Releasing the oldest under-states the addend, which is the direction
    /// that keeps the proxy caching on a volume whose accounting has stopped moving.
    #[tokio::test]
    async fn q_the_record_cap_releases_the_oldest_record() {
        let temp = tempfile::TempDir::new().unwrap();
        let _usage = register_read_fill_bound_for_test(temp.path(), LIMIT, Some(0));
        let accumulator = crate::journal_consolidator::SizeAccumulator::new(
            temp.path(),
            "case37-cap".to_string(),
        );

        // One flush per record, one admission each, one past the cap.
        let flushes = FLUSHED_DELTA_RECORD_CAP + 1;
        for i in 0..flushes {
            admit_n(&accumulator, &format!("cap-{i}"), 1, CAP_ADMIT);
            flush_once(&accumulator).await;
        }

        assert_eq!(
            (
                delta_files(temp.path()).len(),
                pending_delta_record_count(temp.path()),
                unconsolidated_admitted_bytes(temp.path())
            ),
            (
                flushes,
                FLUSHED_DELTA_RECORD_CAP,
                FLUSHED_DELTA_RECORD_CAP as u64 * CAP_ADMIT
            ),
            "(delta files on the volume, records kept, bytes counted): every file is still \
             pending, so the one byte-count missing from the addend is the oldest record's, \
             released by the cap"
        );
    }

    /// (f)'s admission, small enough that 257 of them stay well inside [`LIMIT`].
    const CAP_ADMIT: u64 = 1_000;
}
#[cfg(test)]
mod ram_range_hit_object_length_tests {
    use super::*;
    /// A middle range of a 20 MiB object, promoted to RAM. The RAM-hit serve in
    /// `http_proxy.rs` (the `verified_ram_hit` arm) builds `Content-Range: bytes S-E/<total>`
    /// from `RamRangeHit::content_length`, so it must be the object's length, not the range's.
    #[tokio::test(flavor = "multi_thread")]
    async fn partial_range_ram_hit_carries_the_object_length() {
        let temp_dir = tempfile::TempDir::new().unwrap();
        let cm = CacheManager::new(
            temp_dir.path().to_path_buf(),
            true,
            64 * 1024 * 1024,
            1024,
            true,
        );
        let key = "test-bucket/revalidate-object";
        let (start, end, total) = (8_388_608u64, 8_388_608u64 + 4095, 20_971_520u64);
        assert!(cm.promote_range_to_ram_cache_frame(
            key,
            (start, end),
            vec![7u8; 4096],
            crate::compression::CompressionAlgorithm::None,
            "\"revalidate\"".to_string(),
            String::new(),
            total,
        ));
        let mut hit = None;
        for _ in 0..200 {
            hit = cm.get_range_from_ram_cache_hit(key, start, end, Duration::from_secs(3600));
            if hit.is_some() {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        let hit = hit.expect("fixture: the promoted range must be readable from RAM");
        assert_eq!(
            hit.data.len(),
            4096,
            "fixture: the RAM hit returns the promoted bytes"
        );
        assert_eq!(
            hit.content_length, total,
            "a RAM hit for bytes {}-{} of a {}-byte object reports content_length {}; \
             the serve would answer Content-Range bytes {}-{}/{}",
            start, end, total, hit.content_length, start, end, hit.content_length
        );
    }
}

/// Recording a RAM-cache hit costs bounded, constant work per request.
#[cfg(test)]
mod ram_access_queue_bound_tests {
    use super::*;

    /// A flood of RAM hits, half exact-match and half page, spawns no task per hit and queues at
    /// most the queue's capacity; the drop counter accounts for every hit beyond it. The test
    /// runtime is single-threaded and the loop never yields, so the drain task has not run and
    /// every hit past the capacity must be dropped. Red side: `queue_ram_access` spawning a task
    /// per hit (the earlier spawn-per-hit recorder's shape), which leaves one live task per hit.
    #[tokio::test]
    async fn a_flood_of_ram_hits_spawns_no_task_per_hit_and_queues_at_most_the_capacity() {
        let metrics = tokio::runtime::Handle::current().metrics();
        let mut observed = Vec::new();
        for hits in [1_000usize, 10_000] {
            let dir = tempfile::TempDir::new().unwrap();
            let manager = CacheManager::new_with_eviction_algorithm(
                dir.path().to_path_buf(),
                true,
                64 * 1024 * 1024,
                CacheEvictionAlgorithm::TinyLFU,
            );
            let alive_before = metrics.num_alive_tasks();
            for i in 0..hits {
                if i % 2 == 0 {
                    manager
                        .queue_stored_range_access("test-bucket/access-queue/k", vec![(0, 1023)]);
                } else {
                    manager.queue_ram_page_access("test-bucket/access-queue/k", 0, 1023);
                }
            }
            observed.push((
                hits,
                metrics.num_alive_tasks().saturating_sub(alive_before),
                manager.ram_access_records_queued(),
                manager.ram_access_records_dropped(),
            ));
        }
        for &(hits, spawned, queued, dropped) in &observed {
            assert!(
                spawned <= 1,
                "RAM-HIT RECORDING UNBOUNDED: {hits} RAM hits left {spawned} tasks alive, expected \
                 at most the one drain task. Observed (hits, tasks, queued, dropped): {observed:?}"
            );
            assert_eq!(
                queued,
                RAM_ACCESS_QUEUE_CAPACITY.min(hits),
                "{hits} hits queued {queued} records; the queue holds at most its capacity. \
                 Observed: {observed:?}"
            );
            assert_eq!(
                queued as u64 + dropped,
                hits as u64,
                "every hit is either queued or counted as dropped. Observed: {observed:?}"
            );
        }
    }

    #[test]
    fn a_page_resolves_to_the_equal_stored_range_else_every_overlapping_one() {
        assert_eq!(
            resolve_page_extents(&[(0, 1023), (512, 1535)], 0, 1023),
            vec![(0, 1023)]
        );
        assert_eq!(
            resolve_page_extents(&[(0, 511), (512, 1023), (2048, 4095)], 0, 1023),
            vec![(0, 511), (512, 1023)]
        );
        assert!(resolve_page_extents(&[(2048, 4095)], 0, 1023).is_empty());
    }
}
/// The RAM-hit drain's `.meta` extent memo bounds `.meta` reads per key, for a key with
/// no `.meta` and for a cycle over more keys than the memo holds.
#[cfg(test)]
mod ram_page_extent_memo_tests {
    use super::*;
    use crate::cache_hit_update_buffer::CacheHitUpdateBuffer;
    use crate::fill_visibility_tracker::{FillVisibilityTracker, MarkerStamp, RangeFileStamp};

    struct Drain {
        tx: tokio::sync::mpsc::Sender<RamAccessRecord>,
        task: tokio::task::JoinHandle<()>,
        meta_reads: Arc<AtomicU64>,
        buffer: Arc<CacheHitUpdateBuffer>,
        cache_dir: PathBuf,
    }
    impl Drain {
        fn start(cache_dir: &Path) -> Self {
            Self::start_with(
                cache_dir,
                Arc::new(FillVisibilityTracker::new(Duration::from_secs(5))),
            )
        }
        fn start_with(cache_dir: &Path, tracker: Arc<FillVisibilityTracker>) -> Self {
            Self::start_limited(
                cache_dir,
                tracker,
                4 * 1024 * 1024,
                Arc::new(tokio::sync::Semaphore::new(32)),
            )
        }
        fn start_limited(
            cache_dir: &Path,
            tracker: Arc<FillVisibilityTracker>,
            max_metadata_file_bytes: u64,
            metadata_io_semaphore: Arc<tokio::sync::Semaphore>,
        ) -> Self {
            let buffer = Arc::new(CacheHitUpdateBuffer::new(
                cache_dir.to_path_buf(),
                "drain".to_string(),
            ));
            let slot = Arc::new(tokio::sync::RwLock::new(Some(buffer.clone())));
            let metadata_cache = Arc::new(crate::metadata_cache::MetadataCache::new(
                crate::metadata_cache::MetadataCacheConfig::default(),
            ));
            let meta_reads = Arc::new(AtomicU64::new(0));
            let (tx, rx) = tokio::sync::mpsc::channel(RAM_ACCESS_QUEUE_CAPACITY);
            let task = tokio::spawn(drain_ram_access_records(
                rx,
                slot,
                metadata_cache,
                cache_dir.to_path_buf(),
                tracker,
                max_metadata_file_bytes,
                metadata_io_semaphore,
                Some(meta_reads.clone()),
            ));
            Self {
                tx,
                task,
                meta_reads,
                buffer,
                cache_dir: cache_dir.to_path_buf(),
            }
        }
        async fn page(&self, key: &str) {
            self.tx
                .send(RamAccessRecord::Page {
                    cache_key: key.to_string(),
                    start: 0,
                    end: 1023,
                })
                .await
                .unwrap();
        }
        /// Closes the queue and waits for the drain to record everything sent. Returns the
        /// `.meta` reads and the hit buffer's distinct entries.
        async fn finish(self) -> (u64, usize) {
            drop(self.tx);
            self.task.await.unwrap();
            (
                self.meta_reads.load(AtomicOrdering::Relaxed),
                self.buffer.buffer_len().await,
            )
        }
    }
    impl Drain {
        /// Closes the queue, waits for the drain, flushes the hit buffer and returns the
        /// `(start, end)` of every journal line it wrote, in order.
        async fn finish_bounds(self) -> Vec<(u64, u64)> {
            drop(self.tx);
            self.task.await.unwrap();
            self.buffer.force_flush().await.unwrap();
            let journal = self
                .cache_dir
                .join("metadata")
                .join("_journals")
                .join("drain.journal");
            let text = std::fs::read_to_string(journal).unwrap_or_default();
            text.lines()
                .map(|line| {
                    let v: serde_json::Value = serde_json::from_str(line).unwrap();
                    (
                        v["range_spec"]["start"].as_u64().unwrap(),
                        v["range_spec"]["end"].as_u64().unwrap(),
                    )
                })
                .collect()
        }
    }
    fn paths(cache_dir: &Path) -> crate::disk_cache::DiskCacheManager {
        crate::disk_cache::DiskCacheManager::new(
            cache_dir.to_path_buf(),
            true,
            1024,
            true,
            1_048_576,
        )
    }
    fn write_meta(cache_dir: &Path, meta: &crate::cache_types::NewCacheMetadata) {
        let path = paths(cache_dir).get_new_metadata_file_path(&meta.cache_key);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(&path, serde_json::to_string(meta).unwrap()).unwrap();
    }
    fn ranged_meta(key: &str) -> crate::cache_types::NewCacheMetadata {
        ranged_meta_to(key, 1023)
    }
    fn ranged_meta_to(key: &str, end: u64) -> crate::cache_types::NewCacheMetadata {
        crate::cache_types::NewCacheMetadata {
            cache_key: key.to_string(),
            ranges: vec![crate::cache_types::RangeSpec::new(
                0,
                end,
                "drain.bin".to_string(),
                CompressionAlgorithm::Lz4,
                1024,
                1024,
            )],
            ..Default::default()
        }
    }

    /// A flood of Page records for a key with no `.meta` reads it once per memo window. Red side:
    /// the earlier drain, which memoised only a read that found and parsed a `.meta`.
    #[tokio::test]
    async fn page_records_for_a_key_with_no_meta_read_it_at_most_once_per_window() {
        let dir = tempfile::TempDir::new().unwrap();
        let drain = Drain::start(dir.path());
        const RECORDS: usize = 200;
        for _ in 0..RECORDS {
            drain.page("test-bucket/drain/absent").await;
        }
        let (reads, _) = drain.finish().await;
        assert!(
            reads <= 1,
            "PAGE-EXTENT MISS NOT MEMOISED: {RECORDS} Page records for a key with no `.meta` did \
             {reads} `.meta` reads, expected at most 1 per {RAM_PAGE_EXTENT_MEMO_TTL:?} window"
        );
    }

    /// Three passes over more keys than the memo holds, each key with a `.meta`, read well under
    /// one `.meta` per record: the first pass reads every key, later passes mostly hit. Red side:
    /// the earlier drain, which cleared the whole memo at the cap and so read once per record.
    #[tokio::test]
    async fn a_cycle_over_more_keys_than_the_memo_holds_does_not_read_once_per_record() {
        let dir = tempfile::TempDir::new().unwrap();
        let keys: Vec<String> = (0..RAM_PAGE_EXTENT_MEMO_MAX_KEYS + 76)
            .map(|i| format!("test-bucket/drain/cycle-{i}"))
            .collect();
        for key in &keys {
            write_meta(dir.path(), &ranged_meta(key));
        }
        let drain = Drain::start(dir.path());
        const PASSES: usize = 3;
        for _ in 0..PASSES {
            for key in &keys {
                drain.page(key).await;
            }
        }
        let (reads, _) = drain.finish().await;
        let records = PASSES * keys.len();
        eprintln!(
            "memo cycle: {reads} .meta reads for {records} records over {} keys",
            keys.len()
        );
        assert!(
            reads < 2 * keys.len() as u64,
            "PAGE-EXTENT MEMO THRASH: {PASSES} passes over {} keys ({records} Page records, memo \
             cap {RAM_PAGE_EXTENT_MEMO_MAX_KEYS}) did {reads} `.meta` reads, expected fewer than \
             {}; {records} is one read per record",
            keys.len(),
            2 * keys.len()
        );
    }
    /// A `.meta` larger than the drain's size cap records no extents, and the miss is
    /// memoised. Red side: the drain's bare `read_to_string`, which read and parsed it whatever
    /// its size (a lever that removes the size cap check).
    #[tokio::test]
    async fn an_oversized_meta_is_not_read_by_the_drain() {
        let dir = tempfile::TempDir::new().unwrap();
        const CAP: u64 = 64 * 1024;
        let key = "test-bucket/permit-test/oversized";
        let path = paths(dir.path()).get_new_metadata_file_path(key);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        let mut body = serde_json::to_string(&ranged_meta(key)).unwrap();
        body.push_str(&" ".repeat(CAP as usize + 1));
        std::fs::write(&path, body).unwrap();
        let drain = Drain::start_limited(
            dir.path(),
            Arc::new(FillVisibilityTracker::new(Duration::from_secs(5))),
            CAP,
            Arc::new(tokio::sync::Semaphore::new(32)),
        );
        drain.page(key).await;
        drain.page(key).await;
        let (reads, recorded) = drain.finish().await;
        assert_eq!(
            recorded, 0,
            "OVERSIZED META READ: a `.meta` over the {CAP}-byte cap recorded {recorded} access \
             entries; the drain must reject it from its size without reading it"
        );
        assert_eq!(
            reads, 1,
            "OVERSIZED META NOT MEMOISED: two Page records did {reads} `.meta` reads, expected 1"
        );
    }
    /// With every metadata I/O permit held, the drain does not read a `.meta` until one is
    /// released. Red side: the drain's unpermitted read (a lever that skips the permit).
    #[tokio::test]
    async fn the_drain_waits_for_a_metadata_io_permit() {
        let dir = tempfile::TempDir::new().unwrap();
        let key = "test-bucket/permit-test/permit";
        write_meta(dir.path(), &ranged_meta(key));
        let semaphore = Arc::new(tokio::sync::Semaphore::new(1));
        let held = semaphore.clone().acquire_owned().await.unwrap();
        let drain = Drain::start_limited(
            dir.path(),
            Arc::new(FillVisibilityTracker::new(Duration::from_secs(5))),
            4 * 1024 * 1024,
            semaphore,
        );
        drain.page(key).await;
        for _ in 0..20 {
            tokio::time::sleep(Duration::from_millis(25)).await;
            let recorded = drain.buffer.buffer_len().await;
            assert_eq!(
                recorded, 0,
                "UNPERMITTED META READ: the drain recorded {recorded} entries while every \
                 metadata I/O permit was held"
            );
        }
        drop(held);
        let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
        while drain.buffer.buffer_len().await == 0 {
            assert!(
                tokio::time::Instant::now() < deadline,
                "PERMIT WAIT TIMED OUT: the drain recorded nothing within 10s of the permit's \
                 release"
            );
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        let (reads, recorded) = drain.finish().await;
        assert_eq!(
            (reads, recorded),
            (1, 1),
            "one read and one entry after release"
        );
    }

    fn version() -> crate::cache_types::ObjectMetadata {
        crate::cache_types::ObjectMetadata {
            etag: "\"drain\"".to_string(),
            last_modified: "Wed, 21 Oct 2015 07:28:00 GMT".to_string(),
            content_length: 1024,
            ..Default::default()
        }
    }
    /// The Page the tests request (0-1023) and the wider range the tracked fill stores, so a
    /// record of the Page's bounds instead of the stored ones is visible.
    const STORED_END: u64 = 8191;
    /// A fill this instance published for `key` (one stored range, 0-`STORED_END`) and has not
    /// folded: its `.bin` and its fill-visibility entry, stamped against the `.meta` as it
    /// stands now.
    fn tracked_fill(cache_dir: &Path, key: &str) -> Arc<FillVisibilityTracker> {
        let bin = cache_dir.join("drain-fill.bin");
        std::fs::write(&bin, [7u8; 1024]).unwrap();
        let now = SystemTime::now();
        let tracked = crate::cache_types::NewCacheMetadata {
            object_metadata: version(),
            created_at: now,
            expires_at: now + Duration::from_secs(3600),
            ..ranged_meta_to(key, STORED_END)
        };
        let marker = MarkerStamp::of(&paths(cache_dir).get_new_metadata_file_path(key))
            .expect("fixture: the key's write marker is readable");
        let tracker = Arc::new(FillVisibilityTracker::new(Duration::from_secs(5)));
        tracker.record(tracked, vec![RangeFileStamp::of(&bin).unwrap()], marker);
        assert!(
            tracker.lookup(key).is_some(),
            "fixture: the fill must be tracked"
        );
        tracker
    }

    /// A Page hit on a fill with no `.meta` yet is recorded against the fill's stored range, as
    /// the earlier `get_metadata_cached` lookup recorded it. Red side: the earlier drain, which read
    /// only the `.meta` and recorded nothing.
    #[tokio::test]
    async fn a_page_hit_on_a_tracked_fill_with_no_meta_records_the_fills_range() {
        let dir = tempfile::TempDir::new().unwrap();
        let key = "test-bucket/drain/tracked-no-meta";
        let drain = Drain::start_with(dir.path(), tracked_fill(dir.path(), key));
        drain.page(key).await;
        let recorded = drain.finish_bounds().await;
        assert_eq!(
            recorded,
            vec![(0, STORED_END)],
            "FILL-VISIBILITY CASE: a Page hit (0-1023) on a tracked fill with no `.meta` \
             recorded {recorded:?}, expected the fill's stored bounds [(0, {STORED_END})]"
        );
    }

    /// As above beside a HEAD-only `.meta` (no ranges) of the same version, the state an
    /// `aws s3 cp` HEAD-then-GET leaves before the fold.
    #[tokio::test]
    async fn a_page_hit_on_a_tracked_fill_beside_a_head_only_meta_records_the_fills_range() {
        let dir = tempfile::TempDir::new().unwrap();
        let key = "test-bucket/drain/tracked-head-only";
        let now = SystemTime::now();
        write_meta(
            dir.path(),
            &crate::cache_types::NewCacheMetadata {
                cache_key: key.to_string(),
                object_metadata: version(),
                created_at: now,
                expires_at: now + Duration::from_secs(3600),
                ..Default::default()
            },
        );
        let drain = Drain::start_with(dir.path(), tracked_fill(dir.path(), key));
        drain.page(key).await;
        let recorded = drain.finish_bounds().await;
        assert_eq!(
            recorded,
            vec![(0, STORED_END)],
            "FILL-VISIBILITY CASE: a Page hit (0-1023) on a tracked fill beside a HEAD-only \
             `.meta` recorded {recorded:?}, expected the fill's stored bounds [(0, {STORED_END})]"
        );
    }

    /// A key read once is answered from the memo for the whole window and is read again after it.
    /// Red side: `PageExtentMemo::get` never treating an entry as expired.
    #[test]
    fn a_memoised_key_is_not_re_read_within_the_window_and_is_re_read_after_it() {
        let mut memo = PageExtentMemo::default();
        let t0 = std::time::Instant::now();
        assert!(
            memo.get("b/k", t0).is_none(),
            "fixture: a new key is a miss"
        );
        memo.insert("b/k".to_string(), vec![(0, 1023)], t0);
        let just_inside = t0 + RAM_PAGE_EXTENT_MEMO_TTL - Duration::from_millis(1);
        assert_eq!(
            memo.get("b/k", just_inside),
            Some(vec![(0, 1023)]),
            "MEMO MISSED INSIDE THE WINDOW: a key read at t0 must be answered from the memo 1 ms \
             before {RAM_PAGE_EXTENT_MEMO_TTL:?} has passed"
        );
        let at_expiry = t0 + RAM_PAGE_EXTENT_MEMO_TTL;
        assert_eq!(
            memo.get("b/k", at_expiry),
            None,
            "MEMO NEVER EXPIRES: a key read at t0 was still answered from the memo once \
             {RAM_PAGE_EXTENT_MEMO_TTL:?} had passed, so a changed `.meta` would never be re-read"
        );
        assert!(
            memo.get("b/k", just_inside).is_none(),
            "an expired entry is dropped, not kept for a later get"
        );
    }

    /// As above, but the HEAD-only `.meta` is of another version than the tracked fill: disk wins
    /// (`lookup_over_disk_meta` returns `None`), so the fill's range is not recorded and the hit
    /// records nothing.
    #[tokio::test]
    async fn a_page_hit_beside_a_head_only_meta_of_another_version_records_nothing() {
        let dir = tempfile::TempDir::new().unwrap();
        let key = "test-bucket/tracked/tracked-other-version";
        let now = SystemTime::now();
        let mut other = version();
        other.etag = "\"tracked-other\"".to_string();
        write_meta(
            dir.path(),
            &crate::cache_types::NewCacheMetadata {
                cache_key: key.to_string(),
                object_metadata: other,
                created_at: now,
                expires_at: now + Duration::from_secs(3600),
                ..Default::default()
            },
        );
        let drain = Drain::start_with(dir.path(), tracked_fill(dir.path(), key));
        drain.page(key).await;
        // A known Stored hit through the same drain and journal proves the read path is live, so
        // an empty Page result below cannot be an unreadable or renamed journal.
        const SENTINEL: (u64, u64) = (4096, 5119);
        drain
            .tx
            .send(RamAccessRecord::Stored {
                cache_key: "test-bucket/drain-apparatus/sentinel".to_string(),
                stored: vec![SENTINEL],
            })
            .await
            .unwrap();
        let recorded = drain.finish_bounds().await;
        assert!(
            recorded.contains(&SENTINEL),
            "APPARATUS: the sentinel Stored hit {SENTINEL:?} is absent from the journal read \
             ({recorded:?}), so the journal name, instance id or flush path drifted and this \
             test's verdict is UNKNOWN"
        );
        assert_eq!(
            recorded,
            vec![SENTINEL],
            "VERSION MISMATCH IGNORED: a Page hit beside a HEAD-only `.meta` of another version \
             than the tracked fill recorded {recorded:?} besides the sentinel, expected nothing \
             (disk wins)"
        );
    }
}
